/**
 * Seeded PRNG module. All randomness flows through this single source.
 * Math.random() is used ONLY here, as the fallback for generating a fresh seed
 * when ?seed= is absent from the URL.
 */

export interface PRNG {
  /** Returns a float in [0, 1) */
  next(): number;
  /** Returns an integer in [min, max] inclusive */
  nextInt(min: number, max: number): number;
  /** Returns a float in [min, max) */
  nextFloat(min: number, max: number): number;
  /** Clone this PRNG at its current state */
  clone(): PRNG;
  /** Get the original seed */
  readonly seed: number;
}

/** Mulberry32 — a fast, well-distributed 32-bit PRNG */
function mulberry32(seed: number): () => number {
  let state = seed | 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Create a PRNG from a numeric seed */
export function createPRNG(seed: number): PRNG {
  const raw = mulberry32(seed);
  return {
    seed,
    next: () => raw(),
    nextInt(min: number, max: number): number {
      return Math.floor(raw() * (max - min + 1)) + min;
    },
    nextFloat(min: number, max: number): number {
      return raw() * (max - min) + min;
    },
    clone(): PRNG {
      const c = createPRNG(seed);
      // Advance to match current state by replaying — but since mulberry32
      // is stateful via closure, we need a different approach.
      // Instead, store the state directly.
      return createPRNGFromState(state);
    },
  };
}

/** Internal: create PRNG from raw state (for cloning) */
function createPRNGFromState(state: number): PRNG {
  const raw = mulberry32(state);
  return {
    seed: state,
    next: () => raw(),
    nextInt(min: number, max: number): number {
      return Math.floor(raw() * (max - min + 1)) + min;
    },
    nextFloat(min: number, max: number): number {
      return raw() * (max - min) + min;
    },
    clone(): PRNG {
      return createPRNGFromState(state);
    },
  };
}

/** Parse seed from URL query parameter, or generate a fresh one */
export function parseSeedFromURL(url: string): number {
  try {
    const u = new URL(url);
    const s = u.searchParams.get('seed');
    if (s !== null) {
      const parsed = Number(s);
      if (Number.isFinite(parsed)) return parsed;
    }
  } catch {
    // Not a valid URL or no search params
  }
  // Fallback: use Math.random to generate a seed
  // eslint-disable-next-line no-restricted-properties
  return Math.floor(Math.random() * 2147483647);
}

/** Generate a sub-seed deterministically from a parent seed and a tag */
export function subSeed(parent: PRNG, tag: number): number {
  return (parent.seed ^ (tag * 2654435761)) >>> 0;
}

/** Core type definitions shared across the simulation */

export const TICK_RATE = 20; // simulation ticks per second
export const TICK_DT = 1 / TICK_RATE;

export type Faction = 'humans' | 'orcs';

export type TileType =
  | 'grass'
  | 'dirt'
  | 'forest'
  | 'water'
  | 'rock'
  | 'goldMine'
  | 'goldMineDepleted';

export interface Vec2 {
  readonly x: number;
  readonly y: number;
}

export function vec2(x: number, y: number): Vec2 { return { x, y }; }
export function vecEq(a: Vec2, b: Vec2): boolean { return a.x === b.x && a.y === b.y; }
export function vecDist(a: Vec2, b: Vec2): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}
export function vecManhattan(a: Vec2, b: Vec2): number {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
}
export function vecFloor(v: Vec2): Vec2 {
  return { x: Math.floor(v.x), y: Math.floor(v.y) };
}

export type UnitType = 'worker' | 'melee' | 'ranged' | 'heavy';
export type BuildingType = 'townHall' | 'farm' | 'barracks' | 'lumberMill' | 'guardTower';

export interface UnitStats {
  readonly hp: number;
  readonly armor: number;
  readonly damage: number;
  readonly attackRange: number;
  readonly attackCooldown: number; // in ticks
  readonly moveSpeed: number; // tiles per second
  readonly sightRadius: number;
  readonly goldCost: number;
  readonly woodCost: number;
  readonly supplyCost: number;
  readonly trainTime: number; // in ticks
}

export interface BuildingStats {
  readonly hp: number;
  readonly armor: number;
  readonly supplyProvided: number;
  readonly goldCost: number;
  readonly woodCost: number;
  readonly buildTime: number; // in ticks
  readonly width: number;
  readonly height: number;
  readonly sightRadius: number;
}

export interface FactionStats {
  readonly name: string;
  readonly color: string;
  readonly minimapColor: string;
  readonly units: Record<UnitType, UnitStats>;
  readonly buildings: Record<BuildingType, BuildingStats>;
}

export type OrderType =
  | 'idle'
  | 'move'
  | 'attack'
  | 'attackMove'
  | 'harvest'
  | 'build'
  | 'repair'
  | 'gather';

export interface Order {
  readonly type: OrderType;
  readonly target?: Vec2;
  readonly targetId?: number;
  readonly buildType?: BuildingType;
}

export type EntityType = 'unit' | 'building';

export interface Entity {
  readonly id: number;
  readonly faction: Faction;
  readonly entityType: EntityType;
  readonly unitType?: UnitType;
  readonly buildingType?: BuildingType;
  x: number;
  y: number;
