/**
 * Adjacency rules for WFC: for each tile type, the set of tile types
 * that may appear in the 4 cardinal directions (N/E/S/W).
 * Diagonals are checked as both adjacent cardinals must allow the diagonal tile.
 */
export const ADJACENCY: Record<TileType, Set<TileType>> = {
  grass: new Set<TileType>(['grass', 'dirt', 'forest', 'goldMine']),
  dirt: new Set<TileType>(['grass', 'dirt', 'forest', 'goldMine', 'rock']),
  forest: new Set<TileType>(['grass', 'dirt', 'forest']),
  water: new Set<TileType>(['water', 'dirt']),
  rock: new Set<TileType>(['dirt', 'rock']),
  goldMine: new Set<TileType>(['grass', 'dirt']),
  goldMineDepleted: new Set<TileType>(['grass', 'dirt']),
};

/** Check if tileA is allowed adjacent to tileB */
export function tilesAdjacentAllowed(a: TileType, b: TileType): boolean {
  return ADJACENCY[a].has(b);
}

/** Total tile count for array indexing */
export const NUM_TILE_TYPES = 7;

/** Ordered tile type list for iteration */
export const ALL_TILE_TYPES: readonly TileType[] = [
  'grass', 'dirt', 'forest', 'water', 'rock', 'goldMine', 'goldMineDepleted',
] as const;

/**
 * A* pathfinding on a tile grid (8-directional, no corner cutting through blocked diagonals).
 */

import type { Vec2, GameMap } from './types';
import { vecDist } from './types';

interface ANode {
  x: number;
  y: number;
  g: number;
  h: number;
  f: number;
  parent: ANode | null;
}

/** 8-directional neighbors: cardinal + diagonal */
const DIRS: readonly Vec2[] = [
  { x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 },
  { x: 1, y: -1 }, { x: 1, y: 1 }, { x: -1, y: 1 }, { x: -1, y: -1 },
];

function tileIndex(map: GameMap, x: number, y: number): number {
  return y * map.width + x;
}

function inBounds(map: GameMap, x: number, y: number): boolean {
  return x >= 0 && x < map.width && y >= 0 && y < map.height;
}

/**
 * Check if movement from (fx,fy) to (tx,ty) is allowed.
 * Diagonal moves must not cut through blocked corners.
 */
function canMove(map: GameMap, fx: number, fy: number, tx: number, ty: number): boolean {
  if (!inBounds(map, tx, ty)) return false;
  if (!map.walkable[tileIndex(map, tx, ty)]) return false;
  const dx = tx - fx;
  const dy = ty - fy;
  // Diagonal: both adjacent cardinals must be walkable
  if (dx !== 0 && dy !== 0) {
    if (!map.walkable[tileIndex(map, fx + dx, fy)]) return false;
    if (!map.walkable[tileIndex(map, fx, fy + dy)]) return false;
  }
  return true;
}

/** Heuristic: Chebyshev distance (admissible for 8-directional with diagonal cost √2) */
function heuristic(ax: number, ay: number, bx: number, by: number): number {
  const dx = Math.abs(ax - bx);
  const dy = Math.abs(ay - by);
  // Chebyshev: max(dx,dy) + (√2-1)*min(dx,dy) — more accurate than plain max
  const dMin = Math.min(dx, dy);
  const dMax = Math.max(dx, dy);
  return dMax + (Math.SQRT2 - 1) * dMin;
}

/** Find the nearest walkable tile to (tx, ty), searching outward in a spiral */
export function findNearestWalkable(map: GameMap, tx: number, ty: number): Vec2 | null {
  if (inBounds(map, tx, ty) && map.walkable[tileIndex(map, tx, ty)]) {
    return { x: tx, y: ty };
  }
  for (let r = 1; r < Math.max(map.width, map.height); r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
        const nx = tx + dx;
        const ny = ty + dy;
        if (inBounds(map, nx, ny) && map.walkable[tileIndex(map, nx, ny)]) {
          return { x: nx, y: ny };
        }
      }
    }
  }
  return null;
}

/**
 * A* pathfinding.
 * Returns the path as a list of tile centers (excluding the start tile),
 * or null if no path exists.
 */
export function findPath(
  map: GameMap,
  sx: number, sy: number,
  tx: number, ty: number,
  maxNodes: number = 2000,
): Vec2[] | null {
  if (!inBounds(map, sx, sy)) return null;
  if (!inBounds(map, tx, ty)) return null;

  // Find actual walkable target (may be inside a building)
  const actualTarget = findNearestWalkable(map, tx, ty);
  if (!actualTarget) return null;

  const goalX = actualTarget.x;
  const goalY = actualTarget.y;

  if (sx === goalX && sy === goalY) return [];

  const open: ANode[] = [];
  const closed = new Set<number>();

  const startNode: ANode = {
    x: sx, y: sy, g: 0, h: heuristic(sx, sy, goalX, goalY),
    f: heuristic(sx, sy, goalX, goalY), parent: null,
  };
  open.push(startNode);

  let iterations = 0;
  while (open.length > 0 && iterations < maxNodes) {
    iterations++;

    // Find node with lowest f
    let bestIdx = 0;
    for (let i = 1; i < open.length; i++) {
      if (open[i].f < open[bestIdx].f) bestIdx = i;
    }
    const current = open[bestIdx];
    open[bestIdx] = open[open.length - 1];
    open.pop();

    if (current.x === goalX && current.y === goalY) {
      // Reconstruct path
      const path: Vec2[] = [];
      let node: ANode | null = current;
      while (node !== null) {
        path.push({ x: node.x, y: node.y });
        node = node.parent;
      }
      path.reverse();
      return path.slice(1); // Exclude start tile
    }

    const key = tileIndex(map, current.x, current.y);
    if (closed.has(key)) continue;
    closed.add(key);

    for (const dir of DIRS) {
      const nx = current.x + dir.x;
      const ny = current.y + dir.y;
      if (!canMove(map, current.x, current.y, nx, ny)) continue;
      const nkey = tileIndex(map, nx, ny);
      if (closed.has(nkey)) continue;

      const isDiag = dir.x !== 0 && dir.y !== 0;
      const moveCost = isDiag ? Math.SQRT2 : 1;
      const g = current.g + moveCost;

      // Check if already in open with better g
      const existingIdx = open.findIndex(n => n.x === nx && n.y === ny);
      if (existingIdx >= 0 && open[existingIdx].g <= g) continue;

      const h = heuristic(nx, ny, goalX, goalY);
      const node: ANode = { x: nx, y: ny, g, h, f: g + h, parent: current };

      if (existingIdx >= 0) {
        open[existingIdx] = node;
      } else {
        open.push(node);
      }
    }
  }

  return null; // No path found
}

/**
 * Simplified pathfinding that reports only reachable status.
 */
export function isReachable(
  map: GameMap,
  sx: number, sy: number,
  tx: number, ty: number,
): boolean {
  const path = findPath(map, sx, sy, tx, ty, 500);
  return path !== null;
}

/** 8-directional neighbor walkability check (for range queries) */
export function getWalkableNeighbors(map: GameMap, x: number, y: number): Vec2[] {
  const result: Vec2[] = [];
  for (const dir of DIRS) {
    const nx = x + dir.x;
    const ny = y + dir.y;
    if (inBounds(map, nx, ny) && map.walkable[tileIndex(map, nx, ny)]) {
      result.push({ x: nx, y: ny });
    }
  }
  return result;
}

/**
 * Wave Function Collapse map generator.
 * Minimal-entropy cell selection with adjacency-constraint propagation
 * over a weighted tile set.
 */

import type { PRNG } from '../core/prng';
import type { TileType } from '../core/types';
import { ALL_TILE_TYPES, TILE_DEFS, tilesAdjacentAllowed } from '../core/tiles';
import { createPRNG } from '../core/prng';

interface WFCell {
  options: Set<TileType>;
  collapsed: TileType | null;
  entropy: number;
}

interface WFCGrid {
  width: number;
  height: number;
  cells: WFCell[];
}

function cellIndex(grid: WFCGrid, x: number, y: number): number {
  return y * grid.width + x;
}

function inBounds(grid: WFCGrid, x: number, y: number): boolean {
  return x >= 0 && x < grid.width && y >= 0 && y < grid.height;
}

/** Calculate Shannon entropy approximation from tile weights */
function calcEntropy(options: Set<TileType>): number {
  if (options.size <= 1) return 0;
  let sumW = 0;
  let sumWLogW = 0;
  for (const t of options) {
    const w = TILE_DEFS[t].weight;
    if (w <= 0) continue;
    sumW += w;
    sumWLogW += w * Math.log(w);
  }
  if (sumW <= 0) return 0;
  return Math.log(sumW) - sumWLogW / sumW;
}

/** Initialize the grid with all options open */
function initGrid(width: number, height: number): WFCGrid {
  const cells: WFCell[] = [];
  const initialOptions = new Set<TileType>(
    ALL_TILE_TYPES.filter(t => TILE_DEFS[t].weight > 0),
  );
  for (let i = 0; i < width * height; i++) {
    cells.push({
      options: new Set(initialOptions),
      collapsed: null,
      entropy: calcEntropy(initialOptions),
    });
  }
  return { width, height, cells };
}

/** Cardinal + diagonal neighbor offsets */
const NEIGHBOR_DIRS = [
  { x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 },
  { x: 1, y: -1 }, { x: 1, y: 1 }, { x: -1, y: 1 }, { x: -1, y: -1 },
];

/** Get valid options for neighbor given constraints */
function getValidNeighborOptions(
  selfOptions: Set<TileType>,
  neighborX: number,
  neighborY: number,
  selfX: number,
  selfY: number,
  grid: WFCGrid,
): Set<TileType> {
  const valid = new Set<TileType>();
  const dx = neighborX - selfX;
  const dy = neighborY - selfY;
  const isDiag = dx !== 0 && dy !== 0;

  for (const neighborType of ALL_TILE_TYPES) {
    if (TILE_DEFS[neighborType].weight <= 0) continue;
    let allowed = false;
    for (const selfType of selfOptions) {
      if (!tilesAdjacentAllowed(selfType, neighborType)) continue;
      if (isDiag) {
        // Diagonal: check both cardinal intermediates
        const midX1ok = !inBounds(grid, selfX + dx, selfY) ||
          grid.cells[cellIndex(grid, selfX + dx, selfY)].options.has(neighborType) &&
            [...selfOptions].some(s => tilesAdjacentAllowed(s, neighborType));
        const midX2ok = !inBounds(grid, selfX, selfY + dy) ||
          grid.cells[cellIndex(grid, selfX, selfY + dy)].options.has(neighborType) &&
            [...selfOptions].some(s => tilesAdjacentAllowed(s, neighborType));
        if (midX1ok || midX2ok) { allowed = true; break; }
      } else {
        allowed = true;
        break;
      }
    }
    if (allowed) valid.add(neighborType);
  }
  return valid;
}

/** Propagate constraints from a collapsed cell through the grid */
function propagate(grid: WFCGrid, startX: number, startY: number): boolean {
  const stack: Array<{ x: number; y: number }> = [{ x: startX, y: startY }];

  while (stack.length > 0) {
    const { x, y } = stack.pop() as { x: number; y: number };
    const selfCell = grid.cells[cellIndex(grid, x, y)];

    for (const dir of NEIGHBOR_DIRS) {
      const nx = x + dir.x;
      const ny = y + dir.y;
      if (!inBounds(grid, nx, ny)) continue;

      const neighborCell = grid.cells[cellIndex(grid, nx, ny)];
      if (neighborCell.collapsed !== null) continue;

      const validOptions = getValidNeighborOptions(
        selfCell.options, nx, ny, x, y, grid,
      );

      let changed = false;
      for (const opt of neighborCell.options) {
        if (!validOptions.has(opt)) {
          neighborCell.options.delete(opt);
          changed = true;
        }
      }

      if (changed) {
        neighborCell.entropy = calcEntropy(neighborCell.options);
        if (neighborCell.options.size === 0) return false; // contradiction
        stack.push({ x: nx, y: ny });
      }
    }
  }
  return true;
}

/** Pick the uncollapsed cell with minimum entropy */
function pickMinEntropyCell(grid: WFCGrid, rng: PRNG): { x: number; y: number } | null {
  let minEntropy = Infinity;
  let candidates: Array<{ x: number; y: number }> = [];

  for (let y = 0; y < grid.height; y++) {
    for (let x = 0; x < grid.width; x++) {
      const cell = grid.cells[cellIndex(grid, x, y)];
      if (cell.collapsed !== null) continue;
      if (cell.options.size === 0) continue;

      if (cell.entropy < minEntropy - 0.001) {
        minEntropy = cell.entropy;
        candidates = [{ x, y }];
      } else if (Math.abs(cell.entropy - minEntropy) < 0.001) {
        candidates.push({ x, y });
      }
    }
  }

  if (candidates.length === 0) return null;
  return candidates[rng.nextInt(0, candidates.length - 1)];
}

/** Collapse a cell to a weighted random option */
function collapseCell(grid: WFCGrid, x: number, y: number, rng: PRNG): void {
  const cell = grid.cells[cellIndex(grid, x, y)];
  const options = [...cell.options];
  if (options.length === 0) return;

  let totalWeight = 0;
  for (const opt of options) {
    totalWeight += TILE_DEFS[opt].weight;
  }

  let roll = rng.nextFloat(0, totalWeight);
  for (const opt of options) {
    roll -= TILE_DEFS[opt].weight;
    if (roll <= 0) {
      cell.collapsed = opt;
      cell.options = new Set([opt]);
      cell.entropy = 0;
      return;
    }
  }
  // Fallback
  const last = options[options.length - 1];
  cell.collapsed = last;
  cell.options = new Set([last]);
  cell.entropy = 0;
}

/** Force-set a cell to a specific tile type (for repair/constraints) */
function forceCell(grid: WFCGrid, x: number, y: number, tile: TileType): void {
  const cell = grid.cells[cellIndex(grid, x, y)];
  cell.collapsed = tile;
  cell.options = new Set([tile]);
  cell.entropy = 0;
}

/** Run the full WFC algorithm */
export function runWFC(
  width: number,
  height: number,
  rng: PRNG,
): TileType[] {
  const grid = initGrid(width, height);
  let maxIterations = width * height * 10;

  while (maxIterations-- > 0) {
    const pos = pickMinEntropyCell(grid, rng);
    if (!pos) break;

    collapseCell(grid, pos.x, pos.y, rng);
    const ok = propagate(grid, pos.x, pos.y);
    if (!ok) {
      // Contradiction — restart with a new sub-seed
      return runWFC(width, height, createPRNG(rng.nextInt(0, 2147483647)));
    }
  }

  // Fill any remaining uncollapsed cells with grass
  const tiles: TileType[] = [];
  for (let i = 0; i < width * height; i++) {
    const cell = grid.cells[i];
    tiles.push(cell.collapsed ?? 'grass');
  }
  return tiles;
}

/**
 * Post-WFC constraint: add gold mines in clearings near potential start areas.
 * Ensures at least minMines mines exist in the map.
 */
export function ensureGoldMines(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
  minMines: number = 4,
): TileType[] {
  const result = [...tiles];
  let mineCount = result.filter(t => t === 'goldMine').length;

  while (mineCount < minMines) {
    // Find a grass or dirt tile that's not too close to edges
    for (let attempts = 0; attempts < 200 && mineCount < minMines; attempts++) {
      const x = rng.nextInt(3, width - 4);
      const y = rng.nextInt(3, height - 4);
      const idx = y * width + x;
      if (result[idx] !== 'grass' && result[idx] !== 'dirt') continue;

      // Check that surrounding area is mostly walkable
      let clearCount = 0;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          const nx = x + dx;
          const ny = y + dy;
          if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;
          const t = result[ny * width + nx];
          if (t === 'grass' || t === 'dirt') clearCount++;
        }
      }
      if (clearCount >= 15) {
        result[idx] = 'goldMine';
        mineCount++;
      }
    }
    // If we failed to place enough after 200 attempts each iteration,
    // force-place at a known grass tile
    if (mineCount < minMines) {
      for (let y = 5; y < height - 5 && mineCount < minMines; y += 10) {
        for (let x = 5; x < width - 5 && mineCount < minMines; x += 10) {
          const idx = y * width + x;
          if (result[idx] === 'grass' || result[idx] === 'dirt') {
            result[idx] = 'goldMine';
            mineCount++;
          }
        }
      }
      break; // Prevent infinite loop
    }
  }
  return result;
}

/**
 * Ensure forest tiles exist near start areas for wood harvesting.
 */
export function ensureForestNearStarts(
  tiles: TileType[],
  width: number,
  height: number,
  starts: Array<{ x: number; y: number }>,
  rng: PRNG,
): TileType[] {
  const result = [...tiles];
  for (const start of starts) {
    // Place a line of forest within 15 tiles of the start
    let placed = false;
    for (let r = 5; r <= 12; r++) {
      for (let attempts = 0; attempts < 20; attempts++) {
        const angle = rng.nextFloat(0, Math.PI * 2);
        const fx = Math.round(start.x + r * Math.cos(angle));
        const fy = Math.round(start.y + r * Math.sin(angle));
        if (fx < 1 || fx >= width - 1 || fy < 1 || fy >= height - 1) continue;
        const idx = fy * width + fx;
        if (result[idx] !== 'grass' && result[idx] !== 'dirt') continue;
        result[idx] = 'forest';
        placed = true;
        // Place a few more forest tiles nearby for a cluster
        for (let dr = 0; dr < 3; dr++) {
          const ddx = rng.nextInt(-1, 1);
          const ddy = rng.nextInt(-1, 1);
          const nx = fx + ddx;
          const ny = fy + ddy;
          if (nx < 1 || nx >= width - 1 || ny < 1 || ny >= height - 1) continue;
          const nidx = ny * width + nx;
          if (result[nidx] === 'grass' || result[nidx] === 'dirt') {
            result[nidx] = 'forest';
          }
        }
        break;
      }
      if (placed) break;
    }
  }
  return result;
}

/**
 * Map generation: WFC + playability pass + start-location placement.
 * Generates a complete GameMap for a given seed and level.
 */

import type { PRNG } from '../core/prng';
import type { TileType, Vec2, GameMap, Faction, FogState } from '../core/types';
import {
  MIN_START_SEPARATION_RATIO, MIN_START_LINE_SEPARATION_RATIO,
  RESOURCE_REACH_TILES, MIN_BUILD_AREA,
} from '../core/types';
import { vecDist, vecManhattan } from '../core/types';
import { TILE_DEFS } from '../core/tiles';
import { findPath, findNearestWalkable } from '../core/pathfinding';
import { createPRNG, subSeed } from '../core/prng';
import { runWFC, ensureGoldMines, ensureForestNearStarts } from './wfc';

/** Map dimensions per campaign level */
export const LEVEL_MAP_SIZES: ReadonlyArray<{ width: number; height: number }> = [
  { width: 32, height: 32 },
  { width: 48, height: 48 },
  { width: 64, height: 64 },
  { width: 80, height: 80 },
  { width: 96, height: 96 },
];

/** Number of extra water/rock tiles to add per level (higher = more constrained) */
const LEVEL_TERRAIN_ROUGHNESS = [0, 2, 5, 8, 12];

function makeFog(width: number, height: number): FogState[] {
  return new Array<FogState>(width * height).fill('unexplored');
}

function makeWalkable(tiles: TileType[], width: number, height: number): boolean[] {
  const walkable = new Array<boolean>(width * height);
  for (let i = 0; i < tiles.length; i++) {
    walkable[i] = TILE_DEFS[tiles[i]].walkable;
  }
  return walkable;
}

/**
 * Find a contiguous buildable area of at least minSize x minSize tiles
 * starting from (sx, sy). Returns the set of buildable tiles.
 */
function findBuildableArea(
  tiles: TileType[],
  width: number,
  height: number,
  sx: number,
  sy: number,
  minSize: number,
): Vec2[] {
  const area: Vec2[] = [];
  const visited = new Set<number>();

  // BFS from start to find connected buildable tiles
  const queue: Vec2[] = [{ x: sx, y: sy }];
  while (queue.length > 0) {
    const pos = queue.shift() as Vec2;
    const idx = pos.y * width + pos.x;
    if (visited.has(idx)) continue;
    visited.add(idx);

    const tile = tiles[idx];
    if (!TILE_DEFS[tile].buildable) continue;

    area.push(pos);

    // Check 4-cardinal neighbors
    const dirs = [
      { x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 },
    ];
    for (const d of dirs) {
      const nx = pos.x + d.x;
      const ny = pos.y + d.y;
      if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
        queue.push({ x: nx, y: ny });
      }
    }
  }

  return area;
}

/**
 * Check if there's a contiguous buildable area of at least minSize x minSize
 * near the given position.
 */
function hasBuildableArea(
  tiles: TileType[],
  width: number,
  height: number,
  sx: number,
  sy: number,
  minSize: number,
): boolean {
  // Check a region around the start for a buildable area
  const regionSize = minSize + 4;
  let maxContiguous = 0;

  for (let dy = -regionSize; dy <= regionSize; dy++) {
    for (let dx = -regionSize; dx <= regionSize; dx++) {
      const nx = sx + dx;
      const ny = sy + dy;
      if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;

      const area = findBuildableArea(tiles, width, height, nx, ny, minSize);
      if (area.length > maxContiguous) {
        maxContiguous = area.length;
      }
    }
  }

  return maxContiguous >= minSize * minSize;
}

/** Find valid start locations on the map */
function findStartLocations(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
): Vec2[] {
  const starts: Vec2[] = [];
  const maxDim = Math.max(width, height);
  const minSep = Math.floor(maxDim * MIN_START_SEPARATION_RATIO);
  const minLineSep = Math.floor(maxDim * MIN_START_LINE_SEPARATION_RATIO);

  // Try to find two good start locations far apart
  for (let attempt = 0; attempt < 500; attempt++) {
    const x = rng.nextInt(4, width - 5);
    const y = rng.nextInt(4, height - 5);
    const idx = y * width + x;

    if (!TILE_DEFS[tiles[idx]].buildable) continue;

    // Check buildable area
    if (!hasBuildableArea(tiles, width, height, x, y, MIN_BUILD_AREA)) continue;

    if (starts.length === 0) {
      starts.push({ x, y });
    } else {
      const dist = vecDist(starts[0], { x, y });
      const lineDist = vecManhattan(starts[0], { x, y });
      if (dist >= minSep && lineDist >= minLineSep) {
        starts.push({ x, y });
        break;
      }
    }
  }

  // Fallback if we didn't find two good starts
  if (starts.length < 2) {
    const fallback1 = { x: Math.floor(width * 0.2), y: Math.floor(height * 0.2) };
    const fallback2 = { x: Math.floor(width * 0.8), y: Math.floor(height * 0.8) };
    // Find nearest walkable tiles
    const w1 = findNearestWalkable(
      { width, height, tiles, walkable: makeWalkable(tiles, width, height),
        fog: { humans: [], orcs: [] }, startLocations: { humans: fallback1, orcs: fallback2 }, level: 0 },
      fallback1.x, fallback1.y,
    ) ?? fallback1;
    const w2 = findNearestWalkable(
      { width, height, tiles, walkable: makeWalkable(tiles, width, height),
        fog: { humans: [], orcs: [] }, startLocations: { humans: fallback1, orcs: fallback2 }, level: 0 },
      fallback2.x, fallback2.y,
    ) ?? fallback2;
    starts.length = 0;
    starts.push(w1, w2);
  }

  return starts;
}

/** Add water/rock constraints to the map for harder levels */
function constrainTerrain(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
  roughness: number,
): TileType[] {
  const result = [...tiles];
  for (let i = 0; i < roughness; i++) {
    const x = rng.nextInt(2, width - 3);
    const y = rng.nextInt(2, height - 3);
    const idx = y * width + x;
    if (result[idx] === 'grass' || result[idx] === 'dirt') {
      result[idx] = rng.next() < 0.5 ? 'water' : 'rock';
    }
  }
  return result;
}

/**
 * Carve a land corridor between two points to guarantee reachability.
 */
function carveCorridor(
  tiles: TileType[],
  width: number,
  height: number,
  from: Vec2,
  to: Vec2,
): TileType[] {
  const result = [...tiles];
  let cx = from.x;
  let cy = from.y;

  while (cx !== to.x || cy !== to.y) {
    const idx = cy * width + cx;
    if (result[idx] === 'water' || result[idx] === 'rock') {
      result[idx] = 'grass';
    }

    if (cx < to.x) cx++;
    else if (cx > to.x) cx--;
    if (cy < to.y) cy++;
    else if (cy > to.y) cy--;
  }
  // Also clear the destination
  const toIdx = to.y * width + to.x;
  if (result[toIdx] === 'water' || result[toIdx] === 'rock') {
    result[toIdx] = 'grass';
  }

  return result;
}

/**
 * Generate a complete map for a campaign level.
 */
export function generateMap(
  seed: number,
  level: number,
): GameMap {
  const size = LEVEL_MAP_SIZES[level] ?? LEVEL_MAP_SIZES[0];
  const { width, height } = size;
  const mapSeed = (seed * 31 + level * 17) >>> 0;
  const rng = createPRNG(mapSeed);

  // Generate base terrain with WFC
  let tiles = runWFC(width, height, rng);

  // Add terrain constraints for harder levels
  const roughness = LEVEL_TERRAIN_ROUGHNESS[level] ?? 0;
  tiles = constrainTerrain(tiles, width, height, rng, roughness);

  // Find start locations
  let starts = findStartLocations(tiles, width, height, rng);

  // Ensure reachability between starts
  if (starts.length >= 2) {
    tiles = carveCorridor(tiles, width, height, starts[0], starts[1]);
  }

  // Ensure resources near starts
  tiles = ensureGoldMines(tiles, width, height, rng, 4 + level);
  tiles = ensureForestNearStarts(tiles, width, height, starts, rng);

  // Make walkable array
  const walkable = makeWalkable(tiles, width, height);

  // Create fog arrays
  const fog: Record<Faction, FogState[]> = {
    humans: makeFog(width, height),
    orcs: makeFog(width, height),
  };

  // Set start locations
  const startLocations: Record<Faction, Vec2> = {
    humans: starts[0] ?? { x: 5, y: 5 },
    orcs: starts[1] ?? { x: width - 6, y: height - 6 },
  };

  return {
    width,
    height,
    tiles,
    walkable,
    fog,
    startLocations,
    level,
  };
}

/**
 * Update walkable array based on building positions.
 * Buildings occupy tiles and block movement.
 */
export function updateWalkableForBuildings(
  map: GameMap,
  buildingFootprints: Array<{ x: number; y: number; w: number; h: number }>,
): boolean[] {
  const walkable = makeWalkable(map.tiles, map.width, map.height);

  for (const bp of buildingFootprints) {
    for (let dy = 0; dy < bp.h; dy++) {
      for (let dx = 0; dx < bp.w; dx++) {
        const tx = bp.x + dx;
        const ty = bp.y + dy;
        if (tx >= 0 && tx < map.width && ty >= 0 && ty < map.height) {
          walkable[ty * map.width + tx] = false;
        }
      }
    }
  }

  return walkable;
}

/**
 * Entity management: creation, lookup, and basic operations.
 */

import type {
  Entity, Faction, UnitType, BuildingType, GameState, Vec2,
} from '../core/types';
import { FACTION_STATS, TOWER_ATTACK_DAMAGE, TOWER_ATTACK_RANGE, TOWER_ATTACK_COOLDOWN } from '../core/stats';

/** Create a unit entity */
export function createUnit(
  state: GameState,
  faction: Faction,
  unitType: UnitType,
  x: number,
  y: number,
): Entity {
  const stats = FACTION_STATS[faction].units[unitType];
  const entity: Entity = {
    id: state.nextEntityId++,
    faction,
    entityType: 'unit',
    unitType,
    x,
    y,
    hp: stats.hp,
    maxHp: stats.hp,
    armor: stats.armor,
    damage: stats.damage,
    attackRange: stats.attackRange,
    attackCooldown: stats.attackCooldown,
    attackCooldownTimer: 0,
    moveSpeed: stats.moveSpeed,
    sightRadius: stats.sightRadius,
    order: { type: 'idle' },
    path: [],
    pathIndex: 0,
    cargoGold: 0,
    cargoWood: 0,
    progressTicks: 0,
    progressTotal: 0,
    width: 1,
    height: 1,
    alive: true,
  };
  state.entities.push(entity);
  return entity;
}

/** Create a building entity */
export function createBuilding(
  state: GameState,
  faction: Faction,
  buildingType: BuildingType,
  x: number,
  y: number,
  isConstruction: boolean = false,
): Entity {
  const stats = FACTION_STATS[faction].buildings[buildingType];
  const entity: Entity = {
    id: state.nextEntityId++,
    faction,
    entityType: 'building',
    buildingType,
    x,
    y,
    hp: isConstruction ? 1 : stats.hp,
    maxHp: stats.hp,
    armor: stats.armor,
    damage: buildingType === 'guardTower' ? TOWER_ATTACK_DAMAGE : 0,
    attackRange: buildingType === 'guardTower' ? TOWER_ATTACK_RANGE : 0,
    attackCooldown: buildingType === 'guardTower' ? TOWER_ATTACK_COOLDOWN : 0,
    attackCooldownTimer: 0,
    moveSpeed: 0,
    sightRadius: stats.sightRadius,
    order: { type: 'idle' },
    path: [],
    pathIndex: 0,
    cargoGold: 0,
    cargoWood: 0,
    progressTicks: 0,
    progressTotal: isConstruction ? stats.buildTime : 0,
    width: stats.width,
    height: stats.height,
    alive: true,
  };
  state.entities.push(entity);

  // Update supply cap
  if (stats.supplyProvided > 0) {
    state.supplyCap[faction] += stats.supplyProvided;
  }

  // Update walkable
  if (!isConstruction) {
    markBuildingTiles(state, entity, false);
  }

  return entity;
}

/** Mark building footprint tiles as walkable/unwalkable */
function markBuildingTiles(state: GameState, building: Entity, walkable: boolean): void {
  const map = state.map;
  for (let dy = 0; dy < building.height; dy++) {
    for (let dx = 0; dx < building.width; dx++) {
      const tx = building.x + dx;
      const ty = building.y + dy;
      if (tx >= 0 && tx < map.width && ty >= 0 && ty < map.height) {
        map.walkable[ty * map.width + tx] = walkable;
      }
    }
  }
}

/** Get entity by ID */
export function getEntity(state: GameState, id: number): Entity | undefined {
  return state.entities.find(e => e.id === id && e.alive);
}

/** Get all entities of a faction */
export function getFactionEntities(state: GameState, faction: Faction): Entity[] {
  return state.entities.filter(e => e.faction === faction && e.alive);
}

/** Get entities within a radius of a point */
export function getEntitiesInRange(
  state: GameState,
  center: Vec2,
  radius: number,
  faction?: Faction,
): Entity[] {
  const r2 = radius * radius;
  return state.entities.filter(e => {
    if (!e.alive) return false;
    if (faction !== undefined && e.faction !== faction) return false;
    const dx = e.x - center.x;
    const dy = e.y - center.y;
    return dx * dx + dy * dy <= r2;
  });
}

/** Get the center of a building (for pathfinding targets) */
export function buildingCenter(e: Entity): Vec2 {
  return {
    x: e.x + e.width / 2 - 0.5,
    y: e.y + e.height / 2 - 0.5,
  };
}

/** Get building footprint as an array of tile positions */
export function buildingFootprint(e: Entity): Vec2[] {
  const tiles: Vec2[] = [];
  for (let dy = 0; dy < e.height; dy++) {
    for (let dx = 0; dx < e.width; dx++) {
      tiles.push({ x: e.x + dx, y: e.y + dy });
    }
  }
  return tiles;
}

/** Check if a point is inside a building's footprint */
export function pointInBuilding(e: Entity, px: number, py: number): boolean {
  return px >= e.x && px < e.x + e.width && py >= e.y && py < e.y + e.height;
}

/** Kill an entity and handle side effects */
export function killEntity(state: GameState, entity: Entity): void {
  entity.alive = false;

  if (entity.entityType === 'building' && entity.buildingType) {
    const stats = FACTION_STATS[entity.faction].buildings[entity.buildingType];
    if (stats.supplyProvided > 0) {
      state.supplyCap[entity.faction] -= stats.supplyProvided;
      // Ensure supply cap doesn't go below used
      if (state.supplyCap[entity.faction] < state.supplyUsed[entity.faction]) {
        // Supply can temporarily exceed cap — new training is blocked
      }
    }
    // Mark tiles as walkable again
    markBuildingTiles(state, entity, true);
  }
}

/** Get all buildings of a faction that are drop-off points for a resource */
export function getDropOffs(state: GameState, faction: Faction, resource: 'gold' | 'wood'): Entity[] {
  return state.entities.filter(e => {
    if (!e.alive || e.faction !== faction || e.entityType !== 'building') return false;
    if (e.entityType === 'building' && e.buildingType) {
      if (resource === 'gold') return e.buildingType === 'townHall';
      if (resource === 'wood') return e.buildingType === 'townHall' || e.buildingType === 'lumberMill';
    }
    return false;
  });
}

/** Get the nearest reachable drop-off for a worker */
export function findNearestDropOff(
  state: GameState,
  faction: Faction,
  resource: 'gold' | 'wood',
  fromX: number,
  fromY: number,
): Entity | null {
  const dropoffs = getDropOffs(state, faction, resource);
  if (dropoffs.length === 0) return null;

  let bestDist = Infinity;
  let best: Entity | null = null;
  for (const d of dropoffs) {
    const center = buildingCenter(d);
    const dist = Math.abs(center.x - fromX) + Math.abs(center.y - fromY);
    if (dist < bestDist) {
      bestDist = dist;
      best = d;
    }
  }
  return best;
}

/** Check if a faction has any buildings left */
export function hasBuildings(state: GameState, faction: Faction): boolean {
  return state.entities.some(e =>
    e.alive && e.faction === faction && e.entityType === 'building',
  );
}

/** Check if the player has the tech requirements for a unit or building */
export function hasTechRequirements(state: GameState, faction: Faction, reqs: BuildingType[]): boolean {
  for (const req of reqs) {
    const has = state.entities.some(e =>
      e.alive && e.faction === faction && e.entityType === 'building' &&
      e.buildingType === req,
    );
    if (!has) return false;
  }
  return true;
}

/** Get the town hall of a faction */
export function getTownHall(state: GameState, faction: Faction): Entity | undefined {
  return state.entities.find(e =>
    e.alive && e.faction === faction && e.entityType === 'building' &&
    e.buildingType === 'townHall',
  );
}

/**
 * Movement system: pathfinding, path following, collision avoidance.
 */

import type { Entity, GameState, Vec2 } from '../core/types';
import { vecDist } from '../core/types';
import { findPath } from '../core/pathfinding';
import { buildingCenter } from './entities';

/** The collision radius for units (half tile-width) */
const UNIT_RADIUS = 0.25;
/** How close two units may get before collision avoidance kicks in */
const MIN_SEPARATION = 0.5;
/** Maximum ticks to wait before re-evaluating path */
const WAIT_TICKS_BEFORE_REPATH = 30;
/** Maximum consecutive repath attempts before giving up */
const MAX_REPATH_ATTEMPTS = 5;

/**
 * Assign a move order to an entity, computing a path.
 */
export function assignMoveOrder(
  state: GameState,
  entity: Entity,
  targetX: number,
  targetY: number,
): void {
  const tx = Math.floor(targetX);
  const ty = Math.floor(targetY);
  const sx = Math.floor(entity.x);
  const sy = Math.floor(entity.y);

  const path = findPath(state.map, sx, sy, tx, ty);
  entity.order = { type: 'move', target: { x: targetX, y: targetY } };
  entity.path = path ?? [];
  entity.pathIndex = 0;
  entity.progressTicks = 0;
}

/**
 * Assign a harvest order: walk to resource, gather, carry to drop-off, repeat.
 */
export function assignHarvestOrder(
  state: GameState,
  entity: Entity,
  targetId: number,
): void {
  entity.order = { type: 'harvest', targetId };
  entity.path = [];
  entity.pathIndex = 0;
  entity.progressTicks = 0;
  entity.cargoGold = 0;
  entity.cargoWood = 0;
}

/**
 * Process movement for all moving entities in the current tick.
 * Handles path following, collision avoidance, and progress tracking.
 */
export function processMovement(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive) continue;
    if (entity.entityType !== 'unit') continue;
    if (entity.order.type === 'idle') continue;
    if (entity.isProjectile) continue;
    if (entity.moveSpeed <= 0) continue;

    // Handle path following
    if (entity.path.length > 0 && entity.pathIndex < entity.path.length) {
      followPath(state, entity);
    }
  }
}

/**
 * Move an entity along its path.
 */
function followPath(state: GameState, entity: Entity): void {
  const target = entity.path[entity.pathIndex];
  if (!target) return;

  const dx = target.x - entity.x;
  const dy = target.y - entity.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  if (dist < 0.1) {
    // Arrived at this waypoint
    entity.x = target.x;
    entity.y = target.y;
    entity.pathIndex++;
    entity.progressTicks = 0;
    return;
  }

  // Calculate movement for this tick
  const speed = entity.moveSpeed / 20; // tiles per tick
  const moveX = (dx / dist) * Math.min(speed, dist);
  const moveY = (dy / dist) * Math.min(speed, dist);

  // Check for collisions with other units
  const newX = entity.x + moveX;
  const newY = entity.y + moveY;

  if (canMoveTo(state, entity, newX, newY)) {
    entity.x = newX;
    entity.y = newY;
    entity.progressTicks = 0;
  } else {
    // Collision — try to find alternative route
    entity.progressTicks++;
    if (entity.progressTicks > WAIT_TICKS_BEFORE_REPATH) {
      // Try to re-route around
      repathEntity(state, entity);
    }
  }
}

/**
 * Check if an entity can move to a position without collision.
 */
function canMoveTo(state: GameState, entity: Entity, newX: number, newY: number): boolean {
  // Check map bounds
  if (newX < 0 || newX >= state.map.width || newY < 0 || newY >= state.map.height) {
    return false;
  }

  // Check walkability
  const tx = Math.floor(newX);
  const ty = Math.floor(newY);
  if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) {
    return false;
  }
  if (!state.map.walkable[ty * state.map.width + tx]) {
    return false;
  }

  // Check collision with other units
  for (const other of state.entities) {
    if (!other.alive || other.id === entity.id) continue;
    if (other.entityType !== 'unit') continue;
    if (other.isProjectile) continue;

    const dx = newX - other.x;
    const dy = newY - other.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < MIN_SEPARATION) {
      return false;
    }
  }

  return true;
}

/**
 * Re-route an entity that's stuck.
 */
function repathEntity(state: GameState, entity: Entity): void {
  const target = entity.order.target;
  if (!target) {
    entity.order = { type: 'idle' };
    entity.path = [];
    return;
  }

  const sx = Math.floor(entity.x);
  const sy = Math.floor(entity.y);
  const tx = Math.floor(target.x);
  const ty = Math.floor(target.y);

  const path = findPath(state.map, sx, sy, tx, ty);
  if (path && path.length > 0) {
    entity.path = path;
    entity.pathIndex = 0;
    entity.progressTicks = 0;
  } else {
    // Can't find path — cancel order
    entity.order = { type: 'idle' };
    entity.path = [];
  }
}

/**
 * Check if two entities are colliding.
 */
export function areEntitiesColliding(a: Entity, b: Entity): boolean {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy) < MIN_SEPARATION;
}

/**
 * Get all units currently colliding with the given entity.
 */
export function getCollisions(state: GameState, entity: Entity): Entity[] {
  return state.entities.filter(e =>
    e.alive && e.id !== entity.id && e.entityType === 'unit' && !e.isProjectile &&
    areEntitiesColliding(entity, e),
  );
}

/**
 * Combat system: attack orders, projectiles, damage calculation.
 */

import type { Entity, GameState } from '../core/types';
import { vecDist } from '../core/types';
import { killEntity, buildingCenter } from './entities';

/** Projectile speed in tiles per tick */
const PROJECTILE_SPEED = 0.3;

/**
 * Process combat for all entities.
 * Handles attack cooldowns, auto-acquisition, and attacks.
 */
export function processCombat(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive) continue;
    if (entity.attackCooldownTimer > 0) {
      entity.attackCooldownTimer--;
    }

    // Process projectiles
    if (entity.isProjectile) {
      processProjectile(state, entity);
      continue;
    }

    // Process towers
    if (entity.entityType === 'building' && entity.buildingType === 'guardTower') {
      processTowerCombat(state, entity);
      continue;
    }

    // Process unit combat
    if (entity.entityType !== 'unit') continue;

    // Auto-acquire targets for idle/guarding units
    if (entity.order.type === 'idle' || entity.order.type === 'attack') {
      const target = findAutoTarget(state, entity);
      if (target) {
        entity.order = { type: 'attack', targetId: target.id };
      }
    }

    // Execute attack order
    if (entity.order.type === 'attack' && entity.order.targetId !== undefined) {
      executeAttackOrder(state, entity);
    }

    // Attack-move: find and attack enemies while moving
    if (entity.order.type === 'attackMove') {
      const target = findAutoTarget(state, entity);
      if (target) {
        entity.order = { type: 'attack', targetId: target.id };
      } else if (entity.path.length === 0 && entity.order.target) {
        // Continue moving to destination
        assignMoveOrder(state, entity, entity.order.target.x, entity.order.target.y);
      }
    }
  }
}

/**
 * Process tower combat: auto-attack enemies in range.
 */
function processTowerCombat(state: GameState, tower: Entity): void {
  if (tower.attackCooldownTimer > 0) return;

  // Find nearest enemy in range
  let bestTarget: Entity | null = null;
  let bestDist = Infinity;

  for (const entity of state.entities) {
    if (!entity.alive || entity.faction === tower.faction) continue;
    if (entity.entityType === 'building' && entity.buildingType) {
      // Towers don't attack buildings
      continue;
    }

    const dist = vecDist(buildingCenter(tower), entity);
    if (dist <= tower.attackRange && dist < bestDist) {
      bestDist = dist;
      bestTarget = entity;
    }
  }

  if (bestTarget) {
    spawnProjectile(state, tower, bestTarget);
    tower.attackCooldownTimer = tower.attackCooldown;
  }
}

/**
 * Find a valid auto-target for a unit.
 */
function findAutoTarget(state: GameState, unit: Entity): Entity | null {
  let bestTarget: Entity | null = null;
  let bestDist = Infinity;

  for (const entity of state.entities) {
    if (!entity.alive || entity.faction === unit.faction) continue;

    const dist = vecDist(unit, entity);
    if (dist <= unit.sightRadius && dist < bestDist) {
      bestDist = dist;
      bestTarget = entity;
    }
  }

  return bestTarget;
}

/**
 * Execute an attack order.
 */
function executeAttackOrder(state: GameState, attacker: Entity): void {
  const targetId = attacker.order.targetId;
  if (targetId === undefined) return;

  const target = state.entities.find(e => e.id === targetId && e.alive);
  if (!target) {
    // Target is dead — go idle
    attacker.order = { type: 'idle' };
    attacker.path = [];
    return;
  }

  const targetPos = target.entityType === 'building' ? buildingCenter(target) : target;
  const dist = vecDist(attacker, targetPos);

  if (dist <= attacker.attackRange) {
    // In range — attack
    if (attacker.attackCooldownTimer <= 0) {
      performAttack(state, attacker, target);
      attacker.attackCooldownTimer = attacker.attackCooldown;
    }
  } else {
    // Move to target
    if (attacker.path.length === 0 || attacker.pathIndex >= attacker.path.length) {
      const path = findPath(state.map, Math.floor(attacker.x), Math.floor(attacker.y),
        Math.floor(targetPos.x), Math.floor(targetPos.y));
      attacker.path = path ?? [];
      attacker.pathIndex = 0;
    }
  }
}

import { findPath } from '../core/pathfinding';

/**
 * Perform an attack: damage the target, potentially kill it.
 */
function performAttack(state: GameState, attacker: Entity, target: Entity): void {
  // Spawn projectile for ranged attacks
  if (attacker.attackRange > 1) {
    spawnProjectile(state, attacker, target);
    return;
  }

  // Melee attack — apply damage immediately
  const damage = Math.max(1, attacker.damage - target.armor);
  target.hp -= damage;

  if (target.hp <= 0) {
    killEntity(state, target);
  }
}

/**
 * Spawn a projectile.
 */
function spawnProjectile(state: GameState, attacker: Entity, target: Entity): void {
  const targetPos = target.entityType === 'building' ? buildingCenter(target) : target;

  const projectile: Entity = {
    id: state.nextEntityId++,
    faction: attacker.faction,
    entityType: 'unit',
    x: attacker.x,
    y: attacker.y,
    hp: 1,
    maxHp: 1,
    armor: 0,
    damage: 0,
    attackRange: 0,
    attackCooldown: 0,
    attackCooldownTimer: 0,
    moveSpeed: 0,
    sightRadius: 0,
    order: { type: 'idle' },
    path: [],
    pathIndex: 0,
    cargoGold: 0,
    cargoWood: 0,
    progressTicks: 0,
    progressTotal: 0,
    width: 1,
    height: 1,
    alive: true,
    isProjectile: true,
    projectileTargetId: target.id,
    projectileDamage: Math.max(1, attacker.damage - target.armor),
    projectileSpeed: PROJECTILE_SPEED,
  };

  state.entities.push(projectile);
}

/**
 * Process a projectile's movement and impact.
 */
function processProjectile(state: GameState, projectile: Entity): void {
  if (!projectile.isProjectile || projectile.projectileTargetId === undefined) {
    killEntity(state, projectile);
    return;
  }

  const target = state.entities.find(e => e.id === projectile.projectileTargetId);
  if (!target || !target.alive) {
    killEntity(state, projectile);
    return;
  }

  const targetPos = target.entityType === 'building' ? buildingCenter(target) : target;
  const dx = targetPos.x - projectile.x;
  const dy = targetPos.y - projectile.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  if (dist < 0.2) {
    // Hit!
    const damage = projectile.projectileDamage ?? 1;
    target.hp -= damage;
    if (target.hp <= 0) {
      killEntity(state, target);
    }
    killEntity(state, projectile);
    return;
  }

  // Move toward target
  const speed = projectile.projectileSpeed ?? PROJECTILE_SPEED;
  projectile.x += (dx / dist) * speed;
  projectile.y += (dy / dist) * speed;
}

/**
 * Economy system: harvesting gold and wood, resource management.
 */

import type { Entity, GameState, Faction } from '../core/types';
import {
  WORKER_CARRY_GOLD, WORKER_CARRY_WOOD, WORKER_HARVEST_TICKS,
  GOLD_MINE_AMOUNT,
} from '../core/types';
import { TILE_DEFS } from '../core/tiles';
import { findNearestDropOff, getTownHall } from './entities';
import { findPath } from '../core/pathfinding';
import { vecDist } from '../core/types';

/**
 * Process harvesting for all workers with harvest orders.
 * Handles the full harvest cycle: walk to resource, gather, carry to drop-off, return.
 */
export function processHarvesting(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'unit') continue;
    if (entity.order.type !== 'harvest') continue;
    if (entity.unitType !== 'worker') continue;

    processWorkerHarvest(state, entity);
  }
}

/**
 * Process a single worker's harvest cycle.
 * The worker alternates between: walking to resource, gathering, walking to drop-off, delivering.
 */
function processWorkerHarvest(state: GameState, worker: Entity): void {
  const targetId = worker.order.targetId;
  if (targetId === undefined) {
    worker.order = { type: 'idle' };
    return;
  }

  // Find the target resource (could be a building like gold mine, or a tile like forest)
  const target = state.entities.find(e => e.id === targetId && e.alive);

  if (worker.cargoGold > 0 || worker.cargoWood > 0) {
    // Worker is carrying — deliver to drop-off
    processDeliver(state, worker);
    return;
  }

  if (!target) {
    // Target is gone — find another resource
    findNewResource(state, worker);
    return;
  }

  // Check if we're at the resource
  const dist = vecDist(worker, target.entityType === 'building' ?
    { x: target.x + target.width / 2, y: target.y + target.height / 2 } : target);

  if (dist < 2) {
    // At resource — gather
    worker.progressTicks++;
    if (worker.progressTicks >= WORKER_HARVEST_TICKS) {
      // Gathered!
      worker.progressTicks = 0;
      if (target.buildingType === 'goldMine') {
        worker.cargoGold = Math.min(WORKER_CARRY_GOLD, target.hp);
        // Reduce mine amount (using HP as a proxy for remaining gold)
        target.hp -= worker.cargoGold;
        if (target.hp <= 0) {
          // Mine depleted — transform to depleted tile
          const tx = Math.floor(target.x);
          const ty = Math.floor(target.y);
          state.map.tiles[ty * state.map.width + tx] = 'goldMineDepleted';
          state.map.walkable[ty * state.map.width + tx] = TILE_DEFS.goldMineDepleted.walkable;
          target.alive = false;
        }
      } else {
        // Wood harvesting
        worker.cargoWood = WORKER_CARRY_WOOD;
        // Forest tile depletion — reduce HP
        target.hp -= 10;
        if (target.hp <= 0) {
          // Tile depleted — transform to dirt
          const tx = Math.floor(target.x);
          const ty = Math.floor(target.y);
          state.map.tiles[ty * state.map.width + tx] = 'dirt';
          state.map.walkable[ty * state.map.width + tx] = TILE_DEFS.dirt.walkable;
          target.alive = false;
        }
      }
      // Set state to delivering
      worker.harvestTarget = targetId;
    }
  } else {
    // Move to resource
    if (worker.path.length === 0 || worker.pathIndex >= worker.path.length) {
      const tx = Math.floor(target.x);
      const ty = Math.floor(target.y);
      const path = findPath(state.map, Math.floor(worker.x), Math.floor(worker.y), tx, ty);
      if (path && path.length > 0) {
        worker.path = path;
        worker.pathIndex = 0;
      } else {
        // Can't reach resource — find another
        findNewResource(state, worker);
      }
    }
  }
}

/**
 * Process delivering resources to a drop-off.
 */
function processDeliver(state: GameState, worker: Entity): void {
  const dropoff = findNearestDropOff(state, worker.faction,
    worker.cargoGold > 0 ? 'gold' : 'wood',
    worker.x, worker.y);

  if (!dropoff) {
    // No drop-off — go idle
    worker.order = { type: 'idle' };
    worker.cargoGold = 0;
    worker.cargoWood = 0;
    return;
  }

  const center = { x: dropoff.x + dropoff.width / 2, y: dropoff.y + dropoff.height / 2 };
  const dist = vecDist(worker, center);

  if (dist < 2) {
    // At drop-off — deliver
    state.resources[worker.faction].gold += worker.cargoGold;
    state.resources[worker.faction].wood += worker.cargoWood;
    worker.cargoGold = 0;
    worker.cargoWood = 0;

    // Return to harvest
    if (worker.harvestTarget !== undefined) {
      const target = state.entities.find(e => e.id === worker.harvestTarget && e.alive);
      if (target) {
        worker.order = { type: 'harvest', targetId: worker.harvestTarget };
        worker.path = [];
        worker.pathIndex = 0;
        worker.progressTicks = 0;
        return;
      }
    }
    // Find new resource
    findNewResource(state, worker);
  } else {
    // Move to drop-off
    if (worker.path.length === 0 || worker.pathIndex >= worker.path.length) {
      const path = findPath(state.map, Math.floor(worker.x), Math.floor(worker.y),
        Math.floor(center.x), Math.floor(center.y));
      if (path && path.length > 0) {
        worker.path = path;
        worker.pathIndex = 0;
      } else {
        // Can't reach drop-off — try another
        worker.order = { type: 'idle' };
        worker.cargoGold = 0;
        worker.cargoWood = 0;
      }
    }
  }
}

/**
 * Find a new resource for a worker to harvest.
 */
function findNewResource(state: GameState, worker: Entity): void {
  // Look for nearest gold mine or forest tile
  let bestTarget: Entity | null = null;
  let bestDist = Infinity;

  for (const entity of state.entities) {
    if (!entity.alive || entity.faction !== worker.faction) continue;
    if (entity.entityType !== 'building' || entity.buildingType !== 'goldMine') continue;

    const dist = vecDist(worker, entity);
    if (dist < bestDist) {
      bestDist = dist;
      bestTarget = entity;
    }
  }

  if (bestTarget) {
    worker.order = { type: 'harvest', targetId: bestTarget.id };
    worker.harvestTarget = bestTarget.id;
    worker.path = [];
    worker.pathIndex = 0;
    worker.progressTicks = 0;
  } else {
    // No resources — go idle
    worker.order = { type: 'idle' };
  }
}

/**
 * Check if a tile has a forest resource.
 */
export function isForestTile(state: GameState, x: number, y: number): boolean {
  const tx = Math.floor(x);
  const ty = Math.floor(y);
  if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) return false;
  return state.map.tiles[ty * state.map.width + tx] === 'forest';
}

/**
 * Create a forest entity for harvesting.
 */
export function createForestEntity(state: GameState, x: number, y: number): Entity {
  const entity: Entity = {
    id: state.nextEntityId++,
    faction: 'humans', // Forest is neutral but we need a faction
    entityType: 'building',
    buildingType: 'farm', // Using as placeholder
    x,
    y,
    hp: 200, // Forest health
    maxHp: 200,
    armor: 0,
    damage: 0,
    attackRange: 0,
    attackCooldown: 0,
    attackCooldownTimer: 0,
    moveSpeed: 0,
    sightRadius: 0,
    order: { type: 'idle' },
    path: [],
    pathIndex: 0,
    cargoGold: 0,
    cargoWood: 0,
    progressTicks: 0,
    progressTotal: 0,
    width: 1,
    height: 1,
    alive: true,
  };
  state.entities.push(entity);
  return entity;
}

/**
 * Fog of war system: three states per tile (unexplored, explored, visible).
 */

import type { GameState, Faction, FogState, Entity } from '../core/types';

/**
 * Update fog of war for a faction based on their units' sight radii.
 */
export function updateFog(state: GameState, faction: Faction): void {
  const fog = state.map.fog[faction];

  // First, downgrade all 'visible' to 'explored'
  for (let i = 0; i < fog.length; i++) {
    if (fog[i] === 'visible') {
      fog[i] = 'explored';
    }
  }

  // Then, mark tiles visible from each entity's sight
  for (const entity of state.entities) {
    if (!entity.alive || entity.faction !== faction) continue;
    if (entity.sightRadius <= 0) continue;

    const cx = Math.floor(entity.x);
    const cy = Math.floor(entity.y);
    const r = entity.sightRadius;

    for (let dy = -r; dy <= r; dy++) {
      for (let dx = -r; dx <= r; dx++) {
        const tx = cx + dx;
        const ty = cy + dy;
        if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) continue;

        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist <= r) {
          const idx = ty * state.map.width + tx;
          fog[idx] = 'visible';
        }
      }
    }
  }
}

/**
 * Get the fog state for a tile.
 */
export function getFogState(state: GameState, faction: Faction, x: number, y: number): FogState {
  const tx = Math.floor(x);
  const ty = Math.floor(y);
  if (tx < 0 || tx >= state.map.width || ty < 0 || ty >= state.map.height) {
    return 'unexplored';
  }
  return state.map.fog[faction][ty * state.map.width + tx];
}

/**
 * Check if an entity is visible to a faction.
 */
export function isVisible(state: GameState, faction: Faction, entity: Entity): boolean {
  const fog = getFogState(state, faction, entity.x, entity.y);
  return fog === 'visible';
}

/**
 * Check if a tile is visible to a faction.
 */
export function isTileVisible(state: GameState, faction: Faction, x: number, y: number): boolean {
  return getFogState(state, faction, x, y) === 'visible';
}

/**
 * Check if a tile has been explored by a faction.
 */
export function isTileExplored(state: GameState, faction: Faction, x: number, y: number): boolean {
  const fog = getFogState(state, faction, x, y);
  return fog === 'explored' || fog === 'visible';
}

/**
 * Get all visible entities for a faction.
 */
export function getVisibleEntities(state: GameState, faction: Faction): Entity[] {
  return state.entities.filter(e => {
    if (!e.alive) return false;
    if (e.faction === faction) return true; // Own units always visible
    return isVisible(state, faction, e);
  });
}

/**
 * Get a snapshot of visible state for rendering.
 * Returns only what the player faction can see.
 */
export function getVisibleState(state: GameState, faction: Faction): GameState {
  const visibleEntities = getVisibleEntities(state, faction);

  return {
    ...state,
    entities: visibleEntities,
    // Keep fog data for the player faction
    map: {
      ...state.map,
      fog: {
        ...state.map.fog,
        // Only expose player's fog
      },
    },
  };
}

/**
 * Order processing: training units, building construction, repair.
 */

import type { Entity, GameState, Faction, UnitType, BuildingType } from '../core/types';
import { FACTION_STATS, TECH_REQUIREMENTS } from '../core/stats';
import {
  createUnit, createBuilding, killEntity, hasTechRequirements, getEntity,
} from './entities';
import { WORKER_REPAIR_RATE, WORKER_REPAIR_COST_GOLD, WORKER_REPAIR_COST_WOOD } from '../core/types';
import { findPath } from '../core/pathfinding';
import { vecDist } from '../core/types';

/**
 * Process training queues for buildings.
 */
export function processTraining(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'building') continue;
    if (entity.order.type !== 'train') continue;

    entity.progressTicks++;
    if (entity.progressTicks >= entity.progressTotal) {
      // Training complete — spawn unit
      completeTraining(state, entity);
    }
  }
}

/**
 * Process building construction.
 */
export function processConstruction(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'building') continue;
    if (entity.progressTotal <= 0) continue; // Not under construction
    if (entity.progressTicks >= entity.progressTotal) continue; // Already complete

    entity.progressTicks++;
    // Scale HP based on progress
    const progress = entity.progressTicks / entity.progressTotal;
    const targetHp = FACTION_STATS[entity.faction].buildings[entity.buildingType as BuildingType].hp;
    entity.hp = Math.max(1, Math.floor(targetHp * progress));

    if (entity.progressTicks >= entity.progressTotal) {
      entity.hp = targetHp;
      // Mark tiles as walkable=false for the building footprint
      const map = state.map;
      for (let dy = 0; dy < entity.height; dy++) {
        for (let dx = 0; dx < entity.width; dx++) {
          const tx = entity.x + dx;
          const ty = entity.y + dy;
          if (tx >= 0 && tx < map.width && ty >= 0 && ty < map.height) {
            map.walkable[ty * map.width + tx] = false;
          }
        }
      }
    }
  }
}

/**
 * Process repair orders.
 */
export function processRepair(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'unit') continue;
    if (entity.order.type !== 'repair') continue;
    if (entity.unitType !== 'worker') continue;

    const targetId = entity.order.targetId;
    if (targetId === undefined) {
      entity.order = { type: 'idle' };
      continue;
    }

    const target = getEntity(state, targetId);
    if (!target || !target.alive || target.entityType !== 'building') {
      entity.order = { type: 'idle' };
      continue;
    }

    // Check if building needs repair
    const buildingStats = FACTION_STATS[target.faction].buildings[target.buildingType as BuildingType];
    if (target.hp >= buildingStats.hp) {
      entity.order = { type: 'idle' };
      continue;
    }

    const dist = vecDist(entity, target);
    if (dist < 2) {
      // In range — repair
      const goldCost = WORKER_REPAIR_COST_GOLD;
      const woodCost = WORKER_REPAIR_COST_WOOD;
      if (state.resources[entity.faction].gold >= goldCost &&
          state.resources[entity.faction].wood >= woodCost) {
        const repairAmount = Math.min(WORKER_REPAIR_RATE, buildingStats.hp - target.hp);
        state.resources[entity.faction].gold -= goldCost * repairAmount;
        state.resources[entity.faction].wood -= woodCost * repairAmount;
        target.hp = Math.min(buildingStats.hp, target.hp + repairAmount);
      } else {
        entity.order = { type: 'idle' };
      }
    } else {
      // Move to building
      if (entity.path.length === 0 || entity.pathIndex >= entity.path.length) {
        const path = findPath(state.map, Math.floor(entity.x), Math.floor(entity.y),
          Math.floor(target.x), Math.floor(target.y));
        entity.path = path ?? [];
        entity.pathIndex = 0;
      }
    }
  }
}

/**
 * Enqueue a unit training order at a building.
 */
export function enqueueTraining(
  state: GameState,
  building: Entity,
  unitType: UnitType,
): boolean {
  if (building.entityType !== 'building' || !building.buildingType) return false;
  if (building.buildingType !== 'barracks' && building.buildingType !== 'townHall') return false;

  const faction = building.faction;
  const stats = FACTION_STATS[faction].units[unitType];

  // Check tech requirements
  const reqs = TECH_REQUIREMENTS[unitType] ?? [];
  if (!hasTechRequirements(state, faction, reqs)) return false;

  // Check supply
  if (state.supplyUsed[faction] + stats.supplyCost > state.supplyCap[faction]) return false;

  // Check resources
  if (state.resources[faction].gold < stats.goldCost) return false;
  if (state.resources[faction].wood < stats.woodCost) return false;

  // Deduct resources
  state.resources[faction].gold -= stats.goldCost;
  state.resources[faction].wood -= stats.woodCost;
  state.supplyUsed[faction] += stats.supplyCost;

  // Set building to training
  building.order = { type: 'train', buildType: undefined };
  building.progressTicks = 0;
  building.progressTotal = stats.trainTime;

  return true;
}

/**
 * Complete training: spawn the unit near the building.
 */
function completeTraining(state: GameState, building: Entity): void {
  if (!building.buildingType) return;

  const faction = building.faction;
  const unitType = getUnitTypeForBuilding(building.buildingType);
  if (!unitType) return;

  // Find spawn location
  const spawnPos = findSpawnPosition(state, building);
  if (!spawnPos) return;

  createUnit(state, faction, unitType, spawnPos.x, spawnPos.y);

  // Reset building
  building.order = { type: 'idle' };
  building.progressTicks = 0;
  building.progressTotal = 0;
}

/**
 * Get the unit type for a building's training queue.
 */
function getUnitTypeForBuilding(buildingType: BuildingType): UnitType | null {
  switch (buildingType) {
    case 'townHall': return 'worker';
    case 'barracks': return 'melee'; // Simplified — would track in queue
    default: return null;
  }
}

/**
 * Find a spawn position near a building that's not occupied.
 */
function findSpawnPosition(state: GameState, building: Entity): { x: number; y: number } | null {
  // Try positions adjacent to the building
  const positions: { x: number; y: number }[] = [];

  for (let dx = -1; dx <= building.width; dx++) {
    positions.push({ x: building.x + dx, y: building.y - 1 });
    positions.push({ x: building.x + dx, y: building.y + building.height });
  }
  for (let dy = 0; dy < building.height; dy++) {
    positions.push({ x: building.x - 1, y: building.y + dy });
    positions.push({ x: building.x + building.width, y: building.y + dy });
  }

  // Sort by distance to building center
  const cx = building.x + building.width / 2;
  const cy = building.y + building.height / 2;
  positions.sort((a, b) => {
    const da = Math.sqrt((a.x - cx) ** 2 + (a.y - cy) ** 2);
    const db = Math.sqrt((b.x - cx) ** 2 + (b.y - cy) ** 2);
    return da - db;
  });

  for (const pos of positions) {
    if (pos.x < 0 || pos.x >= state.map.width || pos.y < 0 || pos.y >= state.map.height) continue;
    if (!state.map.walkable[pos.y * state.map.width + pos.x]) continue;

    // Check if position is occupied by another unit
    const occupied = state.entities.some(e =>
      e.alive && e.entityType === 'unit' &&
      Math.abs(e.x - pos.x) < 0.5 && Math.abs(e.y - pos.y) < 0.5,
    );

    if (!occupied) return pos;
  }

  // C6: find nearest free walkable tile
  for (let r = 2; r < 10; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
        const nx = building.x + building.width / 2 + dx;
        const ny = building.y + building.height / 2 + dy;
        if (nx < 0 || nx >= state.map.width || ny < 0 || ny >= state.map.height) continue;
        const tx = Math.floor(nx);
        const ty = Math.floor(ny);
        if (!state.map.walkable[ty * state.map.width + tx]) continue;
        const occupied = state.entities.some(e =>
          e.alive && e.entityType === 'unit' &&
          Math.abs(e.x - nx) < 0.5 && Math.abs(e.y - ny) < 0.5,
        );
        if (!occupied) return { x: nx, y: ny };
      }
    }
  }

  return null;
}

/**
 * Place a building: validate placement and start construction.
 */
export function placeBuilding(
  state: GameState,
  faction: Faction,
  buildingType: BuildingType,
  x: number,
  y: number,
): Entity | null {
  const stats = FACTION_STATS[faction].buildings[buildingType];

  // Check resources
  if (state.resources[faction].gold < stats.goldCost) return null;
  if (state.resources[faction].wood < stats.woodCost) return null;

  // Check tech requirements
  const reqs = TECH_REQUIREMENTS[buildingType] ?? [];
  if (!hasTechRequirements(state, faction, reqs)) return null;

  // Validate placement
  if (!isValidPlacement(state, x, y, stats.width, stats.height)) return null;

  // Deduct resources
  state.resources[faction].gold -= stats.goldCost;
  state.resources[faction].wood -= stats.woodCost;

  // Create building
  const building = createBuilding(state, faction, buildingType, x, y, true);
  return building;
}

/**
 * Check if a building placement is valid (C7).
 */
export function isValidPlacement(
  state: GameState,
  x: number,
  y: number,
  width: number,
  height: number,
): boolean {
  // Check bounds
  if (x < 0 || x + width > state.map.width) return false;
  if (y < 0 || y + height > state.map.height) return false;

  // Check all tiles in footprint
  for (let dy = 0; dy < height; dy++) {
    for (let dx = 0; dx < width; dx++) {
      const tx = x + dx;
      const ty = y + dy;
      const idx = ty * state.map.width + tx;

      // Check walkability
      if (!state.map.walkable[idx]) return false;

      // Check tile type (not water, rock, gold mine, forest)
      const tile = state.map.tiles[idx];
      if (tile === 'water' || tile === 'rock' || tile === 'goldMine' || tile === 'forest') {
        return false;
      }

      // Check for existing buildings
      for (const entity of state.entities) {
        if (!entity.alive || entity.entityType !== 'building') continue;
        if (tx >= entity.x && tx < entity.x + entity.width &&
            ty >= entity.y && ty < entity.y + entity.height) {
          return false;
        }
      }

      // Check for units on the tile
      for (const entity of state.entities) {
        if (!entity.alive || entity.entityType !== 'unit') continue;
        if (Math.abs(entity.x - tx) < 0.5 && Math.abs(entity.y - ty) < 0.5) {
          return false;
        }
      }
    }
  }

  return true;
}

/**
 * Main game simulation: initialization, tick processing, win/lose detection.
 */

import type { GameState, GameConfig, Faction, Entity, UnitType, BuildingType, Vec2 } from '../core/types';
import { TICK_RATE, PROGRESS_WATCHDOG_TICKS } from '../core/types';
import { FACTION_STATS } from '../core/stats';
import { createPRNG } from '../core/prng';
import { generateMap } from '../gen/mapgen';
import { createUnit, createBuilding, killEntity, hasBuildings } from './entities';
import { processMovement } from './movement';
import { processCombat } from './combat';
import { processHarvesting, createForestEntity } from './economy';
import { processTraining, processConstruction, processRepair } from './orders';
import { updateFog } from './fog';

/**
 * Initialize a new game state.
 */
export function initGame(config: GameConfig): GameState {
  const map = generateMap(config.seed, config.level);

  const state: GameState = {
    map,
    entities: [],
    nextEntityId: 1,
    resources: { humans: { gold: 500, wood: 500 }, orcs: { gold: 500, wood: 500 } },
    supplyUsed: { humans: 0, orcs: 0 },
    supplyCap: { humans: 0, orcs: 0 },
    tick: 0,
    winner: null,
    speed: 1,
    paused: false,
    seed: config.seed,
  };

  // Create starting buildings and units
  createStartingEntities(state, config);

  // Create forest entities for harvesting
  createForestEntities(state);

  // Initial fog update
  updateFog(state, 'humans');
  updateFog(state, 'orcs');

  return state;
}

/**
 * Create starting buildings and units for both factions.
 */
function createStartingEntities(state: GameState, config: GameConfig): void {
  const aiFaction: Faction = config.playerFaction === 'humans' ? 'orcs' : 'humans';

  // Player starting entities
  createStartingFaction(state, config.playerFaction, config.difficulty);
  // AI starting entities
  createStartingFaction(state, aiFaction, config.difficulty);
}

/**
 * Create starting entities for a faction.
 */
function createStartingFaction(state: GameState, faction: Faction, difficulty: number): void {
  const start = state.map.startLocations[faction];
  const townHall = createBuilding(state, faction, 'townHall', start.x, start.y);

  // Starting workers (3-5 based on difficulty)
  const workerCount = 3 + Math.min(2, difficulty - 1);
  for (let i = 0; i < workerCount; i++) {
    const angle = (i / workerCount) * Math.PI * 2;
    const wx = start.x + 2 + Math.cos(angle) * 2;
    const wy = start.y + 2 + Math.sin(angle) * 2;
    createUnit(state, faction, 'worker', wx, wy);
  }
}

/**
 * Create forest entities for all forest tiles.
 */
function createForestEntities(state: GameState): void {
  for (let y = 0; y < state.map.height; y++) {
    for (let x = 0; x < state.map.width; x++) {
      if (state.map.tiles[y * state.map.width + x] === 'forest') {
        const forest = createForestEntity(state, x, y);
        forest.faction = 'humans'; // Neutral but we need a faction
      }
    }
  }
}

/**
 * Process one simulation tick.
 */
export function gameTick(state: GameState): void {
  if (state.paused || state.winner) return;

  state.tick++;

  // Process all systems
  processMovement(state);
  processCombat(state);
  processHarvesting(state);
  processTraining(state);
  processConstruction(state);
  processRepair(state);

  // Update fog for both factions
  updateFog(state, 'humans');
  updateFog(state, 'orcs');

  // Clean up dead entities
  cleanupDeadEntities(state);

  // Check win/lose conditions
  checkWinLose(state);

  // Progress watchdog: cancel stuck orders
  processWatchdog(state);
}

/**
 * Clean up dead entities from the entity list.
 */
function cleanupDeadEntities(state: GameState): void {
  state.entities = state.entities.filter(e => e.alive);
}

/**
 * Check win/lose conditions: a side loses when all its buildings are destroyed.
 */
function checkWinLose(state: GameState): void {
  if (state.winner) return;

  const humansAlive = hasBuildings(state, 'humans');
  const orcsAlive = hasBuildings(state, 'orcs');

  if (!humansAlive && !orcsAlive) {
    // Draw — shouldn't happen normally
    state.winner = 'humans'; // Default
  } else if (!humansAlive) {
    state.winner = 'orcs';
  } else if (!orcsAlive) {
    state.winner = 'humans';
  }
}

/**
 * Progress watchdog (I3): cancel orders that haven't made progress.
 */
function processWatchdog(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'unit') continue;
    if (entity.order.type === 'idle') continue;

    entity.progressTicks++;
    if (entity.progressTicks > PROGRESS_WATCHDOG_TICKS) {
      // No progress — cancel order
      entity.order = { type: 'idle' };
      entity.path = [];
      entity.progressTicks = 0;
    }
  }
}

/**
 * Get the current game speed.
 */
export function getGameSpeed(state: GameState): number {
  return state.speed;
}

/**
 * Set the game speed.
 */
export function setGameSpeed(state: GameState, speed: number): void {
  state.speed = Math.max(0.5, Math.min(3, speed));
}

/**
 * Toggle pause.
 */
export function togglePause(state: GameState): void {
  state.paused = !state.paused;
}

/**
 * Spawn entities for testing.
 */
export function spawnTestUnit(
  state: GameState,
  faction: Faction,
  unitType: UnitType,
  x: number,
  y: number,
): Entity {
  return createUnit(state, faction, unitType, x, y);
}

/**
 * Spawn a building for testing.
 */
export function spawnTestBuilding(
  state: GameState,
  faction: Faction,
  buildingType: BuildingType,
  x: number,
  y: number,
): Entity {
  return createBuilding(state, faction, buildingType, x, y);
}

/**
 * Set resources for testing.
 */
export function setResources(state: GameState, faction: Faction, gold: number, wood: number): void {
  state.resources[faction] = { gold, wood };
}

/**
 * Destroy an entity immediately (for testing).
 */
export function destroyEntity(state: GameState, entity: Entity): void {
  killEntity(state, entity);
}

/**
 * Serialize game state for determinism testing.
 */
export function serializeState(state: GameState): string {
  return JSON.stringify({
    tick: state.tick,
    resources: state.resources,
    supplyUsed: state.supplyUsed,
    supplyCap: state.supplyCap,
    entities: state.entities.map(e => ({
      id: e.id,
      faction: e.faction,
      x: Math.round(e.x * 100) / 100,
      y: Math.round(e.y * 100) / 100,
      hp: e.hp,
      order: e.order.type,
      alive: e.alive,
    })),
  });
}

/**
 * Get the simulation tick rate.
 */
export function getTickRate(): number {
  return TICK_RATE;
}

/**
 * AI opponent: scripted-strategy AI for the opposing faction.
 * Maintains worker saturation, follows build order, trains army,
 * sends attack waves, defends base, rebuilds destroyed buildings.
 */

import type { GameState, Faction, Entity, UnitType, BuildingType } from '../core/types';
import {
  difficultyResourceMult, difficultyHarvestMult,
  difficultyWaveSizeMult, difficultyWaveCadenceTicks, TICK_RATE,
} from '../core/types';
import { FACTION_STATS, TECH_REQUIREMENTS } from '../core/stats';
import { createUnit, createBuilding, getTownHall, hasTechRequirements } from '../sim/entities';
import { assignMoveOrder } from '../sim/movement';
import { enqueueTraining, placeBuilding, isValidPlacement } from '../sim/orders';
import { findPath } from '../core/pathfinding';
import { vecDist } from '../core/types';

/** AI state per faction */
interface AIState {
  readonly faction: Faction;
  readonly difficulty: number;
  lastWaveTick: number;
  waveNumber: number;
  buildQueue: BuildingType[];
  nextBuildCheck: number;
}

/** Create AI state for a faction */
export function createAIState(faction: Faction, difficulty: number): AIState {
  return {
    faction,
    difficulty,
    lastWaveTick: 0,
    waveNumber: 0,
    buildQueue: ['farm', 'barracks', 'lumberMill', 'farm', 'guardTower'],
    nextBuildCheck: 0,
  };
}

/**
 * Process AI logic for one tick.
 */
export function processAI(state: GameState, ai: AIState): void {
  if (state.winner) return;

  // Apply difficulty bonuses
  applyDifficultyBonuses(state, ai);

  // Manage workers
  manageWorkers(state, ai);

  // Build structures
  processBuildOrder(state, ai);

  // Train military units
  trainMilitary(state, ai);

  // Send attack waves
  processAttackWaves(state, ai);

  // Defend base
  defendBase(state, ai);

  // Rebuild destroyed buildings
  rebuildBuildings(state, ai);
}

/**
 * Apply difficulty-based bonuses.
 */
function applyDifficultyBonuses(state: GameState, ai: AIState): void {
  // Harvest rate bonus (give extra resources periodically)
  if (state.tick % (TICK_RATE * 10) === 0) {
    const bonus = (ai.difficulty - 1) * 20;
    state.resources[ai.faction].gold += bonus;
    state.resources[ai.faction].wood += bonus;
  }
}

/**
 * Manage workers: ensure saturation on gold and wood.
 */
function manageWorkers(state: GameState, ai: AIState): void {
  const workers = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'unit' && e.unitType === 'worker',
  );

  const idleWorkers = workers.filter(e => e.order.type === 'idle');

  // Find gold mines and forests
  const goldMines = state.entities.filter(e =>
    e.alive && e.buildingType === 'goldMine',
  );
  const forests = state.entities.filter(e =>
    e.alive && e.entityType === 'building' && e.buildingType === 'farm' &&
    state.map.tiles[Math.floor(e.y) * state.map.width + Math.floor(e.x)] === 'forest',
  );

  // Assign idle workers to resources
  for (const worker of idleWorkers) {
    if (goldMines.length > 0) {
      const mine = goldMines[Math.floor(Math.random() * goldMines.length)];
      if (mine) {
        worker.order = { type: 'harvest', targetId: mine.id };
        worker.harvestTarget = mine.id;
      }
    } else if (forests.length > 0) {
      const forest = forests[Math.floor(Math.random() * forests.length)];
      if (forest) {
        worker.order = { type: 'harvest', targetId: forest.id };
        worker.harvestTarget = forest.id;
      }
    }
  }

  // Train more workers if needed
  const townHall = getTownHall(state, ai.faction);
  if (townHall && workers.length < 8) {
    const stats = FACTION_STATS[ai.faction].units.worker;
    if (state.resources[ai.faction].gold >= stats.goldCost &&
        state.supplyUsed[ai.faction] + stats.supplyCost <= state.supplyCap[ai.faction]) {
      enqueueTraining(state, townHall, 'worker');
    }
  }
}

/**
 * Process the build order: construct buildings in sequence.
 */
function processBuildOrder(state: GameState, ai: AIState): void {
  if (state.tick < ai.nextBuildCheck) return;
  ai.nextBuildCheck = state.tick + TICK_RATE * 5; // Check every 5 seconds

  if (ai.buildQueue.length === 0) return;

  const buildingType = ai.buildQueue[0];
  const stats = FACTION_STATS[ai.faction].buildings[buildingType];

  // Check if we can afford it
  if (state.resources[ai.faction].gold < stats.goldCost ||
      state.resources[ai.faction].wood < stats.woodCost) {
    return;
  }

  // Find a worker to build
  const workers = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'unit' &&
    e.unitType === 'worker' && e.order.type === 'idle',
  );

  if (workers.length === 0) return;

  // Find placement near town hall
  const townHall = getTownHall(state, ai.faction);
  if (!townHall) return;

  const placement = findPlacement(state, townHall.x, townHall.y, stats.width, stats.height);
  if (!placement) return;

  // Place building
  const building = placeBuilding(state, ai.faction, buildingType, placement.x, placement.y);
  if (building) {
    ai.buildQueue.shift();
    // Assign worker to build
    const worker = workers[0];
    if (worker) {
      worker.order = { type: 'build', targetId: building.id };
      worker.buildTarget = building.id;
    }
  }
}

/**
 * Find a valid placement near a position.
 */
function findPlacement(
  state: GameState,
  nearX: number,
  nearY: number,
  width: number,
  height: number,
): { x: number; y: number } | null {
  for (let r = 3; r < 15; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
        const x = nearX + dx;
        const y = nearY + dy;
        if (isValidPlacement(state, x, y, width, height)) {
          return { x, y };
        }
      }
    }
  }
  return null;
}

/**
 * Train military units from barracks.
 */
function trainMilitary(state: GameState, ai: AIState): void {
  const barracks = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'building' &&
    e.buildingType === 'barracks' && e.order.type === 'idle',
  );

  for (const barrack of barracks) {
    // Try to train the best unit we can afford
    const unitTypes: UnitType[] = ['heavy', 'ranged', 'melee'];
    for (const unitType of unitTypes) {
      const stats = FACTION_STATS[ai.faction].units[unitType];
      const reqs = TECH_REQUIREMENTS[unitType] ?? [];

      if (!hasTechRequirements(state, ai.faction, reqs)) continue;
      if (state.resources[ai.faction].gold < stats.goldCost) continue;
      if (state.resources[ai.faction].wood < stats.woodCost) continue;
      if (state.supplyUsed[ai.faction] + stats.supplyCost > state.supplyCap[ai.faction]) continue;

      enqueueTraining(state, barrack, unitType);
      break;
    }
  }
}

/**
 * Process attack waves.
 */
function processAttackWaves(state: GameState, ai: AIState): void {
  const cadence = difficultyWaveCadenceTicks(ai.difficulty);
  if (state.tick - ai.lastWaveTick < cadence) return;

  // Gather military units
  const military = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'unit' &&
    e.unitType !== 'worker' && e.order.type === 'idle',
  );

  const waveSize = Math.floor(3 + ai.waveNumber * difficultyWaveSizeMult(ai.difficulty));
  const attackers = military.slice(0, waveSize);

  if (attackers.length < 2) return;

  // Find enemy base
  const enemyFaction: Faction = ai.faction === 'humans' ? 'orcs' : 'humans';
  const enemyTownHall = getTownHall(state, enemyFaction);
  if (!enemyTownHall) return;

  // Send attack wave
  for (const unit of attackers) {
    const path = findPath(state.map, Math.floor(unit.x), Math.floor(unit.y),
      Math.floor(enemyTownHall.x), Math.floor(enemyTownHall.y));
    unit.order = { type: 'attackMove', target: { x: enemyTownHall.x, y: enemyTownHall.y } };
    unit.path = path ?? [];
    unit.pathIndex = 0;
  }

  ai.lastWaveTick = state.tick;
  ai.waveNumber++;
}

/**
 * Defend base: pull military units to threats.
 */
function defendBase(state: GameState, ai: AIState): void {
  const townHall = getTownHall(state, ai.faction);
  if (!townHall) return;

  // Check for enemies near base
  const enemies = state.entities.filter(e =>
    e.alive && e.faction !== ai.faction && e.entityType === 'unit',
  );

  const baseCenter = { x: townHall.x + townHall.width / 2, y: townHall.y + townHall.height / 2 };
  const threats = enemies.filter(e => vecDist(e, baseCenter) < 15);

  if (threats.length === 0) return;

  // Pull idle military to defend
  const defenders = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'unit' &&
    e.unitType !== 'worker' && e.order.type === 'idle',
  );

  for (const defender of defenders) {
    const nearestThreat = threats.reduce((nearest, threat) => {
      const d = vecDist(defender, threat);
      return d < vecDist(defender, nearest) ? threat : nearest;
    });

    if (nearestThreat) {
      defender.order = { type: 'attack', targetId: nearestThreat.id };
    }
  }
}

/**
 * Rebuild destroyed buildings.
 */
function rebuildBuildings(state: GameState, ai: AIState): void {
  // Check what buildings we're missing
  const buildings = state.entities.filter(e =>
    e.alive && e.faction === ai.faction && e.entityType === 'building',
  );

  const buildingTypes = new Set(buildings.map(e => e.buildingType));

  // If we're missing critical buildings, add to build queue
  if (!buildingTypes.has('barracks') && !ai.buildQueue.includes('barracks')) {
    ai.buildQueue.push('barracks');
  }
  if (!buildingTypes.has('lumberMill') && !ai.buildQueue.includes('lumberMill')) {
    ai.buildQueue.push('lumberMill');
  }
}

/**
 * HUD layout: pure functions computing rectangle data for all UI elements.
 * Single source of truth for both rendering and hit-testing.
 */

export interface Rect {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

export interface HudLayout {
  readonly viewport: Rect;
  readonly minimap: Rect;
  readonly resourceBar: Rect;
  readonly selectionPanel: Rect;
  readonly buttons: ReadonlyArray<ButtonDef>;
  readonly speedButton: Rect;
  readonly pauseButton: Rect;
}

export interface ButtonDef {
  readonly id: string;
  readonly rect: Rect;
  readonly label: string;
}

/** Layout constants */
const MINIMAP_SIZE = 200;
const RESOURCE_BAR_HEIGHT = 40;
const SELECTION_PANEL_WIDTH = 250;
const BUTTON_SIZE = 50;
const BUTTON_GAP = 5;
const PADDING = 5;

/**
 * Compute the HUD layout for a given viewport size.
 */
export function computeLayout(viewportWidth: number, viewportHeight: number): HudLayout {
  // Minimap: bottom-left
  const minimap: Rect = {
    x: PADDING,
    y: viewportHeight - MINIMAP_SIZE - PADDING,
    width: MINIMAP_SIZE,
    height: MINIMAP_SIZE,
  };

  // Resource bar: top, full width
  const resourceBar: Rect = {
    x: 0,
    y: 0,
    width: viewportWidth,
    height: RESOURCE_BAR_HEIGHT,
  };

  // Selection panel: right side
  const selectionPanel: Rect = {
    x: viewportWidth - SELECTION_PANEL_WIDTH - PADDING,
    y: RESOURCE_BAR_HEIGHT + PADDING,
    width: SELECTION_PANEL_WIDTH,
    height: viewportHeight - RESOURCE_BAR_HEIGHT - MINIMAP_SIZE - PADDING * 3,
  };

  // Buttons: in selection panel
  const buttons: ButtonDef[] = [];
  const buttonAreaX = selectionPanel.x + PADDING;
  const buttonAreaY = selectionPanel.y + 100; // Below unit info
  const buttonsPerRow = Math.floor((selectionPanel.width - PADDING * 2) / (BUTTON_SIZE + BUTTON_GAP));

  const buttonTypes = ['train_worker', 'train_melee', 'train_ranged', 'train_heavy',
    'build_farm', 'build_barracks', 'build_lumberMill', 'build_guardTower'];

  for (let i = 0; i < buttonTypes.length; i++) {
    const row = Math.floor(i / buttonsPerRow);
    const col = i % buttonsPerRow;
    buttons.push({
      id: buttonTypes[i],
      rect: {
        x: buttonAreaX + col * (BUTTON_SIZE + BUTTON_GAP),
        y: buttonAreaY + row * (BUTTON_SIZE + BUTTON_GAP),
        width: BUTTON_SIZE,
        height: BUTTON_SIZE,
      },
      label: buttonTypes[i].replace('_', ' '),
    });
  }

  // Speed button: top-right
  const speedButton: Rect = {
    x: viewportWidth - 100 - PADDING,
    y: PADDING,
    width: 50,
    height: 30,
  };

  // Pause button: next to speed
  const pauseButton: Rect = {
    x: viewportWidth - 50 - PADDING,
    y: PADDING,
    width: 50,
    height: 30,
  };

  return {
    viewport: { x: 0, y: 0, width: viewportWidth, height: viewportHeight },
    minimap,
    resourceBar,
    selectionPanel,
    buttons,
    speedButton,
    pauseButton,
  };
}

/**
 * Hit-test: determine which UI element is at a screen point.
 * Returns the element ID or null.
 */
export function hitTest(layout: HudLayout, screenX: number, screenY: number): string | null {
  // Check buttons
  for (const btn of layout.buttons) {
    if (pointInRect(btn.rect, screenX, screenY)) {
      return btn.id;
    }
  }

  // Check speed button
  if (pointInRect(layout.speedButton, screenX, screenY)) {
    return 'speed';
  }

  // Check pause button
  if (pointInRect(layout.pauseButton, screenX, screenY)) {
    return 'pause';
  }

  // Check minimap
  if (pointInRect(layout.minimap, screenX, screenY)) {
    return 'minimap';
  }

  // Check selection panel
  if (pointInRect(layout.selectionPanel, screenX, screenY)) {
    return 'selectionPanel';
  }

  // Check resource bar
  if (pointInRect(layout.resourceBar, screenX, screenY)) {
    return 'resourceBar';
  }

  // Otherwise it's a viewport click
  return 'viewport';
}

/**
 * Check if a point is inside a rectangle.
 */
function pointInRect(rect: Rect, x: number, y: number): boolean {
  return x >= rect.x && x < rect.x + rect.width &&
         y >= rect.y && y < rect.y + rect.height;
}

/**
 * Get the minimap position for a world coordinate.
 */
export function worldToMinimap(
  layout: HudLayout,
  worldX: number,
  worldY: number,
  mapWidth: number,
  mapHeight: number,
): { x: number; y: number } {
  const relX = worldX / mapWidth;
  const relY = worldY / mapHeight;
  return {
    x: layout.minimap.x + relX * layout.minimap.width,
    y: layout.minimap.y + relY * layout.minimap.height,
  };
}

/**
 * Get the world coordinate for a minimap position.
 */
export function minimapToWorld(
  layout: HudLayout,
  minimapX: number,
  minimapY: number,
  mapWidth: number,
  mapHeight: number,
): { x: number; y: number } {
  const relX = (minimapX - layout.minimap.x) / layout.minimap.width;
  const relY = (minimapY - layout.minimap.y) / layout.minimap.height;
  return {
    x: relX * mapWidth,
    y: relY * mapHeight,
  };
}

/**
 * Input handling: translates DOM events into simulation orders.
 * Contains no game logic of its own — only input → order mapping.
 */

import type { GameState, Faction, Entity, BuildingType, UnitType } from '../core/types';
import type { HudLayout } from './layout';
import { hitTest, minimapToWorld } from './layout';
import { assignMoveOrder, assignHarvestOrder } from '../sim/movement';
import { enqueueTraining, placeBuilding } from '../sim/orders';
import { FACTION_STATS, TECH_REQUIREMENTS } from '../core/stats';
import { hasTechRequirements } from '../sim/entities';

export interface InputState {
  selectedEntities: Entity[];
  controlGroups: Map<number, Entity[]>;
  isDragging: boolean;
  dragStart: { x: number; y: number } | null;
  dragEnd: { x: number; y: number } | null;
  placementMode: BuildingType | null;
  camera: { x: number; y: number };
}

/** Create initial input state */
export function createInputState(): InputState {
  return {
    selectedEntities: [],
    controlGroups: new Map(),
    isDragging: false,
    dragStart: null,
    dragEnd: null,
    placementMode: null,
    camera: { x: 0, y: 0 },
  };
}

/** Get client→canvas coordinate transform */
export type CoordTransform = (clientX: number, clientY: number) => { x: number; y: number };

/** Default transform using getBoundingClientRect */
export function defaultTransform(canvas: HTMLCanvasElement): CoordTransform {
  return (clientX: number, clientY: number) => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: clientX - rect.left,
      y: clientY - rect.top,
    };
  };
}

/**
 * Handle a mouse down event.
 */
export function handleMouseDown(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  button: number,
  shiftKey: boolean,
  playerFaction: Faction,
): void {
  const element = hitTest(layout, screenX, screenY);

  if (button === 0) {
    // Left click
    if (element === 'viewport') {
      handleViewportLeftClick(state, gameState, layout, screenX, screenY, shiftKey, playerFaction);
    } else if (element === 'minimap') {
      handleMinimapClick(state, layout, screenX, screenY, gameState.map.width, gameState.map.height);
    } else if (element.startsWith('train_') || element.startsWith('build_')) {
      handleButtonClick(state, gameState, element, playerFaction);
    } else if (element === 'speed') {
      gameState.speed = gameState.speed >= 2 ? 1 : gameState.speed + 1;
    } else if (element === 'pause') {
      gameState.paused = !gameState.paused;
    }
  } else if (button === 2) {
    // Right click
    if (element === 'viewport') {
      handleViewportRightClick(state, gameState, layout, screenX, screenY, playerFaction);
    }
  }
}

/**
 * Handle left click on the viewport.
 */
function handleViewportLeftClick(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  shiftKey: boolean,
  playerFaction: Faction,
): void {
  const worldPos = screenToWorld(state, layout, screenX, screenY);

  // If in placement mode, try to place building
  if (state.placementMode) {
    const stats = FACTION_STATS[playerFaction].buildings[state.placementMode];
    const placed = placeBuilding(gameState, playerFaction, state.placementMode,
      Math.floor(worldPos.x), Math.floor(worldPos.y));
    if (placed) {
      state.placementMode = null;
      // Assign idle worker to build
      const worker = state.selectedEntities.find(e =>
        e.entityType === 'unit' && e.unitType === 'worker',
      );
      if (worker) {
        worker.order = { type: 'build', targetId: placed.id };
        worker.buildTarget = placed.id;
      }
    }
    return;
  }

  // Start drag selection
  state.isDragging = true;
  state.dragStart = { x: screenX, y: screenY };
  state.dragEnd = { x: screenX, y: screenY };

  // Try to select entity at click position
  const clickedEntity = findEntityAtPosition(gameState, worldPos.x, worldPos.y, playerFaction);

  if (clickedEntity) {
    if (shiftKey) {
      // Add to selection
      if (!state.selectedEntities.includes(clickedEntity)) {
        state.selectedEntities.push(clickedEntity);
      }
    } else {
      state.selectedEntities = [clickedEntity];
    }
  } else if (!shiftKey) {
    state.selectedEntities = [];
  }
}

/**
 * Handle right click on the viewport (context-sensitive order).
 */
function handleViewportRightClick(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  playerFaction: Faction,
): void {
  if (state.selectedEntities.length === 0) return;

  const worldPos = screenToWorld(state, layout, screenX, screenY);
  const targetEntity = findEntityAtPosition(gameState, worldPos.x, worldPos.y);

  for (const entity of state.selectedEntities) {
    if (entity.faction !== playerFaction) continue;
    if (entity.entityType !== 'unit') continue;

    if (targetEntity && targetEntity.faction !== playerFaction) {
      // Attack enemy
      entity.order = { type: 'attack', targetId: targetEntity.id };
    } else if (targetEntity && targetEntity.buildingType === 'goldMine') {
      // Harvest gold
      assignHarvestOrder(gameState, entity, targetEntity.id);
    } else if (targetEntity && targetEntity.faction === playerFaction &&
               targetEntity.entityType === 'building' && targetEntity.hp < targetEntity.maxHp) {
      // Repair
      entity.order = { type: 'repair', targetId: targetEntity.id };
      entity.repairTarget = targetEntity.id;
    } else {
      // Move to position
      assignMoveOrder(gameState, entity, worldPos.x, worldPos.y);
    }
  }
}

/**
 * Handle minimap click.
 */
function handleMinimapClick(
  state: InputState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  mapWidth: number,
  mapHeight: number,
): void {
  const worldPos = minimapToWorld(layout, screenX, screenY, mapWidth, mapHeight);
  state.camera.x = worldPos.x - layout.viewport.width / 2;
  state.camera.y = worldPos.y - layout.viewport.height / 2;
}

/**
 * Handle button click (train/build).
 */
function handleButtonClick(
  state: InputState,
  gameState: GameState,
  buttonId: string,
  playerFaction: Faction,
): void {
  if (buttonId.startsWith('train_')) {
    const unitType = buttonId.replace('train_', '') as UnitType;
    const building = state.selectedEntities.find(e =>
      e.entityType === 'building' && e.buildingType === 'barracks' || e.buildingType === 'townHall',
    );
    if (building) {
      enqueueTraining(gameState, building, unitType);
    }
  } else if (buttonId.startsWith('build_')) {
    const buildingType = buttonId.replace('build_', '') as BuildingType;
    state.placementMode = buildingType;
  }
}

/**
 * Handle mouse up (end drag selection).
 */
export function handleMouseUp(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  playerFaction: Faction,
): void {
  if (!state.isDragging || !state.dragStart) return;

  const dragEnd = { x: screenX, y: screenY };
  const dx = Math.abs(dragEnd.x - state.dragStart.x);
  const dy = Math.abs(dragEnd.y - state.dragStart.y);

  if (dx > 5 || dy > 5) {
    // Box selection
    const startWorld = screenToWorld(state, layout, state.dragStart.x, state.dragStart.y);
    const endWorld = screenToWorld(state, layout, dragEnd.x, dragEnd.y);

    const minX = Math.min(startWorld.x, endWorld.x);
    const maxX = Math.max(startWorld.x, endWorld.x);
    const minY = Math.min(startWorld.y, endWorld.y);
    const maxY = Math.max(startWorld.y, endWorld.y);

    state.selectedEntities = gameState.entities.filter(e =>
      e.alive && e.faction === playerFaction &&
      e.x >= minX && e.x <= maxX && e.y >= minY && e.y <= maxY,
    );
  }

  state.isDragging = false;
  state.dragStart = null;
  state.dragEnd = null;
}

/**
 * Handle keyboard input.
 */
export function handleKeyDown(
  state: InputState,
  gameState: GameState,
  key: string,
  ctrlKey: boolean,
  playerFaction: Faction,
): void {
  // Control groups
  if (ctrlKey && key >= '1' && key <= '9') {
    const groupNum = parseInt(key);
    state.controlGroups.set(groupNum, [...state.selectedEntities]);
    return;
  }

  if (!ctrlKey && key >= '1' && key <= '9') {
    const groupNum = parseInt(key);
    const group = state.controlGroups.get(groupNum);
    if (group) {
      state.selectedEntities = group.filter(e => e.alive);
    }
    return;
  }

  // Space: pause
  if (key === ' ') {
    gameState.paused = !gameState.paused;
    return;
  }

  // Escape: cancel placement
  if (key === 'Escape') {
    state.placementMode = null;
    state.selectedEntities = [];
  }
}

/**
 * Find an entity at a world position.
 */
function findEntityAtPosition(
  gameState: GameState,
  worldX: number,
  worldY: number,
  faction?: Faction,
): Entity | undefined {
  for (const entity of gameState.entities) {
    if (!entity.alive) continue;
    if (faction !== undefined && entity.faction !== faction) continue;

    const dx = worldX - entity.x;
    const dy = worldY - entity.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (entity.entityType === 'building') {
      if (worldX >= entity.x && worldX < entity.x + entity.width &&
          worldY >= entity.y && worldY < entity.y + entity.height) {
        return entity;
      }
    } else {
      if (dist < 0.5) return entity;
    }
  }
  return undefined;
}

/**
 * Convert screen coordinates to world coordinates.
 */
function screenToWorld(
  state: InputState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
): { x: number; y: number } {
  return {
    x: screenX - layout.viewport.x + state.camera.x,
    y: screenY - layout.viewport.y + state.camera.y,
  };
}

/**
 * Canvas 2D renderer: draws the game world, units, buildings, fog, and HUD.
 */

import type { GameState, Faction, Entity } from '../core/types';
import type { HudLayout, Rect } from '../ui/layout';
import { TILE_DEFS } from '../core/tiles';
import { FACTION_STATS } from '../core/stats';
import { computeLayout } from '../ui/layout';
import { getFogState } from '../sim/fog';

const TILE_SIZE = 16;

/**
 * Render the complete game frame.
 */
export function render(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  const { width, height } = layout.viewport;

  // Clear
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, width, height);

  // Draw world
  renderWorld(ctx, state, layout, camera, playerFaction);

  // Draw entities
  renderEntities(ctx, state, layout, camera, selectedEntities, playerFaction);

  // Draw fog overlay
  renderFogOverlay(ctx, state, layout, camera, playerFaction);

  // Draw HUD
  renderHUD(ctx, state, layout, selectedEntities, playerFaction);
}

/**
 * Render the tile map.
 */
function renderWorld(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  playerFaction: Faction,
): void {
  const map = state.map;
  const startX = Math.floor(camera.x / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endX = Math.min(map.width, startX + Math.ceil(layout.viewport.width / TILE_SIZE) + 1);
  const endY = Math.min(map.height, startY + Math.ceil(layout.viewport.height / TILE_SIZE) + 1);

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (x < 0 || x >= map.width || y < 0 || y >= map.height) continue;

      const tile = map.tiles[y * map.width + x];
      const def = TILE_DEFS[tile];
      const fog = getFogState(state, playerFaction, x, y);

      if (fog === 'unexplored') continue;

      const screenX = x * TILE_SIZE - camera.x + layout.viewport.x;
      const screenY = y * TILE_SIZE - camera.y + layout.viewport.y;

      // Use dark color for explored but not visible
      ctx.fillStyle = fog === 'visible' ? def.color : def.colorAlt;
      ctx.fillRect(screenX, screenY, TILE_SIZE, TILE_SIZE);

      // Add grid lines
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.strokeRect(screenX, screenY, TILE_SIZE, TILE_SIZE);
    }
  }
}

/**
 * Render entities (units and buildings).
 */
function renderEntities(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  for (const entity of state.entities) {
    if (!entity.alive) continue;

    // Skip if not visible
    const fog = getFogState(state, playerFaction, entity.x, entity.y);
    if (entity.faction !== playerFaction && fog !== 'visible') continue;

    const screenX = entity.x * TILE_SIZE - camera.x + layout.viewport.x;
    const screenY = entity.y * TILE_SIZE - camera.y + layout.viewport.y;

    // Skip if off-screen
    if (screenX + entity.width * TILE_SIZE < layout.viewport.x ||
        screenX > layout.viewport.x + layout.viewport.width ||
        screenY + entity.height * TILE_SIZE < layout.viewport.y ||
        screenY > layout.viewport.y + layout.viewport.height) {
      continue;
    }

    const isSelected = selectedEntities.includes(entity);
    const factionColor = FACTION_STATS[entity.faction].color;

    if (entity.entityType === 'building') {
      renderBuilding(ctx, entity, screenX, screenY, factionColor, isSelected);
    } else {
      renderUnit(ctx, entity, screenX, screenY, factionColor, isSelected);
    }
  }
}

/**
 * Render a building.
 */
function renderBuilding(
  ctx: CanvasRenderingContext2D,
  entity: Entity,
  screenX: number,
  screenY: number,
  color: string,
  isSelected: boolean,
): void {
  const w = entity.width * TILE_SIZE;
  const h = entity.height * TILE_SIZE;

  // Building body
  ctx.fillStyle = color;
  ctx.fillRect(screenX, screenY, w, h);

  // Building outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.strokeRect(screenX, screenY, w, h);

  // Selection highlight
  if (isSelected) {
    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;
    ctx.strokeRect(screenX - 1, screenY - 1, w + 2, h + 2);
  }

  // HP bar
  if (entity.hp < entity.maxHp) {
    const hpRatio = entity.hp / entity.maxHp;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY - 6, w, 4);
    ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
    ctx.fillRect(screenX, screenY - 6, w * hpRatio, 4);
  }

  // Progress bar (for construction)
  if (entity.progressTotal > 0 && entity.progressTicks < entity.progressTotal) {
    const progress = entity.progressTicks / entity.progressTotal;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY + h + 2, w, 4);
    ctx.fillStyle = '#0af';
    ctx.fillRect(screenX, screenY + h + 2, w * progress, 4);
  }
}

/**
 * Render a unit.
 */
function renderUnit(
  ctx: CanvasRenderingContext2D,
  entity: Entity,
  screenX: number,
  screenY: number,
  color: string,
  isSelected: boolean,
): void {
  const size = TILE_SIZE * 0.6;
  const centerX = screenX + TILE_SIZE / 2;
  const centerY = screenY + TILE_SIZE / 2;

  // Unit circle
  ctx.beginPath();
  ctx.arc(centerX, centerY, size / 2, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Selection highlight
  if (isSelected) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, size / 2 + 2, 0, Math.PI * 2);
    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // HP bar
  if (entity.hp < entity.maxHp) {
    const hpRatio = entity.hp / entity.maxHp;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY - 6, TILE_SIZE, 4);
    ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
    ctx.fillRect(screenX, screenY - 6, TILE_SIZE * hpRatio, 4);
  }

  // Projectile indicator
  if (entity.isProjectile) {
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
    ctx.fill();
  }
}

/**
 * Render fog overlay.
 */
function renderFogOverlay(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  playerFaction: Faction,
): void {
  const map = state.map;
  const startX = Math.floor(camera.x / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endX = Math.min(map.width, startX + Math.ceil(layout.viewport.width / TILE_SIZE) + 1);
  const endY = Math.min(map.height, startY + Math.ceil(layout.viewport.height / TILE_SIZE) + 1);

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (x < 0 || x >= map.width || y < 0 || y >= map.height) continue;

      const fog = getFogState(state, playerFaction, x, y);
      if (fog === 'visible') continue;

      const screenX = x * TILE_SIZE - camera.x + layout.viewport.x;
      const screenY = y * TILE_SIZE - camera.y + layout.viewport.y;

      if (fog === 'unexplored') {
        ctx.fillStyle = 'rgba(0,0,0,0.8)';
      } else {
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
      }
      ctx.fillRect(screenX, screenY, TILE_SIZE, TILE_SIZE);
    }
  }
}

/**
 * Render the HUD (resource bar, minimap, selection panel).
 */
function renderHUD(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  // Resource bar
  renderResourceBar(ctx, state, layout, playerFaction);

  // Minimap
  renderMinimap(ctx, state, layout, playerFaction);

  // Selection panel
  renderSelectionPanel(ctx, state, layout, selectedEntities, playerFaction);

  // Buttons
  renderButtons(ctx, state, layout, selectedEntities, playerFaction);

  // Speed/Pause buttons
  renderSpeedPause(ctx, state, layout);
}

/**
 * Render the resource bar.
 */
function renderResourceBar(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  playerFaction: Faction,
): void {
  const rb = layout.resourceBar;
  ctx.fillStyle = '#222';
  ctx.fillRect(rb.x, rb.y, rb.width, rb.height);

  ctx.fillStyle = '#fff';
  ctx.font = '14px monospace';
  ctx.textBaseline = 'middle';

  const resources = state.resources[playerFaction];
  ctx.fillText(`Gold: ${resources.gold}`, 10, rb.height / 2);
  ctx.fillText(`Wood: ${resources.wood}`, 150, rb.height / 2);
  ctx.fillText(`Supply: ${state.supplyUsed[playerFaction]}/${state.supplyCap[playerFaction]}`, 290, rb.height / 2);
  ctx.fillText(`Seed: ${state.seed}`, 450, rb.height / 2);
}

/**
 * Render the minimap.
 */
function renderMinimap(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  playerFaction: Faction,
): void {
  const mm = layout.minimap;
  const map = state.map;

  // Background
  ctx.fillStyle = '#111';
  ctx.fillRect(mm.x, mm.y, mm.width, mm.height);

  // Draw tiles
  const scaleX = mm.width / map.width;
  const scaleY = mm.height / map.height;

  for (let y = 0; y < map.height; y++) {
    for (let x = 0; x < map.width; x++) {
      const fog = getFogState(state, playerFaction, x, y);
      if (fog === 'unexplored') continue;

      const tile = map.tiles[y * map.width + x];
      const def = TILE_DEFS[tile];
      ctx.fillStyle = fog === 'visible' ? def.color : def.colorAlt;
      ctx.fillRect(
        mm.x + x * scaleX,
        mm.y + y * scaleY,
        Math.ceil(scaleX),
        Math.ceil(scaleY),
      );
    }
  }

  // Draw entities on minimap
  for (const entity of state.entities) {
    if (!entity.alive) continue;
    const fog = getFogState(state, playerFaction, entity.x, entity.y);
    if (entity.faction !== playerFaction && fog !== 'visible') continue;

    ctx.fillStyle = FACTION_STATS[entity.faction].minimapColor;
    const ex = mm.x + entity.x * scaleX;
    const ey = mm.y + entity.y * scaleY;
    ctx.fillRect(ex, ey, Math.max(2, scaleX), Math.max(2, scaleY));
  }
}

/**
 * Render the selection panel.
 */
function renderSelectionPanel(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  const sp = layout.selectionPanel;
  ctx.fillStyle = '#222';
  ctx.fillRect(sp.x, sp.y, sp.width, sp.height);

  if (selectedEntities.length === 0) return;

  ctx.fillStyle = '#fff';
  ctx.font = '12px monospace';
  ctx.textBaseline = 'top';

  const first = selectedEntities[0];
  let y = sp.y + 10;

  if (selectedEntities.length === 1) {
    ctx.fillText(`ID: ${first.id}`, sp.x + 10, y); y += 16;
    ctx.fillText(`HP: ${first.hp}/${first.maxHp}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Type: ${first.entityType} ${first.unitType ?? first.buildingType}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Faction: ${first.faction}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Order: ${first.order.type}`, sp.x + 10, y); y += 16;
  } else {
    ctx.fillText(`${selectedEntities.length} units selected`, sp.x + 10, y); y += 16;
  }
}

/**
 * Render action buttons.
 */
function renderButtons(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  for (const btn of layout.buttons) {
    ctx.fillStyle = '#444';
    ctx.fillRect(btn.rect.x, btn.rect.y, btn.rect.width, btn.rect.height);
    ctx.strokeStyle = '#666';
    ctx.strokeRect(btn.rect.x, btn.rect.y, btn.rect.width, btn.rect.height);

    ctx.fillStyle = '#fff';
    ctx.font = '10px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(btn.label, btn.rect.x + btn.rect.width / 2, btn.rect.y + btn.rect.height / 2);
    ctx.textAlign = 'left';
  }
}

/**
 * Render speed and pause buttons.
 */
function renderSpeedPause(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
): void {
  // Speed button
  ctx.fillStyle = '#444';
  ctx.fillRect(layout.speedButton.x, layout.speedButton.y,
    layout.speedButton.width, layout.speedButton.height);
  ctx.fillStyle = '#fff';
  ctx.font = '12px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(`${state.speed}x`,
    layout.speedButton.x + layout.speedButton.width / 2,
    layout.speedButton.y + layout.speedButton.height / 2);

  // Pause button
  ctx.fillStyle = state.paused ? '#a00' : '#444';
  ctx.fillRect(layout.pauseButton.x, layout.pauseButton.y,
    layout.pauseButton.width, layout.pauseButton.height);
  ctx.fillStyle = '#fff';
  ctx.fillText(state.paused ? '▶' : '⏸',
    layout.pauseButton.x + layout.pauseButton.width / 2,
    layout.pauseButton.y + layout.pauseButton.height / 2);
  ctx.textAlign = 'left';
}

/**
 * Campaign system: 5 levels of progressively increasing complexity.
 */

import type { GameConfig, Faction } from '../core/types';
import { CAMPAIGN_LEVELS } from '../core/types';

export interface CampaignLevel {
  readonly level: number;
  readonly name: string;
  readonly description: string;
  readonly difficulty: number;
  readonly unlocked: boolean;
}

/** Default campaign levels */
export const CAMPAIGN_DATA: CampaignLevel[] = [
  {
    level: 0,
    name: 'The Gathering',
    description: 'Learn to harvest resources and train workers.',
    difficulty: 1,
    unlocked: true,
  },
  {
    level: 1,
    name: 'First Blood',
    description: 'Build barracks and train your first army.',
    difficulty: 2,
    unlocked: false,
  },
  {
    level: 2,
    name: 'Siege',
    description: 'Expand your base and defend against waves.',
    difficulty: 3,
    unlocked: false,
  },
  {
    level: 3,
    name: 'Crossroads',
    description: 'Control chokepoints and manage two fronts.',
    difficulty: 4,
    unlocked: false,
  },
  {
    level: 4,
    name: 'Final Battle',
    description: 'Destroy the enemy stronghold.',
    difficulty: 5,
    unlocked: false,
  },
];

/** Create a game config for a campaign level */
export function createLevelConfig(
  seed: number,
  level: number,
  playerFaction: Faction,
): GameConfig {
  const campaignLevel = CAMPAIGN_DATA[level] ?? CAMPAIGN_DATA[0];
  return {
    seed,
    level,
    playerFaction,
    difficulty: campaignLevel.difficulty,
  };
}

/** Get the next level after completing the current one */
export function getNextLevel(currentLevel: number): number {
  return Math.min(currentLevel + 1, CAMPAIGN_LEVELS - 1);
}

/** Check if a level is unlocked based on completed levels */
export function isLevelUnlocked(level: number, completedLevels: number[]): boolean {
  if (level === 0) return true;
  return completedLevels.includes(level - 1);
}

/** Get level-specific seed */
export function getLevelSeed(baseSeed: number, level: number): number {
  return (baseSeed * 31 + level * 17) >>> 0;
}

/**
 * Main entry point: initializes the game loop, rendering, and input handling.
 */

import type { GameState, Faction } from './core/types';
import { TICK_RATE } from './core/types';
import { parseSeedFromURL } from './core/prng';
import { initGame, gameTick } from './sim/game';
import { createAIState, processAI } from './ai/ai';
import { computeLayout } from './ui/layout';
import { createInputState, handleMouseDown, handleMouseUp, handleKeyDown, defaultTransform } from './ui/input';
import { render } from './render/renderer';
import type { InputState } from './ui/input';
import type { HudLayout } from './ui/layout';

interface GameApp {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  state: GameState;
  input: InputState;
  layout: HudLayout;
  ai: ReturnType<typeof createAIState>;
  lastTime: number;
  accumulator: number;
  animFrame: number;
}

function createApp(): GameApp {
  const canvas = document.getElementById('game-canvas') as HTMLCanvasElement;
  if (!canvas) throw new Error('Canvas element not found');

  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Could not get 2D context');

  // Parse seed from URL
  const seed = parseSeedFromURL(window.location.href);
  const playerFaction: Faction = 'humans';

  // Initialize game
  const state = initGame({ seed, level: 0, playerFaction, difficulty: 1 });
  const ai = createAIState('orcs', 1);

  // Create input state
  const input = createInputState();

  // Compute layout
  const layout = computeLayout(canvas.width, canvas.height);

  return {
    canvas,
    ctx,
    state,
    input,
    layout,
    ai,
    lastTime: 0,
    accumulator: 0,
    animFrame: 0,
  };
}

function startGameLoop(app: GameApp): void {
  const tickInterval = 1000 / TICK_RATE;

  function gameLoop(currentTime: number): void {
    if (app.lastTime === 0) app.lastTime = currentTime;
    const deltaTime = currentTime - app.lastTime;
    app.lastTime = currentTime;

    // Fixed timestep simulation
    app.accumulator += deltaTime * app.state.speed;
    while (app.accumulator >= tickInterval) {
      gameTick(app.state);
      processAI(app.state, app.ai);
      app.accumulator -= tickInterval;
    }

    // Render
    render(app.ctx, app.state, app.layout, app.input.camera,
      app.input.selectedEntities, 'humans');

    // Request next frame
    app.animFrame = requestAnimationFrame(gameLoop);
  }

  app.animFrame = requestAnimationFrame(gameLoop);
}

function setupInput(app: GameApp): void {
  const transform = defaultTransform(app.canvas);

  app.canvas.addEventListener('mousedown', (e: MouseEvent) => {
    const pos = transform(e.clientX, e.clientY);
    handleMouseDown(app.input, app.state, app.layout, pos.x, pos.y,
      e.button, e.shiftKey, 'humans');
  });

  app.canvas.addEventListener('mouseup', (e: MouseEvent) => {
    const pos = transform(e.clientX, e.clientY);
    handleMouseUp(app.input, app.state, app.layout, pos.x, pos.y, 'humans');
  });

  app.canvas.addEventListener('contextmenu', (e: Event) => {
    e.preventDefault();
  });

  document.addEventListener('keydown', (e: KeyboardEvent) => {
    handleKeyDown(app.input, app.state, e.key, e.ctrlKey, 'humans');
  });

  // Resize handling
  window.addEventListener('resize', () => {
    app.canvas.width = window.innerWidth;
    app.canvas.height = window.innerHeight;
    app.layout = computeLayout(app.canvas.width, app.canvas.height);
  });
}

// Initialize when DOM is ready
if (typeof document !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => {
    try {
      const app = createApp();
      setupInput(app);
      startGameLoop(app);
    } catch (error) {
      console.error('Failed to initialize game:', error);
    }
  });
}

