    // Check entities
    for (const entity of state.entities) {
      expect(Number.isFinite(entity.x)).toBe(true);
      expect(Number.isFinite(entity.y)).toBe(true);
      expect(Number.isFinite(entity.hp)).toBe(true);
      expect(entity.hp).toBeGreaterThanOrEqual(0);
    }
  });
});

