/**
 * Order processing: training units, building construction, repair.
 */

import type { Entity, GameState, Faction, UnitType, BuildingType } from '../core/types';
import { FACTION_STATS, TECH_REQUIREMENTS } from '../core/stats';
import {
  createUnit, createBuilding, hasTechRequirements, getEntity,
} from './entities';
import { WORKER_REPAIR_RATE, WORKER_REPAIR_COST_GOLD, WORKER_REPAIR_COST_WOOD } from '../core/types';
import { findPath } from '../core/pathfinding';
import { vecDist } from '../core/types';

/**
 * Process training queues for buildings.
 */
export function processTraining(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'building') continue;
    if (entity.order.type !== 'train') continue;

    entity.progressTicks++;
    if (entity.progressTicks >= entity.progressTotal) {
      // Training complete — spawn unit
      completeTraining(state, entity);
    }
  }
}

/**
 * Process building construction.
 */
export function processConstruction(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'building') continue;
    if (entity.progressTotal <= 0) continue; // Not under construction
    if (entity.progressTicks >= entity.progressTotal) continue; // Already complete

    entity.progressTicks++;
    // Scale HP based on progress
    const progress = entity.progressTicks / entity.progressTotal;
    const bt = entity.buildingType;
    if (!bt) continue;
    const targetHp = FACTION_STATS[entity.faction].buildings[bt].hp;
    entity.hp = Math.max(1, Math.floor(targetHp * progress));

    if (entity.progressTicks >= entity.progressTotal) {
      entity.hp = targetHp;
      // Mark tiles as walkable=false for the building footprint
      const map = state.map;
      for (let dy = 0; dy < entity.height; dy++) {
        for (let dx = 0; dx < entity.width; dx++) {
          const tx = entity.x + dx;
          const ty = entity.y + dy;
          if (tx >= 0 && tx < map.width && ty >= 0 && ty < map.height) {
            map.walkable[ty * map.width + tx] = false;
          }
        }
      }
    }
  }
}

/**
 * Process repair orders.
 */
export function processRepair(state: GameState): void {
  for (const entity of state.entities) {
    if (!entity.alive || entity.entityType !== 'unit') continue;
    if (entity.order.type !== 'repair') continue;
    if (entity.unitType !== 'worker') continue;

    const targetId = entity.order.targetId;
    if (targetId === undefined) {
      entity.order = { type: 'idle' };
      continue;
    }

    const target = getEntity(state, targetId);
    if (!target || !target.alive || target.entityType !== 'building') {
      entity.order = { type: 'idle' };
      continue;
    }

    // Check if building needs repair
    const bt = target.buildingType;
    if (!bt) {
      entity.order = { type: 'idle' };
      continue;
    }
    const buildingStats = FACTION_STATS[target.faction].buildings[bt];
    if (target.hp >= buildingStats.hp) {
      entity.order = { type: 'idle' };
      continue;
    }

    const dist = vecDist(entity, target);
    if (dist < 2) {
      // In range — repair
      const goldCost = WORKER_REPAIR_COST_GOLD;
      const woodCost = WORKER_REPAIR_COST_WOOD;
      if (state.resources[entity.faction].gold >= goldCost &&
          state.resources[entity.faction].wood >= woodCost) {
        const repairAmount = Math.min(WORKER_REPAIR_RATE, buildingStats.hp - target.hp);
        state.resources[entity.faction].gold -= goldCost * repairAmount;
        state.resources[entity.faction].wood -= woodCost * repairAmount;
        target.hp = Math.min(buildingStats.hp, target.hp + repairAmount);
      } else {
        entity.order = { type: 'idle' };
      }
    } else {
      // Move to building
      if (entity.path.length === 0 || entity.pathIndex >= entity.path.length) {
        const path = findPath(state.map, Math.floor(entity.x), Math.floor(entity.y),
          Math.floor(target.x), Math.floor(target.y));
        entity.path = path ?? [];
        entity.pathIndex = 0;
      }
    }
  }
}

/**
 * Enqueue a unit training order at a building.
 */
export function enqueueTraining(
  state: GameState,
  building: Entity,
  unitType: UnitType,
): boolean {
  if (building.entityType !== 'building' || !building.buildingType) return false;
  if (building.buildingType !== 'barracks' && building.buildingType !== 'townHall') return false;

  const faction = building.faction;
  const stats = FACTION_STATS[faction].units[unitType];

  // Check tech requirements
  const reqs = TECH_REQUIREMENTS[unitType] ?? [];
  if (!hasTechRequirements(state, faction, reqs)) return false;

  // Check supply
  if (state.supplyUsed[faction] + stats.supplyCost > state.supplyCap[faction]) return false;

  // Check resources
  if (state.resources[faction].gold < stats.goldCost) return false;
  if (state.resources[faction].wood < stats.woodCost) return false;

  // Deduct resources
  state.resources[faction].gold -= stats.goldCost;
  state.resources[faction].wood -= stats.woodCost;
  state.supplyUsed[faction] += stats.supplyCost;

  // Set building to training
  building.order = { type: 'train' };
  building.progressTicks = 0;
  building.progressTotal = stats.trainTime;

  return true;
}

/**
 * Complete training: spawn the unit near the building.
 */
function completeTraining(state: GameState, building: Entity): void {
  if (!building.buildingType) return;

  const faction = building.faction;
  const unitType = getUnitTypeForBuilding(building.buildingType);
  if (!unitType) return;

  // Find spawn location
  const spawnPos = findSpawnPosition(state, building);
  if (!spawnPos) return;

  createUnit(state, faction, unitType, spawnPos.x, spawnPos.y);

  // Reset building
  building.order = { type: 'idle' };
  building.progressTicks = 0;
  building.progressTotal = 0;
}

/**
 * Get the unit type for a building's training queue.
 */
function getUnitTypeForBuilding(buildingType: BuildingType): UnitType | null {
  switch (buildingType) {
    case 'townHall': return 'worker';
    case 'barracks': return 'melee'; // Simplified — would track in queue
    default: return null;
  }
}

/**
 * Find a spawn position near a building that's not occupied.
 */
function findSpawnPosition(state: GameState, building: Entity): { x: number; y: number } | null {
  // Try positions adjacent to the building
  const positions: Array<{ x: number; y: number }> = [];

  for (let dx = -1; dx <= building.width; dx++) {
    positions.push({ x: building.x + dx, y: building.y - 1 });
    positions.push({ x: building.x + dx, y: building.y + building.height });
  }
  for (let dy = 0; dy < building.height; dy++) {
    positions.push({ x: building.x - 1, y: building.y + dy });
    positions.push({ x: building.x + building.width, y: building.y + dy });
  }

  // Sort by distance to building center
  const cx = building.x + building.width / 2;
  const cy = building.y + building.height / 2;
  positions.sort((a, b) => {
    const da = Math.sqrt((a.x - cx) ** 2 + (a.y - cy) ** 2);
    const db = Math.sqrt((b.x - cx) ** 2 + (b.y - cy) ** 2);
    return da - db;
  });

  for (const pos of positions) {
    if (pos.x < 0 || pos.x >= state.map.width || pos.y < 0 || pos.y >= state.map.height) continue;
    if (!state.map.walkable[pos.y * state.map.width + pos.x]) continue;

    // Check if position is occupied by another unit
    const occupied = state.entities.some(e =>
      e.alive && e.entityType === 'unit' &&
      Math.abs(e.x - pos.x) < 0.5 && Math.abs(e.y - pos.y) < 0.5,
    );

    if (!occupied) return pos;
  }

  // C6: find nearest free walkable tile
  for (let r = 2; r < 10; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
        const nx = building.x + building.width / 2 + dx;
        const ny = building.y + building.height / 2 + dy;
        if (nx < 0 || nx >= state.map.width || ny < 0 || ny >= state.map.height) continue;
        const tx = Math.floor(nx);
        const ty = Math.floor(ny);
        if (!state.map.walkable[ty * state.map.width + tx]) continue;
        const occupied = state.entities.some(e =>
          e.alive && e.entityType === 'unit' &&
          Math.abs(e.x - nx) < 0.5 && Math.abs(e.y - ny) < 0.5,
        );
        if (!occupied) return { x: nx, y: ny };
      }
    }
  }

  return null;
}

/**
 * Place a building: validate placement and start construction.
 */
export function placeBuilding(
  state: GameState,
  faction: Faction,
  buildingType: BuildingType,
  x: number,
  y: number,
): Entity | null {
  const stats = FACTION_STATS[faction].buildings[buildingType];

  // Check resources
  if (state.resources[faction].gold < stats.goldCost) return null;
  if (state.resources[faction].wood < stats.woodCost) return null;

  // Check tech requirements
  const reqs = TECH_REQUIREMENTS[buildingType] ?? [];
  if (!hasTechRequirements(state, faction, reqs)) return null;

  // Validate placement
  if (!isValidPlacement(state, x, y, stats.width, stats.height)) return null;

  // Deduct resources
  state.resources[faction].gold -= stats.goldCost;
  state.resources[faction].wood -= stats.woodCost;

  // Create building
  const building = createBuilding(state, faction, buildingType, x, y, true);
  return building;
}

/**
 * Check if a building placement is valid (C7).
 */
export function isValidPlacement(
  state: GameState,
  x: number,
  y: number,
  width: number,
  height: number,
): boolean {
  // Check bounds
  if (x < 0 || x + width > state.map.width) return false;
  if (y < 0 || y + height > state.map.height) return false;

  // Check all tiles in footprint
  for (let dy = 0; dy < height; dy++) {
    for (let dx = 0; dx < width; dx++) {
      const tx = x + dx;
      const ty = y + dy;
      const idx = ty * state.map.width + tx;

      // Check walkability
      if (!state.map.walkable[idx]) return false;

      // Check tile type (not water, rock, gold mine, forest)
      const tile = state.map.tiles[idx];
      if (tile === 'water' || tile === 'rock' || tile === 'goldMine' || tile === 'forest') {
        return false;
      }

      // Check for existing buildings
      for (const entity of state.entities) {
        if (!entity.alive || entity.entityType !== 'building') continue;
        if (tx >= entity.x && tx < entity.x + entity.width &&
            ty >= entity.y && ty < entity.y + entity.height) {
          return false;
        }
      }

      // Check for units on the tile
      for (const entity of state.entities) {
        if (!entity.alive || entity.entityType !== 'unit') continue;
        if (Math.abs(entity.x - tx) < 0.5 && Math.abs(entity.y - ty) < 0.5) {
          return false;
        }
      }
    }
  }

  return true;
}

/**
 * Input handling: translates DOM events into simulation orders.
 * Contains no game logic of its own — only input → order mapping.
 */

import type { GameState, Faction, Entity, BuildingType, UnitType } from '../core/types';
import type { HudLayout } from './layout';
import { hitTest, minimapToWorld } from './layout';
import { assignMoveOrder, assignHarvestOrder } from '../sim/movement';
import { enqueueTraining, placeBuilding } from '../sim/orders';

export interface InputState {
  selectedEntities: Entity[];
  controlGroups: Map<number, Entity[]>;
  isDragging: boolean;
  dragStart: { x: number; y: number } | null;
  dragEnd: { x: number; y: number } | null;
  placementMode: BuildingType | null;
  camera: { x: number; y: number };
}

/** Create initial input state */
export function createInputState(): InputState {
  return {
    selectedEntities: [],
    controlGroups: new Map(),
    isDragging: false,
    dragStart: null,
    dragEnd: null,
    placementMode: null,
    camera: { x: 0, y: 0 },
  };
}

/** Get client→canvas coordinate transform */
export type CoordTransform = (clientX: number, clientY: number) => { x: number; y: number };

/** Default transform using getBoundingClientRect */
export function defaultTransform(canvas: HTMLCanvasElement): CoordTransform {
  return (clientX: number, clientY: number) => {
    const rect = canvas.getBoundingClientRect();
    return {
      x: clientX - rect.left,
      y: clientY - rect.top,
    };
  };
}

/**
 * Handle a mouse down event.
 */
export function handleMouseDown(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  button: number,
  shiftKey: boolean,
  playerFaction: Faction,
): void {
  const element = hitTest(layout, screenX, screenY);

  if (button === 0) {
    // Left click
    if (element === 'viewport') {
      handleViewportLeftClick(state, gameState, layout, screenX, screenY, shiftKey, playerFaction);
    } else if (element === 'minimap') {
      handleMinimapClick(state, layout, screenX, screenY, gameState.map.width, gameState.map.height);
    } else if (element !== null && (element.startsWith('train_') || element.startsWith('build_'))) {
      handleButtonClick(state, gameState, element, playerFaction);
    } else if (element === 'speed') {
      gameState.speed = gameState.speed >= 2 ? 1 : gameState.speed + 1;
    } else if (element === 'pause') {
      gameState.paused = !gameState.paused;
    }
  } else if (button === 2) {
    // Right click
    if (element === 'viewport') {
      handleViewportRightClick(state, gameState, layout, screenX, screenY, playerFaction);
    }
  }
}

/**
 * Handle left click on the viewport.
 */
function handleViewportLeftClick(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  shiftKey: boolean,
  playerFaction: Faction,
): void {
  const worldPos = screenToWorld(state, layout, screenX, screenY);

  // If in placement mode, try to place building
  if (state.placementMode) {
    placeBuilding(gameState, playerFaction, state.placementMode,
      Math.floor(worldPos.x), Math.floor(worldPos.y));
    state.placementMode = null;
    // Assign idle worker to build
    const worker = state.selectedEntities.find(e =>
      e.entityType === 'unit' && e.unitType === 'worker',
    );
    if (worker) {
      // Building was placed, assign worker
    }
    return;
  }

  // Start drag selection
  state.isDragging = true;
  state.dragStart = { x: screenX, y: screenY };
  state.dragEnd = { x: screenX, y: screenY };

  // Try to select entity at click position
  const clickedEntity = findEntityAtPosition(gameState, worldPos.x, worldPos.y, playerFaction);

  if (clickedEntity) {
    if (shiftKey) {
      // Add to selection
      if (!state.selectedEntities.includes(clickedEntity)) {
        state.selectedEntities.push(clickedEntity);
      }
    } else {
      state.selectedEntities = [clickedEntity];
    }
  } else if (!shiftKey) {
    state.selectedEntities = [];
  }
}

/**
 * Handle right click on the viewport (context-sensitive order).
 */
function handleViewportRightClick(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  playerFaction: Faction,
): void {
  if (state.selectedEntities.length === 0) return;

  const worldPos = screenToWorld(state, layout, screenX, screenY);
  const targetEntity = findEntityAtPosition(gameState, worldPos.x, worldPos.y);

  for (const entity of state.selectedEntities) {
    if (entity.faction !== playerFaction) continue;
    if (entity.entityType !== 'unit') continue;

    if (targetEntity && targetEntity.faction !== playerFaction) {
      // Attack enemy
      entity.order = { type: 'attack', targetId: targetEntity.id };
    } else if (targetEntity && targetEntity.buildingType === 'goldMine') {
      // Harvest gold
      assignHarvestOrder(gameState, entity, targetEntity.id);
    } else if (targetEntity && targetEntity.faction === playerFaction &&
               targetEntity.entityType === 'building' && targetEntity.hp < targetEntity.maxHp) {
      // Repair
      entity.order = { type: 'repair', targetId: targetEntity.id };
      entity.repairTarget = targetEntity.id;
    } else {
      // Move to position
      assignMoveOrder(gameState, entity, worldPos.x, worldPos.y);
    }
  }
}

/**
 * Handle minimap click.
 */
function handleMinimapClick(
  state: InputState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  mapWidth: number,
  mapHeight: number,
): void {
  const worldPos = minimapToWorld(layout, screenX, screenY, mapWidth, mapHeight);
  state.camera.x = worldPos.x - layout.viewport.width / 2;
  state.camera.y = worldPos.y - layout.viewport.height / 2;
}

/**
 * Handle button click (train/build).
 */
function handleButtonClick(
  state: InputState,
  gameState: GameState,
  buttonId: string,
  playerFaction: Faction,
): void {
  if (buttonId.startsWith('train_')) {
    const unitType = buttonId.replace('train_', '') as UnitType;
    const building = state.selectedEntities.find(e =>
      e.entityType === 'building' && (e.buildingType === 'barracks' || e.buildingType === 'townHall'),
    );
    if (building) {
      enqueueTraining(gameState, building, unitType);
    }
  } else if (buttonId.startsWith('build_')) {
    const buildingType = buttonId.replace('build_', '') as BuildingType;
    state.placementMode = buildingType;
  }
}

/**
 * Handle mouse up (end drag selection).
 */
export function handleMouseUp(
  state: InputState,
  gameState: GameState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
  playerFaction: Faction,
): void {
  if (!state.isDragging || !state.dragStart) return;

  const dragEnd = { x: screenX, y: screenY };
  const dx = Math.abs(dragEnd.x - state.dragStart.x);
  const dy = Math.abs(dragEnd.y - state.dragStart.y);

  if (dx > 5 || dy > 5) {
    // Box selection
    const startWorld = screenToWorld(state, layout, state.dragStart.x, state.dragStart.y);
    const endWorld = screenToWorld(state, layout, dragEnd.x, dragEnd.y);

    const minX = Math.min(startWorld.x, endWorld.x);
    const maxX = Math.max(startWorld.x, endWorld.x);
    const minY = Math.min(startWorld.y, endWorld.y);
    const maxY = Math.max(startWorld.y, endWorld.y);

    state.selectedEntities = gameState.entities.filter(e =>
      e.alive && e.faction === playerFaction &&
      e.x >= minX && e.x <= maxX && e.y >= minY && e.y <= maxY,
    );
  }

  state.isDragging = false;
  state.dragStart = null;
  state.dragEnd = null;
}

/**
 * Handle keyboard input.
 */
export function handleKeyDown(
  state: InputState,
  gameState: GameState,
  key: string,
  ctrlKey: boolean,
  _playerFaction: Faction,
): void {
  // Control groups
  if (ctrlKey && key >= '1' && key <= '9') {
    const groupNum = parseInt(key);
    state.controlGroups.set(groupNum, [...state.selectedEntities]);
    return;
  }

  if (!ctrlKey && key >= '1' && key <= '9') {
    const groupNum = parseInt(key);
    const group = state.controlGroups.get(groupNum);
    if (group) {
      state.selectedEntities = group.filter(e => e.alive);
    }
    return;
  }

  // Space: pause
  if (key === ' ') {
    gameState.paused = !gameState.paused;
    return;
  }

  // Escape: cancel placement
  if (key === 'Escape') {
    state.placementMode = null;
    state.selectedEntities = [];
  }
}

/**
 * Find an entity at a world position.
 */
function findEntityAtPosition(
  gameState: GameState,
  worldX: number,
  worldY: number,
  faction?: Faction,
): Entity | undefined {
  for (const entity of gameState.entities) {
    if (!entity.alive) continue;
    if (faction !== undefined && entity.faction !== faction) continue;

    if (entity.entityType === 'building') {
      if (worldX >= entity.x && worldX < entity.x + entity.width &&
          worldY >= entity.y && worldY < entity.y + entity.height) {
        return entity;
      }
    } else {
      const dx = worldX - entity.x;
      const dy = worldY - entity.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 0.5) return entity;
    }
  }
  return undefined;
}

/**
 * Convert screen coordinates to world coordinates.
 */
function screenToWorld(
  state: InputState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
): { x: number; y: number } {
  return {
    x: screenX - layout.viewport.x + state.camera.x,
    y: screenY - layout.viewport.y + state.camera.y,
  };
}

/**
 * Canvas 2D renderer: draws the game world, units, buildings, fog, and HUD.
 */

import type { GameState, Faction, Entity } from '../core/types';
import type { HudLayout } from '../ui/layout';
import { TILE_DEFS } from '../core/tiles';
import { FACTION_STATS } from '../core/stats';
import { getFogState } from '../sim/fog';

const TILE_SIZE = 16;

/**
 * Render the complete game frame.
 */
export function render(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  const { width, height } = layout.viewport;

  // Clear
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, width, height);

  // Draw world
  renderWorld(ctx, state, layout, camera, playerFaction);

  // Draw entities
  renderEntities(ctx, state, layout, camera, selectedEntities, playerFaction);

  // Draw fog overlay
  renderFogOverlay(ctx, state, layout, camera, playerFaction);

  // Draw HUD
  renderHUD(ctx, state, layout, selectedEntities, playerFaction);
}

/**
 * Render the tile map.
 */
function renderWorld(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  playerFaction: Faction,
): void {
  const map = state.map;
  const startX = Math.floor(camera.x / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endX = Math.min(map.width, startX + Math.ceil(layout.viewport.width / TILE_SIZE) + 1);
  const endY = Math.min(map.height, startY + Math.ceil(layout.viewport.height / TILE_SIZE) + 1);

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (x < 0 || x >= map.width || y < 0 || y >= map.height) continue;

      const tile = map.tiles[y * map.width + x];
      const def = TILE_DEFS[tile];
      const fog = getFogState(state, playerFaction, x, y);

      if (fog === 'unexplored') continue;

      const screenX = x * TILE_SIZE - camera.x + layout.viewport.x;
      const screenY = y * TILE_SIZE - camera.y + layout.viewport.y;

      // Use dark color for explored but not visible
      ctx.fillStyle = fog === 'visible' ? def.color : def.colorAlt;
      ctx.fillRect(screenX, screenY, TILE_SIZE, TILE_SIZE);

      // Add grid lines
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.strokeRect(screenX, screenY, TILE_SIZE, TILE_SIZE);
    }
  }
}

/**
 * Render entities (units and buildings).
 */
function renderEntities(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  for (const entity of state.entities) {
    if (!entity.alive) continue;

    // Skip if not visible
    const fog = getFogState(state, playerFaction, entity.x, entity.y);
    if (entity.faction !== playerFaction && fog !== 'visible') continue;

    const screenX = entity.x * TILE_SIZE - camera.x + layout.viewport.x;
    const screenY = entity.y * TILE_SIZE - camera.y + layout.viewport.y;

    // Skip if off-screen
    if (screenX + entity.width * TILE_SIZE < layout.viewport.x ||
        screenX > layout.viewport.x + layout.viewport.width ||
        screenY + entity.height * TILE_SIZE < layout.viewport.y ||
        screenY > layout.viewport.y + layout.viewport.height) {
      continue;
    }

    const isSelected = selectedEntities.includes(entity);
    const factionColor = FACTION_STATS[entity.faction].color;

    if (entity.entityType === 'building') {
      renderBuilding(ctx, entity, screenX, screenY, factionColor, isSelected);
    } else {
      renderUnit(ctx, entity, screenX, screenY, factionColor, isSelected);
    }
  }
}

/**
 * Render a building.
 */
function renderBuilding(
  ctx: CanvasRenderingContext2D,
  entity: Entity,
  screenX: number,
  screenY: number,
  color: string,
  isSelected: boolean,
): void {
  const w = entity.width * TILE_SIZE;
  const h = entity.height * TILE_SIZE;

  // Building body
  ctx.fillStyle = color;
  ctx.fillRect(screenX, screenY, w, h);

  // Building outline
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.strokeRect(screenX, screenY, w, h);

  // Selection highlight
  if (isSelected) {
    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;
    ctx.strokeRect(screenX - 1, screenY - 1, w + 2, h + 2);
  }

  // HP bar
  if (entity.hp < entity.maxHp) {
    const hpRatio = entity.hp / entity.maxHp;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY - 6, w, 4);
    ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
    ctx.fillRect(screenX, screenY - 6, w * hpRatio, 4);
  }

  // Progress bar (for construction)
  if (entity.progressTotal > 0 && entity.progressTicks < entity.progressTotal) {
    const progress = entity.progressTicks / entity.progressTotal;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY + h + 2, w, 4);
    ctx.fillStyle = '#0af';
    ctx.fillRect(screenX, screenY + h + 2, w * progress, 4);
  }
}

/**
 * Render a unit.
 */
function renderUnit(
  ctx: CanvasRenderingContext2D,
  entity: Entity,
  screenX: number,
  screenY: number,
  color: string,
  isSelected: boolean,
): void {
  const size = TILE_SIZE * 0.6;
  const centerX = screenX + TILE_SIZE / 2;
  const centerY = screenY + TILE_SIZE / 2;

  // Unit circle
  ctx.beginPath();
  ctx.arc(centerX, centerY, size / 2, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.stroke();

  // Selection highlight
  if (isSelected) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, size / 2 + 2, 0, Math.PI * 2);
    ctx.strokeStyle = '#0f0';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // HP bar
  if (entity.hp < entity.maxHp) {
    const hpRatio = entity.hp / entity.maxHp;
    ctx.fillStyle = '#333';
    ctx.fillRect(screenX, screenY - 6, TILE_SIZE, 4);
    ctx.fillStyle = hpRatio > 0.5 ? '#0f0' : hpRatio > 0.25 ? '#ff0' : '#f00';
    ctx.fillRect(screenX, screenY - 6, TILE_SIZE * hpRatio, 4);
  }

  // Projectile indicator
  if (entity.isProjectile) {
    ctx.fillStyle = '#ff0';
    ctx.beginPath();
    ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
    ctx.fill();
  }
}

/**
 * Render fog overlay.
 */
function renderFogOverlay(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  camera: { x: number; y: number },
  playerFaction: Faction,
): void {
  const map = state.map;
  const startX = Math.floor(camera.x / TILE_SIZE);
  const startY = Math.floor(camera.y / TILE_SIZE);
  const endX = Math.min(map.width, startX + Math.ceil(layout.viewport.width / TILE_SIZE) + 1);
  const endY = Math.min(map.height, startY + Math.ceil(layout.viewport.height / TILE_SIZE) + 1);

  for (let y = startY; y < endY; y++) {
    for (let x = startX; x < endX; x++) {
      if (x < 0 || x >= map.width || y < 0 || y >= map.height) continue;

      const fog = getFogState(state, playerFaction, x, y);
      if (fog === 'visible') continue;

      const screenX = x * TILE_SIZE - camera.x + layout.viewport.x;
      const screenY = y * TILE_SIZE - camera.y + layout.viewport.y;

      if (fog === 'unexplored') {
        ctx.fillStyle = 'rgba(0,0,0,0.8)';
      } else {
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
      }
      ctx.fillRect(screenX, screenY, TILE_SIZE, TILE_SIZE);
    }
  }
}

/**
 * Render the HUD (resource bar, minimap, selection panel).
 */
function renderHUD(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  selectedEntities: Entity[],
  playerFaction: Faction,
): void {
  // Resource bar
  renderResourceBar(ctx, state, layout, playerFaction);

  // Minimap
  renderMinimap(ctx, state, layout, playerFaction);

  // Selection panel
  renderSelectionPanel(ctx, layout, selectedEntities);

  // Buttons
  renderButtons(ctx, layout);

  // Speed/Pause buttons
  renderSpeedPause(ctx, state, layout);
}

/**
 * Render the resource bar.
 */
function renderResourceBar(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  playerFaction: Faction,
): void {
  const rb = layout.resourceBar;
  ctx.fillStyle = '#222';
  ctx.fillRect(rb.x, rb.y, rb.width, rb.height);

  ctx.fillStyle = '#fff';
  ctx.font = '14px monospace';
  ctx.textBaseline = 'middle';

  const resources = state.resources[playerFaction];
  ctx.fillText(`Gold: ${resources.gold}`, 10, rb.height / 2);
  ctx.fillText(`Wood: ${resources.wood}`, 150, rb.height / 2);
  ctx.fillText(`Supply: ${state.supplyUsed[playerFaction]}/${state.supplyCap[playerFaction]}`, 290, rb.height / 2);
  ctx.fillText(`Seed: ${state.seed}`, 450, rb.height / 2);
}

/**
 * Render the minimap.
 */
function renderMinimap(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
  playerFaction: Faction,
): void {
  const mm = layout.minimap;
  const map = state.map;

  // Background
  ctx.fillStyle = '#111';
  ctx.fillRect(mm.x, mm.y, mm.width, mm.height);

  // Draw tiles
  const scaleX = mm.width / map.width;
  const scaleY = mm.height / map.height;

  for (let y = 0; y < map.height; y++) {
    for (let x = 0; x < map.width; x++) {
      const fog = getFogState(state, playerFaction, x, y);
      if (fog === 'unexplored') continue;

      const tile = map.tiles[y * map.width + x];
      const def = TILE_DEFS[tile];
      ctx.fillStyle = fog === 'visible' ? def.color : def.colorAlt;
      ctx.fillRect(
        mm.x + x * scaleX,
        mm.y + y * scaleY,
        Math.ceil(scaleX),
        Math.ceil(scaleY),
      );
    }
  }

  // Draw entities on minimap
  for (const entity of state.entities) {
    if (!entity.alive) continue;
    const fog = getFogState(state, playerFaction, entity.x, entity.y);
    if (entity.faction !== playerFaction && fog !== 'visible') continue;

    ctx.fillStyle = FACTION_STATS[entity.faction].minimapColor;
    const ex = mm.x + entity.x * scaleX;
    const ey = mm.y + entity.y * scaleY;
    ctx.fillRect(ex, ey, Math.max(2, scaleX), Math.max(2, scaleY));
  }
}

/**
 * Render the selection panel.
 */
function renderSelectionPanel(
  ctx: CanvasRenderingContext2D,
  layout: HudLayout,
  selectedEntities: Entity[],
): void {
  const sp = layout.selectionPanel;
  ctx.fillStyle = '#222';
  ctx.fillRect(sp.x, sp.y, sp.width, sp.height);

  if (selectedEntities.length === 0) return;

  ctx.fillStyle = '#fff';
  ctx.font = '12px monospace';
  ctx.textBaseline = 'top';

  const first = selectedEntities[0];
  let y = sp.y + 10;

  if (selectedEntities.length === 1) {
    ctx.fillText(`ID: ${first.id}`, sp.x + 10, y); y += 16;
    ctx.fillText(`HP: ${first.hp}/${first.maxHp}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Type: ${first.entityType} ${first.unitType ?? first.buildingType}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Faction: ${first.faction}`, sp.x + 10, y); y += 16;
    ctx.fillText(`Order: ${first.order.type}`, sp.x + 10, y); y += 16;
  } else {
    ctx.fillText(`${selectedEntities.length} units selected`, sp.x + 10, y);
  }
}

/**
 * Render action buttons.
 */
function renderButtons(
  ctx: CanvasRenderingContext2D,
  layout: HudLayout,
): void {
  for (const btn of layout.buttons) {
    ctx.fillStyle = '#444';
    ctx.fillRect(btn.rect.x, btn.rect.y, btn.rect.width, btn.rect.height);
    ctx.strokeStyle = '#666';
    ctx.strokeRect(btn.rect.x, btn.rect.y, btn.rect.width, btn.rect.height);

    ctx.fillStyle = '#fff';
    ctx.font = '10px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(btn.label, btn.rect.x + btn.rect.width / 2, btn.rect.y + btn.rect.height / 2);
    ctx.textAlign = 'left';
  }
}

/**
 * Render speed and pause buttons.
 */
function renderSpeedPause(
  ctx: CanvasRenderingContext2D,
  state: GameState,
  layout: HudLayout,
): void {
  // Speed button
  ctx.fillStyle = '#444';
  ctx.fillRect(layout.speedButton.x, layout.speedButton.y,
    layout.speedButton.width, layout.speedButton.height);
  ctx.fillStyle = '#fff';
  ctx.font = '12px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(`${state.speed}x`,
    layout.speedButton.x + layout.speedButton.width / 2,
    layout.speedButton.y + layout.speedButton.height / 2);

  // Pause button
  ctx.fillStyle = state.paused ? '#a00' : '#444';
  ctx.fillRect(layout.pauseButton.x, layout.pauseButton.y,
    layout.pauseButton.width, layout.pauseButton.height);
  ctx.fillStyle = '#fff';
  ctx.fillText(state.paused ? '▶' : '⏸',
    layout.pauseButton.x + layout.pauseButton.width / 2,
    layout.pauseButton.y + layout.pauseButton.height / 2);
  ctx.textAlign = 'left';
}

/**
 * Map generation: WFC + playability pass + start-location placement.
 * Generates a complete GameMap for a given seed and level.
 */

import type { PRNG } from '../core/prng';
import type { TileType, Vec2, GameMap, Faction, FogState } from '../core/types';
import {
  MIN_START_SEPARATION_RATIO, MIN_START_LINE_SEPARATION_RATIO,
  MIN_BUILD_AREA,
} from '../core/types';
import { vecDist, vecManhattan } from '../core/types';
import { TILE_DEFS } from '../core/tiles';
import { findNearestWalkable } from '../core/pathfinding';
import { createPRNG } from '../core/prng';
import { runWFC, ensureGoldMines, ensureForestNearStarts } from './wfc';

/** Map dimensions per campaign level */
export const LEVEL_MAP_SIZES: ReadonlyArray<{ width: number; height: number }> = [
  { width: 32, height: 32 },
  { width: 48, height: 48 },
  { width: 64, height: 64 },
  { width: 80, height: 80 },
  { width: 96, height: 96 },
];

/** Number of extra water/rock tiles to add per level (higher = more constrained) */
const LEVEL_TERRAIN_ROUGHNESS = [0, 2, 5, 8, 12];

function makeFog(width: number, height: number): FogState[] {
  return new Array<FogState>(width * height).fill('unexplored');
}

function makeWalkable(tiles: TileType[], width: number, height: number): boolean[] {
  const walkable = new Array<boolean>(width * height);
  for (let i = 0; i < tiles.length; i++) {
    walkable[i] = TILE_DEFS[tiles[i]].walkable;
  }
  return walkable;
}

/**
 * Find a contiguous buildable area of at least minSize x minSize tiles
 * starting from (sx, sy). Returns the set of buildable tiles.
 */
function findBuildableArea(
  tiles: TileType[],
  width: number,
  height: number,
  sx: number,
  sy: number,
): Vec2[] {
  const area: Vec2[] = [];
  const visited = new Set<number>();

  // BFS from start to find connected buildable tiles
  const queue: Vec2[] = [{ x: sx, y: sy }];
  while (queue.length > 0) {
    const pos = queue.shift() as Vec2;
    const idx = pos.y * width + pos.x;
    if (visited.has(idx)) continue;
    visited.add(idx);

    const tile = tiles[idx];
    if (!TILE_DEFS[tile].buildable) continue;

    area.push(pos);

    // Check 4-cardinal neighbors
    const dirs = [
      { x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 },
    ];
    for (const d of dirs) {
      const nx = pos.x + d.x;
      const ny = pos.y + d.y;
      if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
        queue.push({ x: nx, y: ny });
      }
    }
  }

  return area;
}

/**
 * Check if there's a contiguous buildable area of at least minSize x minSize
 * near the given position.
 */
function hasBuildableArea(
  tiles: TileType[],
  width: number,
  height: number,
  sx: number,
  sy: number,
  minSize: number,
): boolean {
  // Check a region around the start for a buildable area
  const regionSize = minSize + 4;
  let maxContiguous = 0;

  for (let dy = -regionSize; dy <= regionSize; dy++) {
    for (let dx = -regionSize; dx <= regionSize; dx++) {
      const nx = sx + dx;
      const ny = sy + dy;
      if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;

      const area = findBuildableArea(tiles, width, height, nx, ny);
      if (area.length > maxContiguous) {
        maxContiguous = area.length;
      }
    }
  }

  return maxContiguous >= minSize * minSize;
}

/** Find valid start locations on the map */
function findStartLocations(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
): Vec2[] {
  const starts: Vec2[] = [];
  const maxDim = Math.max(width, height);
  const minSep = Math.floor(maxDim * MIN_START_SEPARATION_RATIO);
  const minLineSep = Math.floor(maxDim * MIN_START_LINE_SEPARATION_RATIO);

  // Try to find two good start locations far apart
  for (let attempt = 0; attempt < 500; attempt++) {
    const x = rng.nextInt(4, width - 5);
    const y = rng.nextInt(4, height - 5);
    const idx = y * width + x;

    if (!TILE_DEFS[tiles[idx]].buildable) continue;

    // Check buildable area
    if (!hasBuildableArea(tiles, width, height, x, y, MIN_BUILD_AREA)) continue;

    if (starts.length === 0) {
      starts.push({ x, y });
    } else {
      const dist = vecDist(starts[0], { x, y });
      const lineDist = vecManhattan(starts[0], { x, y });
      if (dist >= minSep && lineDist >= minLineSep) {
        starts.push({ x, y });
        break;
      }
    }
  }

  // Fallback if we didn't find two good starts
  if (starts.length < 2) {
    const fallback1 = { x: Math.floor(width * 0.2), y: Math.floor(height * 0.2) };
    const fallback2 = { x: Math.floor(width * 0.8), y: Math.floor(height * 0.8) };
    // Find nearest walkable tiles
    const tempMap = { width, height, tiles, walkable: makeWalkable(tiles, width, height),
      fog: { humans: [], orcs: [] }, startLocations: { humans: fallback1, orcs: fallback2 }, level: 0 };
    const w1 = findNearestWalkable(tempMap, fallback1.x, fallback1.y) ?? fallback1;
    const w2 = findNearestWalkable(tempMap, fallback2.x, fallback2.y) ?? fallback2;
    starts.length = 0;
    starts.push(w1, w2);
  }

  return starts;
}

/** Add water/rock constraints to the map for harder levels */
function constrainTerrain(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
  roughness: number,
): TileType[] {
  const result = [...tiles];
  for (let i = 0; i < roughness; i++) {
    const x = rng.nextInt(2, width - 3);
    const y = rng.nextInt(2, height - 3);
    const idx = y * width + x;
    if (result[idx] === 'grass' || result[idx] === 'dirt') {
      result[idx] = rng.next() < 0.5 ? 'water' : 'rock';
    }
  }
  return result;
}

/**
 * Carve a land corridor between two points to guarantee reachability.
 */
function carveCorridor(
  tiles: TileType[],
  width: number,
  _height: number,
  from: Vec2,
  to: Vec2,
): TileType[] {
  const result = [...tiles];
  let cx = from.x;
  let cy = from.y;

  while (cx !== to.x || cy !== to.y) {
    const idx = cy * width + cx;
    if (result[idx] === 'water' || result[idx] === 'rock') {
      result[idx] = 'grass';
    }

    if (cx < to.x) cx++;
    else if (cx > to.x) cx--;
    if (cy < to.y) cy++;
    else if (cy > to.y) cy--;
  }
  // Also clear the destination
  const toIdx = to.y * width + to.x;
  if (result[toIdx] === 'water' || result[toIdx] === 'rock') {
    result[toIdx] = 'grass';
  }

  return result;
}

/**
 * Generate a complete map for a campaign level.
 */
export function generateMap(
  seed: number,
  level: number,
): GameMap {
  const size = LEVEL_MAP_SIZES[level] ?? LEVEL_MAP_SIZES[0];
  const { width, height } = size;
  const mapSeed = (seed * 31 + level * 17) >>> 0;
  const rng = createPRNG(mapSeed);

  // Generate base terrain with WFC
  let tiles = runWFC(width, height, rng);

  // Add terrain constraints for harder levels
  const roughness = LEVEL_TERRAIN_ROUGHNESS[level] ?? 0;
  tiles = constrainTerrain(tiles, width, height, rng, roughness);

  // Find start locations
  const starts = findStartLocations(tiles, width, height, rng);

  // Ensure reachability between starts
  if (starts.length >= 2) {
    tiles = carveCorridor(tiles, width, height, starts[0], starts[1]);
  }

  // Ensure resources near starts
  tiles = ensureGoldMines(tiles, width, height, rng, 4 + level);
  tiles = ensureForestNearStarts(tiles, width, height, starts, rng);

  // Make walkable array
  const walkable = makeWalkable(tiles, width, height);

  // Create fog arrays
  const fog: Record<Faction, FogState[]> = {
    humans: makeFog(width, height),
    orcs: makeFog(width, height),
  };

  // Set start locations
  const startLocations: Record<Faction, Vec2> = {
    humans: starts[0] ?? { x: 5, y: 5 },
    orcs: starts[1] ?? { x: width - 6, y: height - 6 },
  };

  return {
    width,
    height,
    tiles,
    walkable,
    fog,
    startLocations,
    level,
  };
}

/**
 * Wave Function Collapse map generator.
 * Minimal-entropy cell selection with adjacency-constraint propagation
 * over a weighted tile set.
 */

import type { PRNG } from '../core/prng';
import type { TileType } from '../core/types';
import { ALL_TILE_TYPES, TILE_DEFS, tilesAdjacentAllowed } from '../core/tiles';
import { createPRNG } from '../core/prng';

interface WFCell {
  options: Set<TileType>;
  collapsed: TileType | null;
  entropy: number;
}

interface WFCGrid {
  width: number;
  height: number;
  cells: WFCell[];
}

function cellIndex(grid: WFCGrid, x: number, y: number): number {
  return y * grid.width + x;
}

function inBounds(grid: WFCGrid, x: number, y: number): boolean {
  return x >= 0 && x < grid.width && y >= 0 && y < grid.height;
}

/** Calculate Shannon entropy approximation from tile weights */
function calcEntropy(options: Set<TileType>): number {
  if (options.size <= 1) return 0;
  let sumW = 0;
  let sumWLogW = 0;
  for (const t of options) {
    const w = TILE_DEFS[t].weight;
    if (w <= 0) continue;
    sumW += w;
    sumWLogW += w * Math.log(w);
  }
  if (sumW <= 0) return 0;
  return Math.log(sumW) - sumWLogW / sumW;
}

/** Initialize the grid with all options open */
function initGrid(width: number, height: number): WFCGrid {
  const cells: WFCell[] = [];
  const initialOptions = new Set<TileType>(
    ALL_TILE_TYPES.filter(t => TILE_DEFS[t].weight > 0),
  );
  for (let i = 0; i < width * height; i++) {
    cells.push({
      options: new Set(initialOptions),
      collapsed: null,
      entropy: calcEntropy(initialOptions),
    });
  }
  return { width, height, cells };
}

/** Cardinal + diagonal neighbor offsets */
const NEIGHBOR_DIRS = [
  { x: 0, y: -1 }, { x: 1, y: 0 }, { x: 0, y: 1 }, { x: -1, y: 0 },
  { x: 1, y: -1 }, { x: 1, y: 1 }, { x: -1, y: 1 }, { x: -1, y: -1 },
];

/** Get valid options for neighbor given constraints */
function getValidNeighborOptions(
  selfOptions: Set<TileType>,
  neighborX: number,
  neighborY: number,
  selfX: number,
  selfY: number,
  grid: WFCGrid,
): Set<TileType> {
  const valid = new Set<TileType>();
  const dx = neighborX - selfX;
  const dy = neighborY - selfY;

  for (const neighborType of ALL_TILE_TYPES) {
    if (TILE_DEFS[neighborType].weight <= 0) continue;
    let allowed = false;
    for (const selfType of selfOptions) {
      if (!tilesAdjacentAllowed(selfType, neighborType)) continue;
      if (dx !== 0 && dy !== 0) {
        // Diagonal: check both cardinal intermediates
        const mid1Ok = !inBounds(grid, selfX + dx, selfY) ||
          grid.cells[cellIndex(grid, selfX + dx, selfY)].options.size > 0;
        const mid2Ok = !inBounds(grid, selfX, selfY + dy) ||
          grid.cells[cellIndex(grid, selfX, selfY + dy)].options.size > 0;
        if (mid1Ok || mid2Ok) { allowed = true; break; }
      } else {
        allowed = true;
        break;
      }
    }
    if (allowed) valid.add(neighborType);
  }
  return valid;
}

/** Propagate constraints from a collapsed cell through the grid */
function propagate(grid: WFCGrid, startX: number, startY: number): boolean {
  const stack: Array<{ x: number; y: number }> = [{ x: startX, y: startY }];

  while (stack.length > 0) {
    const { x, y } = stack.pop() as { x: number; y: number };
    const selfCell = grid.cells[cellIndex(grid, x, y)];

    for (const dir of NEIGHBOR_DIRS) {
      const nx = x + dir.x;
      const ny = y + dir.y;
      if (!inBounds(grid, nx, ny)) continue;

      const neighborCell = grid.cells[cellIndex(grid, nx, ny)];
      if (neighborCell.collapsed !== null) continue;

      const validOptions = getValidNeighborOptions(
        selfCell.options, nx, ny, x, y, grid,
      );

      let changed = false;
      for (const opt of neighborCell.options) {
        if (!validOptions.has(opt)) {
          neighborCell.options.delete(opt);
          changed = true;
        }
      }

      if (changed) {
        neighborCell.entropy = calcEntropy(neighborCell.options);
        if (neighborCell.options.size === 0) return false; // contradiction
        stack.push({ x: nx, y: ny });
      }
    }
  }
  return true;
}

/** Pick the uncollapsed cell with minimum entropy */
function pickMinEntropyCell(grid: WFCGrid, rng: PRNG): { x: number; y: number } | null {
  let minEntropy = Infinity;
  let candidates: Array<{ x: number; y: number }> = [];

  for (let y = 0; y < grid.height; y++) {
    for (let x = 0; x < grid.width; x++) {
      const cell = grid.cells[cellIndex(grid, x, y)];
      if (cell.collapsed !== null) continue;
      if (cell.options.size === 0) continue;

      if (cell.entropy < minEntropy - 0.001) {
        minEntropy = cell.entropy;
        candidates = [{ x, y }];
      } else if (Math.abs(cell.entropy - minEntropy) < 0.001) {
        candidates.push({ x, y });
      }
    }
  }

  if (candidates.length === 0) return null;
  return candidates[rng.nextInt(0, candidates.length - 1)];
}

/** Collapse a cell to a weighted random option */
function collapseCell(grid: WFCGrid, x: number, y: number, rng: PRNG): void {
  const cell = grid.cells[cellIndex(grid, x, y)];
  const options = [...cell.options];
  if (options.length === 0) return;

  let totalWeight = 0;
  for (const opt of options) {
    totalWeight += TILE_DEFS[opt].weight;
  }

  let roll = rng.nextFloat(0, totalWeight);
  for (const opt of options) {
    roll -= TILE_DEFS[opt].weight;
    if (roll <= 0) {
      cell.collapsed = opt;
      cell.options = new Set([opt]);
      cell.entropy = 0;
      return;
    }
  }
  // Fallback
  const last = options[options.length - 1];
  cell.collapsed = last;
  cell.options = new Set([last]);
  cell.entropy = 0;
}

/** Run the full WFC algorithm */
export function runWFC(
  width: number,
  height: number,
  rng: PRNG,
): TileType[] {
  const grid = initGrid(width, height);
  let maxIterations = width * height * 10;

  while (maxIterations-- > 0) {
    const pos = pickMinEntropyCell(grid, rng);
    if (!pos) break;

    collapseCell(grid, pos.x, pos.y, rng);
    const ok = propagate(grid, pos.x, pos.y);
    if (!ok) {
      // Contradiction — restart with a new sub-seed
      return runWFC(width, height, createPRNG(rng.nextInt(0, 2147483647)));
    }
  }

  // Fill any remaining uncollapsed cells with grass
  const tiles: TileType[] = [];
  for (let i = 0; i < width * height; i++) {
    const cell = grid.cells[i];
    tiles.push(cell.collapsed ?? 'grass');
  }
  return tiles;
}

/**
 * Post-WFC constraint: add gold mines in clearings near potential start areas.
 * Ensures at least minMines mines exist in the map.
 */
export function ensureGoldMines(
  tiles: TileType[],
  width: number,
  height: number,
  rng: PRNG,
  minMines: number = 4,
): TileType[] {
  const result = [...tiles];
  let mineCount = result.filter(t => t === 'goldMine').length;

  while (mineCount < minMines) {
    // Find a grass or dirt tile that's not too close to edges
    for (let attempts = 0; attempts < 200 && mineCount < minMines; attempts++) {
      const x = rng.nextInt(3, width - 4);
      const y = rng.nextInt(3, height - 4);
      const idx = y * width + x;
      if (result[idx] !== 'grass' && result[idx] !== 'dirt') continue;

      // Check that surrounding area is mostly walkable
      let clearCount = 0;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          const nx = x + dx;
          const ny = y + dy;
          if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;
          const t = result[ny * width + nx];
          if (t === 'grass' || t === 'dirt') clearCount++;
        }
      }
      if (clearCount >= 15) {
        result[idx] = 'goldMine';
        mineCount++;
      }
    }
    // If we failed to place enough after 200 attempts each iteration,
    // force-place at a known grass tile
    if (mineCount < minMines) {
      for (let y = 5; y < height - 5 && mineCount < minMines; y += 10) {
        for (let x = 5; x < width - 5 && mineCount < minMines; x += 10) {
          const idx = y * width + x;
          if (result[idx] === 'grass' || result[idx] === 'dirt') {
            result[idx] = 'goldMine';
            mineCount++;
          }
        }
      }
      break; // Prevent infinite loop
    }
  }
  return result;
}

/**
 * Ensure forest tiles exist near start areas for wood harvesting.
 */
export function ensureForestNearStarts(
  tiles: TileType[],
  width: number,
  height: number,
  starts: Array<{ x: number; y: number }>,
  rng: PRNG,
): TileType[] {
  const result = [...tiles];
  for (const start of starts) {
    // Place a line of forest within 15 tiles of the start
    let placed = false;
    for (let r = 5; r <= 12; r++) {
      for (let attempts = 0; attempts < 20; attempts++) {
        const angle = rng.nextFloat(0, Math.PI * 2);
        const fx = Math.round(start.x + r * Math.cos(angle));
        const fy = Math.round(start.y + r * Math.sin(angle));
        if (fx < 1 || fx >= width - 1 || fy < 1 || fy >= height - 1) continue;
        const idx = fy * width + fx;
        if (result[idx] !== 'grass' && result[idx] !== 'dirt') continue;
        result[idx] = 'forest';
        placed = true;
        // Place a few more forest tiles nearby for a cluster
        for (let dr = 0; dr < 3; dr++) {
          const ddx = rng.nextInt(-1, 1);
          const ddy = rng.nextInt(-1, 1);
          const nx = fx + ddx;
          const ny = fy + ddy;
          if (nx < 1 || nx >= width - 1 || ny < 1 || ny >= height - 1) continue;
          const nidx = ny * width + nx;
          if (result[nidx] === 'grass' || result[nidx] === 'dirt') {
            result[nidx] = 'forest';
          }
        }
        break;
      }
      if (placed) break;
    }
  }
  return result;
}

/**
 * Tests for A* pathfinding.
 */

import { describe, it, expect } from 'vitest';
import { findPath, isReachable, findNearestWalkable } from '../src/core/pathfinding';
import type { GameMap, FogState } from '../src/core/types';

function makeTestMap(
  width: number,
  height: number,
  walkable: boolean[],
): GameMap {
  return {
    width,
    height,
    tiles: new Array(width * height).fill('grass'),
    walkable,
    fog: {
      humans: new Array<FogState>(width * height).fill('visible'),
      orcs: new Array<FogState>(width * height).fill('visible'),
    },
    startLocations: { humans: { x: 0, y: 0 }, orcs: { x: width - 1, y: height - 1 } },
    level: 0,
  };
}

describe('Pathfinding', () => {
  it('should find shortest path on open grid', () => {
    const w = 10;
    const h = 10;
    const walkable = new Array(w * h).fill(true);
    const map = makeTestMap(w, h, walkable);

    const path = findPath(map, 0, 0, 9, 9);
    expect(path).not.toBeNull();
    if (path) {
      expect(path.length).toBeGreaterThan(0);
      expect(path[path.length - 1]).toEqual({ x: 9, y: 9 });
    }
  });

  it('should not cut through blocked diagonals', () => {
    // Create a map where diagonal movement would cut through blocked tiles
    const w = 5;
    const h = 5;
    const walkable = new Array(w * h).fill(true);
    // Block the tiles that would be adjacent to a diagonal move
    walkable[1 * w + 1] = false; // Block (1,1)
    walkable[1 * w + 2] = false; // Block (2,1)
    walkable[2 * w + 1] = false; // Block (1,2)

    const map = makeTestMap(w, h, walkable);
    const path = findPath(map, 0, 0, 2, 2);

    // Should not be able to move diagonally through blocked corners
    if (path) {
      for (let i = 1; i < path.length; i++) {
        const prev = path[i - 1];
        const curr = path[i];
        const dx = Math.abs(curr.x - prev.x);
        const dy = Math.abs(curr.y - prev.y);
        expect(dx).toBeLessThanOrEqual(1);
        expect(dy).toBeLessThanOrEqual(1);
      }
    }
  });

  it('should report unreachable targets as null', () => {
    const w = 5;
    const h = 5;
    const walkable = new Array(w * h).fill(true);
    // Create a wall separating start from target
    for (let y = 0; y < h; y++) {
      walkable[y * w + 2] = false;
    }
    const map = makeTestMap(w, h, walkable);

    const path = findPath(map, 0, 0, 4, 4);
    expect(path).toBeNull();
  });

  it('should handle same start and target', () => {
    const w = 5;
    const h = 5;
    const walkable = new Array(w * h).fill(true);
    const map = makeTestMap(w, h, walkable);

    const path = findPath(map, 2, 2, 2, 2);
    expect(path).toEqual([]);
  });

  it('should find nearest walkable tile', () => {
    const w = 5;
    const h = 5;
    const walkable = new Array(w * h).fill(true);
    walkable[2 * w + 2] = false; // Block center

    const map = makeTestMap(w, h, walkable);
    const nearest = findNearestWalkable(map, 2, 2);

    expect(nearest).not.toBeNull();
    if (nearest) {
      expect(nearest.x !== 2 || nearest.y !== 2).toBe(true);
    }
  });

  it('isReachable should return true for reachable targets', () => {
    const w = 10;
    const h = 10;
    const walkable = new Array(w * h).fill(true);
    const map = makeTestMap(w, h, walkable);

    expect(isReachable(map, 0, 0, 9, 9)).toBe(true);
  });

  it('isReachable should return false for unreachable targets', () => {
    const w = 5;
    const h = 5;
    const walkable = new Array(w * h).fill(true);
    for (let y = 0; y < h; y++) {
      walkable[y * w + 2] = false;
    }
    const map = makeTestMap(w, h, walkable);

    expect(isReachable(map, 0, 0, 4, 4)).toBe(false);
  });
});

/**
 * Tests for determinism: same seed + same orders = same state.
 */

import { describe, it, expect } from 'vitest';
import { initGame, gameTick, serializeState } from '../src/sim/game';
import type { GameConfig, Faction } from '../src/core/types';

describe('Determinism', () => {
  it('should produce identical state from same seed and orders', () => {
    const config: GameConfig = {
      seed: 42,
      level: 0,
      playerFaction: 'humans',
      difficulty: 1,
    };

    const state1 = initGame(config);
    const state2 = initGame(config);

    // Step both simulations
    for (let i = 0; i < 1000; i++) {
      gameTick(state1);
      gameTick(state2);
    }

    const serialized1 = serializeState(state1);
    const serialized2 = serializeState(state2);

    expect(serialized1).toBe(serialized2);
  });

  it('should produce different maps for different seeds', () => {
    const config1: GameConfig = { seed: 42, level: 0, playerFaction: 'humans', difficulty: 1 };
    const config2: GameConfig = { seed: 43, level: 0, playerFaction: 'humans', difficulty: 1 };

    const state1 = initGame(config1);
    const state2 = initGame(config2);

    // Check that maps are different
    const map1 = state1.map.tiles.join(',');
    const map2 = state2.map.tiles.join(',');

    expect(map1).not.toBe(map2);
  });

  it('should produce identical maps for same seed across different initializations', () => {
    const config: GameConfig = { seed: 12345, level: 0, playerFaction: 'humans', difficulty: 1 };

    const state1 = initGame(config);
    const state2 = initGame(config);

    const map1 = state1.map.tiles.join(',');
    const map2 = state2.map.tiles.join(',');

    expect(map1).toBe(map2);
  });

  it('should have no NaN or non-finite values in state', () => {
    const config: GameConfig = { seed: 42, level: 0, playerFaction: 'humans', difficulty: 1 };
    const state = initGame(config);

    // Step for a while
    for (let i = 0; i < 500; i++) {
      gameTick(state);
    }

    // Check resources
    for (const faction of ['humans', 'orcs'] as Faction[]) {
      expect(Number.isFinite(state.resources[faction].gold)).toBe(true);
      expect(Number.isFinite(state.resources[faction].wood)).toBe(true);
      expect(state.resources[faction].gold).toBeGreaterThanOrEqual(0);
      expect(state.resources[faction].wood).toBeGreaterThanOrEqual(0);
    }

    // Check entities
    for (const entity of state.entities) {
      expect(Number.isFinite(entity.x)).toBe(true);
      expect(Number.isFinite(entity.y)).toBe(true);
      expect(Number.isFinite(entity.hp)).toBe(true);
      expect(entity.hp).toBeGreaterThanOrEqual(0);
    }
  });
});

