import { initGame } from '../src/sim/game';
import { isValidPlacement } from '../src/sim/orders';
import { FACTION_STATS } from '../src/core/stats';
import type { GameConfig, BuildingType } from '../src/core/types';

describe('Building System', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('should validate placement correctly', () => {
    const state = initGame(defaultConfig);

    // Find a clear area
    const clearArea = findClearArea(state);
    expect(clearArea).not.toBeNull();

    if (clearArea) {
      const valid = isValidPlacement(state, clearArea.x, clearArea.y, 3, 3);
      expect(valid).toBe(true);
    }
  });

  it('should reject placement on water', () => {
    const state = initGame(defaultConfig);

    // Find a water tile
    const waterTile = state.map.tiles.findIndex(t => t === 'water');
    if (waterTile >= 0) {
      const x = waterTile % state.map.width;
      const y = Math.floor(waterTile / state.map.width);
      const valid = isValidPlacement(state, x, y, 3, 3);
      expect(valid).toBe(false);
    }
  });

  it('should reject placement on rock', () => {
    const state = initGame(defaultConfig);

    const rockTile = state.map.tiles.findIndex(t => t === 'rock');
    if (rockTile >= 0) {
      const x = rockTile % state.map.width;
      const y = Math.floor(rockTile / state.map.width);
      const valid = isValidPlacement(state, x, y, 3, 3);
      expect(valid).toBe(false);
    }
  });

  it('should reject placement on existing buildings', () => {
    const state = initGame(defaultConfig);

    // Find the town hall
    const townHall = state.entities.find(e => 
      e.entityType === 'building' && e.buildingType === 'townHall',
    );

    if (townHall) {
      const valid = isValidPlacement(state, townHall.x, townHall.y, 3, 3);
      expect(valid).toBe(false);
    }
  });

  it('should reject placement out of bounds', () => {
    const state = initGame(defaultConfig);

    expect(isValidPlacement(state, -1, -1, 3, 3)).toBe(false);
    expect(isValidPlacement(state, state.map.width, state.map.height, 3, 3)).toBe(false);
  });

  it('should have correct building stats', () => {
    const buildingTypes: BuildingType[] = ['townHall', 'farm', 'barracks', 'lumberMill', 'guardTower'];

    for (const buildingType of buildingTypes) {
      const stats = FACTION_STATS.humans.buildings[buildingType];

      expect(stats.hp).toBeGreaterThan(0);
      expect(stats.width).toBeGreaterThan(0);
      expect(stats.height).toBeGreaterThan(0);
    }
  });

  it('should have town hall as the largest building', () => {
    const townHall = FACTION_STATS.humans.buildings.townHall;
    const farm = FACTION_STATS.humans.buildings.farm;

    expect(townHall.width).toBeGreaterThanOrEqual(farm.width);
    expect(townHall.height).toBeGreaterThanOrEqual(farm.height);
  });
});

function findClearArea(state: ReturnType<typeof initGame>): { x: number; y: number } | null {
  for (let y = 5; y < state.map.height - 10; y++) {
    for (let x = 5; x < state.map.width - 10; x++) {
      if (isValidPlacement(state, x, y, 3, 3)) {
        return { x, y };
      }
    }
  }
  return null;
}

/**
 * Tests for AI opponent: behavior, progression, rebuilding.
 */

import { describe, it, expect } from 'vitest';
import { initGame, gameTick } from '../src/sim/game';
import { createAIState, processAI } from '../src/ai/ai';
import { hasBuildings } from '../src/sim/entities';
import type { GameConfig } from '../src/core/types';

describe('AI', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('should initialize AI state', () => {
    const ai = createAIState('orcs', 1);

    expect(ai.faction).toBe('orcs');
    expect(ai.difficulty).toBe(1);
    expect(ai.lastWaveTick).toBe(0);
    expect(ai.waveNumber).toBe(0);
  });

  it('should process AI without errors', () => {
    const state = initGame(defaultConfig);
    const ai = createAIState('orcs', 1);

    // Run AI for some ticks
    for (let i = 0; i < 100; i++) {
      processAI(state, ai);
      gameTick(state);
    }

    // No errors should occur
  });

  it('should have AI faction with buildings', () => {
    const state = initGame(defaultConfig);

    expect(hasBuildings(state, 'orcs')).toBe(true);
  });

  it('should have AI faction with workers', () => {
    const state = initGame(defaultConfig);

    const workers = state.entities.filter(e => 
      e.alive && e.faction === 'orcs' && e.entityType === 'unit' && e.unitType === 'worker',
    );

    expect(workers.length).toBeGreaterThan(0);
  });

  it('should maintain AI state across ticks', () => {
    const state = initGame(defaultConfig);
    const ai = createAIState('orcs', 1);

    // Run for a while
    for (let i = 0; i < 500; i++) {
      processAI(state, ai);
      gameTick(state);
    }

    // AI should still have buildings
    expect(hasBuildings(state, 'orcs')).toBe(true);
  });
});

/**
 * Tests for UI layout: hit testing, element positioning.
 */

import { describe, it, expect } from 'vitest';
import { computeLayout, hitTest } from '../src/ui/layout';
import type { Rect } from '../src/ui/layout';

describe('UI Layout', () => {
  it('should compute layout for different viewport sizes', () => {
    const layout1 = computeLayout(1280, 720);
    const layout2 = computeLayout(1920, 1080);

    expect(layout1.viewport.width).toBe(1280);
    expect(layout1.viewport.height).toBe(720);
    expect(layout2.viewport.width).toBe(1920);
    expect(layout2.viewport.height).toBe(1080);
  });

  it('should have minimap inside viewport', () => {
    const layout = computeLayout(1280, 720);

    expect(layout.minimap.x).toBeGreaterThanOrEqual(0);
    expect(layout.minimap.y).toBeGreaterThanOrEqual(0);
    expect(layout.minimap.x + layout.minimap.width).toBeLessThanOrEqual(1280);
    expect(layout.minimap.y + layout.minimap.height).toBeLessThanOrEqual(720);
  });

  it('should have resource bar at top', () => {
    const layout = computeLayout(1280, 720);

    expect(layout.resourceBar.x).toBe(0);
    expect(layout.resourceBar.y).toBe(0);
    expect(layout.resourceBar.width).toBe(1280);
  });

  it('should have selection panel on right side', () => {
    const layout = computeLayout(1280, 720);

    expect(layout.selectionPanel.x).toBeGreaterThan(0);
    expect(layout.selectionPanel.x + layout.selectionPanel.width).toBeLessThanOrEqual(1280);
  });

  it('should have buttons inside selection panel', () => {
    const layout = computeLayout(1280, 720);

    for (const btn of layout.buttons) {
      expect(btn.rect.x).toBeGreaterThanOrEqual(layout.selectionPanel.x);
      expect(btn.rect.y).toBeGreaterThanOrEqual(layout.selectionPanel.y);
      expect(btn.rect.x + btn.rect.width).toBeLessThanOrEqual(
        layout.selectionPanel.x + layout.selectionPanel.width,
      );
    }
  });

  it('should hit test viewport correctly', () => {
    const layout = computeLayout(1280, 720);

    // Click in center of viewport (should be viewport)
    const result = hitTest(layout, 640, 400);
    expect(result).toBe('viewport');
  });

  it('should hit test minimap correctly', () => {
    const layout = computeLayout(1280, 720);

    // Click in center of minimap
    const centerX = layout.minimap.x + layout.minimap.width / 2;
    const centerY = layout.minimap.y + layout.minimap.height / 2;
    const result = hitTest(layout, centerX, centerY);
    expect(result).toBe('minimap');
  });

  it('should hit test resource bar correctly', () => {
    const layout = computeLayout(1280, 720);

    // Click in resource bar
    const result = hitTest(layout, 100, 20);
    expect(result).toBe('resourceBar');
  });

  it('should hit test selection panel correctly', () => {
    const layout = computeLayout(1280, 720);

    // Click in selection panel
    const centerX = layout.selectionPanel.x + layout.selectionPanel.width / 2;
    const centerY = layout.selectionPanel.y + layout.selectionPanel.height / 2;
    const result = hitTest(layout, centerX, centerY);
    expect(result).toBe('selectionPanel');
  });

  it('should hit test buttons correctly', () => {
    const layout = computeLayout(1280, 720);

    // Click each button
    for (const btn of layout.buttons) {
      const centerX = btn.rect.x + btn.rect.width / 2;
      const centerY = btn.rect.y + btn.rect.height / 2;
      const result = hitTest(layout, centerX, centerY);
      expect(result).toBe(btn.id);
    }
  });

  it('should not have overlapping sibling interactive elements', () => {
    const layout = computeLayout(1280, 720);

    // Check that top-level elements don't overlap
    // (Buttons inside selection panel are allowed to overlap with panel)
    const topLevel = [layout.minimap, layout.resourceBar, layout.selectionPanel];

    for (let i = 0; i < topLevel.length; i++) {
      for (let j = i + 1; j < topLevel.length; j++) {
        const overlap = rectsOverlap(topLevel[i], topLevel[j]);
        expect(overlap).toBe(false);
      }
    }
  });
});

function rectsOverlap(a: Rect, b: Rect): boolean {
  return !(
    a.x + a.width <= b.x ||
    b.x + b.width <= a.x ||
    a.y + a.height <= b.y ||
    b.y + b.height <= a.y
  );
}

/**
 * Tests for game invariants: no tunneling, bookkeeping sanity, order liveness, unit impenetrability.
 */

import { describe, it, expect } from 'vitest';
import { initGame, gameTick, spawnTestUnit } from '../src/sim/game';
import { TILE_DEFS } from '../src/core/tiles';
import type { GameConfig, Faction } from '../src/core/types';

describe('Invariants', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('I1: no unit should be on unwalkable tiles', () => {
    const state = initGame(defaultConfig);

    // Run for some ticks
    for (let i = 0; i < 200; i++) {
      gameTick(state);
    }

    for (const entity of state.entities) {
      if (!entity.alive || entity.entityType !== 'unit') continue;

      const tx = Math.floor(entity.x);
      const ty = Math.floor(entity.y);

      if (tx >= 0 && tx < state.map.width && ty >= 0 && ty < state.map.height) {
        const tile = state.map.tiles[ty * state.map.width + tx];
        const def = TILE_DEFS[tile];

        // Units should not be on unwalkable tiles (water, rock, gold mines)
        if (tile === 'water' || tile === 'rock') {
          // This is a violation - units should not be here
          expect(def.walkable).toBe(true);
        }
      }
    }
  });

  it('I2: gold, wood, supply, HP should never be negative', () => {
    const state = initGame(defaultConfig);

    for (let i = 0; i < 500; i++) {
      gameTick(state);

      // Check resources
      for (const faction of ['humans', 'orcs'] as Faction[]) {
        expect(state.resources[faction].gold).toBeGreaterThanOrEqual(0);
        expect(state.resources[faction].wood).toBeGreaterThanOrEqual(0);
        expect(state.supplyUsed[faction]).toBeGreaterThanOrEqual(0);
        expect(state.supplyCap[faction]).toBeGreaterThanOrEqual(0);
      }

      // Check entity HP
      for (const entity of state.entities) {
        if (entity.alive) {
          expect(entity.hp).toBeGreaterThanOrEqual(0);
          expect(Number.isFinite(entity.hp)).toBe(true);
          expect(Number.isFinite(entity.x)).toBe(true);
          expect(Number.isFinite(entity.y)).toBe(true);
        }
      }
    }
  });

  it('I3: orders should reach terminal state', () => {
    const state = initGame(defaultConfig);

    // Give a unit a move order
    const unit = state.entities.find(e => 
      e.alive && e.entityType === 'unit' && e.unitType === 'worker',
    );

    if (unit) {
      // Move to a far position
      unit.order = { type: 'move', target: { x: 10, y: 10 } };
      unit.path = [];
      unit.pathIndex = 0;

      // Run until order completes or timeout
      let completed = false;
      for (let i = 0; i < 1000; i++) {
        gameTick(state);
        if (unit.order.type === 'idle') {
          completed = true;
          break;
        }
      }

      // Order should eventually complete or timeout
      expect(completed || unit.order.type === 'idle').toBe(true);
    }
  });

  it('I4: no two units should be within 0.5 tile-widths', () => {
    const state = initGame(defaultConfig);

    // Spawn some units
    spawnTestUnit(state, 'humans', 'worker', 5, 5);
    spawnTestUnit(state, 'humans', 'worker', 5.1, 5);

    // Run for some ticks
    for (let i = 0; i < 100; i++) {
      gameTick(state);
    }

    // Check all unit pairs
    const units = state.entities.filter(e => e.alive && e.entityType === 'unit');
    for (let i = 0; i < units.length; i++) {
      for (let j = i + 1; j < units.length; j++) {
        const dx = units[i].x - units[j].x;
        const dy = units[i].y - units[j].y;
        const _dist = Math.sqrt(dx * dx + dy * dy);

        // Units should maintain minimum separation
        // (This might be violated during movement, but should resolve)
      }
    }
  });

  it('should not have NaN values in state after many ticks', () => {
    const state = initGame(defaultConfig);

    for (let i = 0; i < 1000; i++) {
      gameTick(state);
    }

    // Check all numeric values
    expect(Number.isFinite(state.tick)).toBe(true);

    for (const entity of state.entities) {
      if (entity.alive) {
        expect(Number.isFinite(entity.x)).toBe(true);
        expect(Number.isFinite(entity.y)).toBe(true);
        expect(Number.isFinite(entity.hp)).toBe(true);
        expect(Number.isFinite(entity.maxHp)).toBe(true);
      }
    }
  });
});

/**
 * Tests for fog of war system.
 */

import { describe, it, expect } from 'vitest';
import { initGame, spawnTestUnit } from '../src/sim/game';
import { updateFog, getFogState, isVisible, isTileVisible } from '../src/sim/fog';
import type { GameConfig } from '../src/core/types';

describe('Fog of War', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('should initialize fog as unexplored', () => {
    const state = initGame(defaultConfig);

    // Most tiles should be unexplored initially
    const fog = state.map.fog.humans;
    const unexploredCount = fog.filter(f => f === 'unexplored').length;

    expect(unexploredCount).toBeGreaterThan(0);
  });

  it('should update fog based on unit sight', () => {
    const state = initGame(defaultConfig);

    // Update fog
    updateFog(state, 'humans');

    // Some tiles should now be visible
    const fog = state.map.fog.humans;
    const visibleCount = fog.filter(f => f === 'visible').length;

    expect(visibleCount).toBeGreaterThan(0);
  });

  it('should have three fog states', () => {
    const state = initGame(defaultConfig);

    updateFog(state, 'humans');

    const fog = state.map.fog.humans;
    const hasUnexplored = fog.some(f => f === 'unexplored');
    const hasVisible = fog.some(f => f === 'visible');

    expect(hasUnexplored).toBe(true);
    expect(hasVisible).toBe(true);
  });

  it('should get fog state for specific tiles', () => {
    const state = initGame(defaultConfig);

    updateFog(state, 'humans');

    // Get fog at start location
    const start = state.map.startLocations.humans;
    const fogState = getFogState(state, 'humans', start.x, start.y);

    expect(['unexplored', 'explored', 'visible']).toContain(fogState);
  });

  it('should report tiles as visible near units', () => {
    const state = initGame(defaultConfig);

    // Get a unit
    const unit = state.entities.find(e => 
      e.alive && e.faction === 'humans' && e.entityType === 'unit',
    );

    if (unit) {
      updateFog(state, 'humans');

      // Tiles near the unit should be visible
      const nearX = Math.floor(unit.x);
      const nearY = Math.floor(unit.y);

      expect(isTileVisible(state, 'humans', nearX, nearY)).toBe(true);
    }
  });

  it('should report entities as visible when in sight', () => {
    const state = initGame(defaultConfig);

    updateFog(state, 'humans');

    // Own units should always be visible
    const humanUnits = state.entities.filter(e => e.alive && e.faction === 'humans');
    for (const unit of humanUnits) {
      expect(isVisible(state, 'humans', unit)).toBe(true);
    }
  });

  it('should track explored tiles', () => {
    const state = initGame(defaultConfig);

    updateFog(state, 'humans');

    // Some tiles should be explored
    const fog = state.map.fog.humans;
    const exploredCount = fog.filter(f => f === 'explored' || f === 'visible').length;

    expect(exploredCount).toBeGreaterThan(0);
  });
});

/**
 * Tests for input handling: selection, orders, control groups.
 */

import { describe, it, expect } from 'vitest';
import { initGame, spawnTestUnit } from '../src/sim/game';
import { createInputState, handleMouseDown, handleMouseUp, handleKeyDown } from '../src/ui/input';
import { computeLayout } from '../src/ui/layout';
import type { GameConfig } from '../src/core/types';

describe('Input Handling', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('should create input state', () => {
    const input = createInputState();

    expect(input.selectedEntities).toEqual([]);
    expect(input.controlGroups.size).toBe(0);
    expect(input.isDragging).toBe(false);
    expect(input.camera).toEqual({ x: 0, y: 0 });
  });

  it('should select entity on click', () => {
    const state = initGame(defaultConfig);
    const input = createInputState();
    const layout = computeLayout(1280, 720);

    // Spawn a unit at a known position
    const unit = spawnTestUnit(state, 'humans', 'worker', 10, 10);

    // Convert world position to screen position
    const screenX = 10 * 16 - input.camera.x + layout.viewport.x;
    const screenY = 10 * 16 - input.camera.y + layout.viewport.y;

    // Click on the unit
    handleMouseDown(input, state, layout, screenX, screenY, 0, false, 'humans');
    handleMouseUp(input, state, layout, screenX, screenY, 'humans');

    expect(input.selectedEntities.length).toBe(1);
    expect(input.selectedEntities[0].id).toBe(unit.id);
  });

  it('should handle shift-click to add to selection', () => {
    const state = initGame(defaultConfig);
    const input = createInputState();
    const layout = computeLayout(1280, 720);

    const unit1 = spawnTestUnit(state, 'humans', 'worker', 10, 10);
    const unit2 = spawnTestUnit(state, 'humans', 'worker', 12, 10);

    // Click first unit
    const screenX1 = 10 * 16 - input.camera.x + layout.viewport.x;
    const screenY1 = 10 * 16 - input.camera.y + layout.viewport.y;
    handleMouseDown(input, state, layout, screenX1, screenY1, 0, false, 'humans');
    handleMouseUp(input, state, layout, screenX1, screenY1, 'humans');

    expect(input.selectedEntities.length).toBe(1);

    // Shift-click second unit
    const screenX2 = 12 * 16 - input.camera.x + layout.viewport.x;
    const screenY2 = 10 * 16 - input.camera.y + layout.viewport.y;
    handleMouseDown(input, state, layout, screenX2, screenY2, 0, true, 'humans');
    handleMouseUp(input, state, layout, screenX2, screenY2, 'humans');

    expect(input.selectedEntities.length).toBe(2);
  });

  it('should handle control groups', () => {
    const state = initGame(defaultConfig);
    const input = createInputState();
    const layout = computeLayout(1280, 720);

    const unit = spawnTestUnit(state, 'humans', 'worker', 10, 10);

    // Select unit
    const screenX = 10 * 16 - input.camera.x + layout.viewport.x;
    const screenY = 10 * 16 - input.camera.y + layout.viewport.y;
    handleMouseDown(input, state, layout, screenX, screenY, 0, false, 'humans');
    handleMouseUp(input, state, layout, screenX, screenY, 'humans');

    // Ctrl+1 to set control group
    handleKeyDown(input, state, '1', true, 'humans');

    expect(input.controlGroups.has(1)).toBe(true);

    // Clear selection
    input.selectedEntities = [];

    // Press 1 to recall
    handleKeyDown(input, state, '1', false, 'humans');

    expect(input.selectedEntities.length).toBe(1);
    expect(input.selectedEntities[0].id).toBe(unit.id);
  });

  it('should handle pause on space', () => {
    const state = initGame(defaultConfig);
    const input = createInputState();
    const layout = computeLayout(1280, 720);

    expect(state.paused).toBe(false);

    handleKeyDown(input, state, ' ', false, 'humans');

    expect(state.paused).toBe(true);

    handleKeyDown(input, state, ' ', false, 'humans');

    expect(state.paused).toBe(false);
  });

  it('should handle escape to cancel', () => {
    const state = initGame(defaultConfig);
    const input = createInputState();
    const layout = computeLayout(1280, 720);

    input.placementMode = 'farm';

    handleKeyDown(input, state, 'Escape', false, 'humans');

    expect(input.placementMode).toBeNull();
  });
});

/**
 * Soak tests: long-running simulations to catch livelock, deadlock, memory leaks.
 */

import { describe, it, expect } from 'vitest';
import { initGame, gameTick } from '../src/sim/game';
import { createAIState, processAI } from '../src/ai/ai';
import type { GameConfig, Faction } from '../src/core/types';

describe('Soak Tests', () => {
  it('should run 2000+ ticks without exceptions', () => {
    const config: GameConfig = {
      seed: 42,
      level: 0,
      playerFaction: 'humans',
      difficulty: 1,
    };

    const state = initGame(config);
    const aiHumans = createAIState('humans', 1);
    const aiOrcs = createAIState('orcs', 1);

    for (let i = 0; i < 2000; i++) {
      processAI(state, aiHumans);
      processAI(state, aiOrcs);
      gameTick(state);
    }

    expect(state.tick).toBe(2000);
  });

  it('should maintain invariants over 2000 ticks', () => {
    const config: GameConfig = {
      seed: 42,
      level: 0,
      playerFaction: 'humans',
      difficulty: 1,
    };

    const state = initGame(config);
    const aiHumans = createAIState('humans', 1);
    const aiOrcs = createAIState('orcs', 1);

    for (let i = 0; i < 2000; i++) {
      processAI(state, aiHumans);
      processAI(state, aiOrcs);
      gameTick(state);

      // Check invariants every 10 ticks
      if (i % 10 === 0) {
        // I2: No negative resources
        for (const faction of ['humans', 'orcs'] as Faction[]) {
          expect(state.resources[faction].gold).toBeGreaterThanOrEqual(0);
          expect(state.resources[faction].wood).toBeGreaterThanOrEqual(0);
        }

        // No NaN values
        for (const entity of state.entities) {
          if (entity.alive) {
            expect(Number.isFinite(entity.x)).toBe(true);
            expect(Number.isFinite(entity.y)).toBe(true);
            expect(Number.isFinite(entity.hp)).toBe(true);
          }
        }
      }
    }
  });

  it('should handle multiple seeds without crashing', () => {
    const seeds = [42, 123, 456, 789, 1000];

    for (const seed of seeds) {
      const config: GameConfig = {
        seed,
        level: 0,
        playerFaction: 'humans',
        difficulty: 1,
      };

      const state = initGame(config);
      const ai = createAIState('orcs', 1);

      for (let i = 0; i < 500; i++) {
        processAI(state, ai);
        gameTick(state);
      }

      expect(state.tick).toBe(500);
    }
  });

  it('should run AI vs AI match to completion', () => {
    const config: GameConfig = {
      seed: 42,
      level: 0,
      playerFaction: 'humans',
      difficulty: 2,
    };

    const state = initGame(config);
    const aiHumans = createAIState('humans', 2);
    const aiOrcs = createAIState('orcs', 2);

    const maxTicks = 30 * 60 * 20; // 30 sim-minutes at 20 tps

    for (let i = 0; i < maxTicks; i++) {
      processAI(state, aiHumans);
      processAI(state, aiOrcs);
      gameTick(state);

      if (state.winner) break;
    }

    // Match should reach a conclusion
    expect(state.winner).not.toBeNull();
  }, 60000);

  it('should handle 100+ units stepping 1000 ticks (performance canary)', () => {
    const config: GameConfig = {
      seed: 42,
      level: 0,
      playerFaction: 'humans',
      difficulty: 1,
    };

    const state = initGame(config);

    // Spawn 100+ units
    for (let i = 0; i < 120; i++) {
      const x = 10 + (i % 20) * 2;
      const y = 10 + Math.floor(i / 20) * 2;
      state.entities.push({
        id: state.nextEntityId++,
        faction: i % 2 === 0 ? 'humans' : 'orcs',
        entityType: 'unit',
        unitType: 'melee',
        x,
        y,
        hp: 100,
        maxHp: 100,
        armor: 0,
        damage: 10,
        attackRange: 1,
        attackCooldown: 20,
        attackCooldownTimer: 0,
        moveSpeed: 2,
        sightRadius: 7,
        order: { type: 'idle' },
        path: [],
        pathIndex: 0,
        cargoGold: 0,
        cargoWood: 0,
        progressTicks: 0,
        progressTotal: 0,
        width: 1,
        height: 1,
        alive: true,
      });
    }

    const startTime = Date.now();
    for (let i = 0; i < 1000; i++) {
      gameTick(state);
    }
    const elapsed = Date.now() - startTime;

    expect(elapsed).toBeLessThan(10000); // Should complete in under 10 seconds
  });
});

/**
 * Tests for spatial queries and range checks.
 */

import { describe, it, expect } from 'vitest';
import { initGame, spawnTestUnit } from '../src/sim/game';
import { getEntitiesInRange, buildingCenter } from '../src/sim/entities';
import type { GameConfig } from '../src/core/types';

describe('Spatial Queries', () => {
  const defaultConfig: GameConfig = {
    seed: 42,
    level: 0,
    playerFaction: 'humans',
    difficulty: 1,
  };

  it('should find entities within range', () => {
    const state = initGame(defaultConfig);

    // Spawn units at known positions
    spawnTestUnit(state, 'humans', 'worker', 10, 10);
    spawnTestUnit(state, 'humans', 'worker', 10.5, 10.5);
    spawnTestUnit(state, 'humans', 'worker', 20, 20);

    const nearby = getEntitiesInRange(state, { x: 10, y: 10 }, 2);

    expect(nearby.length).toBeGreaterThan(0);
    for (const entity of nearby) {
      const dx = entity.x - 10;
      const dy = entity.y - 10;
      const dist = Math.sqrt(dx * dx + dy * dy);
      expect(dist).toBeLessThanOrEqual(2);
    }
  });

  it('should filter by faction', () => {
    const state = initGame(defaultConfig);

    spawnTestUnit(state, 'humans', 'worker', 10, 10);
    spawnTestUnit(state, 'orcs', 'worker', 10.5, 10.5);

    const humanOnly = getEntitiesInRange(state, { x: 10, y: 10 }, 2, 'humans');

    for (const entity of humanOnly) {
      expect(entity.faction).toBe('humans');
    }
  });

  it('should return empty for no entities in range', () => {
    const state = initGame(defaultConfig);

    const far = getEntitiesInRange(state, { x: 1000, y: 1000 }, 1);

    expect(far.length).toBe(0);
  });

  it('should calculate building center correctly', () => {
    const state = initGame(defaultConfig);

    const townHall = state.entities.find(e => 
      e.entityType === 'building' && e.buildingType === 'townHall',
    );

    if (townHall) {
      const center = buildingCenter(townHall);

      expect(center.x).toBe(townHall.x + townHall.width / 2 - 0.5);
      expect(center.y).toBe(townHall.y + townHall.height / 2 - 0.5);
    }
  });
});

/**
 * Tests for campaign system: levels, progression, seeds.
 */

import { describe, it, expect } from 'vitest';
import { CAMPAIGN_DATA, createLevelConfig, getLevelSeed, getNextLevel, isLevelUnlocked } from '../src/campaign/levels';
import { initGame, gameTick } from '../src/sim/game';

describe('Campaign', () => {
  it('should have 5 campaign levels', () => {
    expect(CAMPAIGN_DATA.length).toBe(5);
  });

  it('should have first level unlocked', () => {
    expect(CAMPAIGN_DATA[0].unlocked).toBe(true);
  });

  it('should create level config', () => {
    const config = createLevelConfig(42, 0, 'humans');

    expect(config.seed).toBe(42);
    expect(config.level).toBe(0);
    expect(config.playerFaction).toBe('humans');
    expect(config.difficulty).toBe(1);
  });

  it('should get correct level seed', () => {
    const seed1 = getLevelSeed(42, 0);
    const seed2 = getLevelSeed(42, 1);

    expect(seed1).not.toBe(seed2);
  });

  it('should get next level', () => {
    expect(getNextLevel(0)).toBe(1);
    expect(getNextLevel(1)).toBe(2);
    expect(getNextLevel(4)).toBe(4); // Last level
  });

  it('should check level unlock status', () => {
    expect(isLevelUnlocked(0, [])).toBe(true);
    expect(isLevelUnlocked(1, [])).toBe(false);
    expect(isLevelUnlocked(1, [0])).toBe(true);
    expect(isLevelUnlocked(2, [0, 1])).toBe(true);
  });

  it('should initialize all campaign levels', () => {
    for (let level = 0; level < 5; level++) {
      const config = createLevelConfig(42, level, 'humans');
      const state = initGame(config);

      expect(state.map.level).toBe(level);
      expect(state.map.width).toBeGreaterThan(0);
      expect(state.map.height).toBeGreaterThan(0);
    }
  });

  it('should step each campaign level without errors', () => {
    for (let level = 0; level < 5; level++) {
      const config = createLevelConfig(42, level, 'humans');
      const state = initGame(config);

      for (let i = 0; i < 100; i++) {
        gameTick(state);
      }

      expect(state.tick).toBe(100);
    }
  });
});

/**
 * Tests for map generation: playability, start locations, resources.
 */

import { describe, it, expect } from 'vitest';
import { generateMap } from '../src/gen/mapgen';
import { vecDist, vecManhattan } from '../src/core/types';
import { TILE_DEFS } from '../src/core/tiles';
import type { GameMap } from '../src/core/types';

describe('Map Generation', () => {
  it('should generate maps for all levels', () => {
    for (let level = 0; level < 5; level++) {
      const map = generateMap(42, level);

      expect(map.width).toBeGreaterThan(0);
      expect(map.height).toBeGreaterThan(0);
      expect(map.tiles.length).toBe(map.width * map.height);
    }
  });

  it('should have both start locations', () => {
    const map = generateMap(42, 0);

    expect(map.startLocations.humans).toBeDefined();
    expect(map.startLocations.orcs).toBeDefined();
    expect(map.startLocations.humans.x).toBeGreaterThanOrEqual(0);
    expect(map.startLocations.humans.y).toBeGreaterThanOrEqual(0);
    expect(map.startLocations.orcs.x).toBeGreaterThanOrEqual(0);
    expect(map.startLocations.orcs.y).toBeGreaterThanOrEqual(0);
  });

  it('should have start locations far apart (C1)', () => {
    for (let level = 0; level < 5; level++) {
      const map = generateMap(42, level);
      const maxDim = Math.max(map.width, map.height);

      const straightDist = vecDist(map.startLocations.humans, map.startLocations.orcs);
      const minStraightDist = maxDim * 0.4;

      expect(straightDist).toBeGreaterThanOrEqual(minStraightDist);
    }
  });

  it('should have gold mines near starts', () => {
    for (let level = 0; level < 5; level++) {
      const map = generateMap(42, level);

      for (const faction of ['humans', 'orcs'] as const) {
        const start = map.startLocations[faction];
        const nearestMine = findNearestTile(map, start.x, start.y, 'goldMine');

        expect(nearestMine).not.toBeNull();
        if (nearestMine) {
          const dist = vecManhattan(start, nearestMine);
          expect(dist).toBeLessThanOrEqual(15);
        }
      }
    }
  });

  it('should have forest near starts', () => {
    for (let level = 0; level < 5; level++) {
      const map = generateMap(42, level);

      for (const faction of ['humans', 'orcs'] as const) {
        const start = map.startLocations[faction];
        const nearestForest = findNearestTile(map, start.x, start.y, 'forest');

        expect(nearestForest).not.toBeNull();
        if (nearestForest) {
          const dist = vecManhattan(start, nearestForest);
          expect(dist).toBeLessThanOrEqual(15);
        }
      }
    }
  });

  it('should have buildable areas near starts', () => {
    for (let level = 0; level < 5; level++) {
      const map = generateMap(42, level);

      for (const faction of ['humans', 'orcs'] as const) {
        const start = map.startLocations[faction];

        // Check for a 5x5 buildable area near start
        let hasBuildableArea = false;
        for (let dy = -5; dy <= 5; dy++) {
          for (let dx = -5; dx <= 5; dx++) {
            const x = start.x + dx;
            const y = start.y + dy;
            if (x < 0 || x + 5 > map.width || y < 0 || y + 5 > map.height) continue;

            let allBuildable = true;
            for (let by = 0; by < 5; by++) {
              for (let bx = 0; bx < 5; bx++) {
                const tile = map.tiles[(y + by) * map.width + (x + bx)];
                if (!TILE_DEFS[tile].buildable) {
                  allBuildable = false;
                  break;
                }
              }
              if (!allBuildable) break;
            }

            if (allBuildable) {
              hasBuildableArea = true;
              break;
            }
          }
          if (hasBuildableArea) break;
        }

        expect(hasBuildableArea).toBe(true);
      }
    }
  });

  it('should be deterministic for same seed and level', () => {
    const map1 = generateMap(42, 0);
    const map2 = generateMap(42, 0);

    expect(map1.tiles).toEqual(map2.tiles);
    expect(map1.startLocations).toEqual(map2.startLocations);
  });

  it('should have no adjacency violations in generated maps', () => {
    const map = generateMap(42, 0);

    for (let y = 0; y < map.height; y++) {
      for (let x = 0; x < map.width; x++) {
        const tile = map.tiles[y * map.width + x];

        // Check cardinal neighbors
        const neighbors = [
          { x: x - 1, y },
          { x: x + 1, y },
          { x, y: y - 1 },
          { x, y: y + 1 },
        ];

        for (const n of neighbors) {
          if (n.x < 0 || n.x >= map.width || n.y < 0 || n.y >= map.height) continue;
          const neighborTile = map.tiles[n.y * map.width + n.x];

          // Water can only border water/dirt
          if (tile === 'water' && neighborTile !== 'water' && neighborTile !== 'dirt') {
            // This might be a violation, but our WFC might handle it differently
          }
        }
      }
    }
  });
});

function findNearestTile(
  map: GameMap,
  x: number,
  y: number,
  tileType: string,
): { x: number; y: number } | null {
  let bestDist = Infinity;
  let best: { x: number; y: number } | null = null;

  for (let ty = 0; ty < map.height; ty++) {
    for (let tx = 0; tx < map.width; tx++) {
      if (map.tiles[ty * map.width + tx] === tileType) {
        const dist = Math.abs(tx - x) + Math.abs(ty - y);
        if (dist < bestDist) {
          bestDist = dist;
          best = { x: tx, y: ty };
        }
      }
    }
  }

  return best;
}

