  state: InputState,
  layout: HudLayout,
  screenX: number,
  screenY: number,
): { x: number; y: number } {
  return {
    x: screenX - layout.viewport.x + state.camera.x,
    y: screenY - layout.viewport.y + state.camera.y,
  };
}

